function lab_asegurar_datos(PDO $pdo): void {
    // 0. Cuentas de usuario para el equipo consultor
    $equipoCuentas = [
        ["leandro", "Leandro", "admin", "esquel2026"],
        ["adria", "Adria", "editor", "esquel2026"],
        ["mariela", "Mariela", "editor", "esquel2026"],
        ["francisco", "Francisco", "viewer", "esquel2026"],
        ["agustina", "Agustina", "viewer", "esquel2026"],
        ["noelia", "Noelia", "viewer", "esquel2026"],
        ["cesia", "Cesia", "viewer", "esquel2026"],
    ];
    $insUser = $pdo->prepare("INSERT INTO users (username, password, role) VALUES (?, ?, ?)");
    $checkUser = $pdo->prepare("SELECT 1 FROM users WHERE LOWER(username) = LOWER(?)");
    foreach ($equipoCuentas as $uRow) {
        $checkUser->execute([$uRow[0]]);
        if (!$checkUser->fetchColumn()) {
            $insUser->execute([$uRow[1], password_hash($uRow[3], PASSWORD_DEFAULT), $uRow[2]]);
        }
    }

    // Acceso para el equipo consultor
    $pdo->exec("INSERT OR IGNORE INTO lab_user_access (user_id, granted_by) SELECT id, 1 FROM users WHERE LOWER(username) IN ('leandro', 'adria', 'mariela', 'francisco', 'agustina', 'noelia', 'cesia')");

    // 1. Consultores
    $countCons = (int) $pdo->query("SELECT COUNT(*) FROM lab_consultores")->fetchColumn();
    if ($countCons === 0) {
        $insCons = $pdo->prepare("INSERT INTO lab_consultores (id, nombre, rol, disponibilidad, restricciones, color, activo) VALUES (?, ?, ?, ?, ?, ?, 1)");
        $consultores = [
            ["leandro", "Leandro", "Conducción", "[\"completa\",\"hasta 15:50\",\"completa\",\"hasta 15:50\",\"completa\"]", "No disponible martes y jueves después de las 15:50.", "#132B43"],
            ["adria", "Adria", "Senior", "[\"7–14\",\"7–14\",\"7–14\",\"7–14\",\"7–14\"]", "Única senior con ventana para rutas rurales. Lleva la cartera de territorio.", "#2F7D5D"],
            ["mariela", "Mariela", "Senior", "[\"7–13\",\"7–13\",\"7–13\",\"7–13\",\"7–13\"]", "Cartera urbana sin traslados. Cierre firme a las 13:00.", "#C4442E"],
            ["francisco", "Francisco", "Junior", "[\"8–18\",\"8–18\",\"8–18\",\"8–18\",\"libre\"]", "Facultad de lunes a jueves de 18:00 a 22:00. Fuera por FIT del 24 al 30 de septiembre.", "#4A7FA8"],
            ["agustina", "Agustina", "Junior", "[\"8–18\",\"8–18\",\"8–18\",\"8–18\",\"libre\"]", "Facultad de lunes a jueves de 18:00 a 22:00. Fuera por FIT del 24 al 30 de septiembre.", "#E8A33D"],
            ["noelia", "Noelia", "Junior", "[\"8–18\",\"8–18\",\"8–18\",\"8–18\",\"libre\"]", "Facultad de lunes a jueves de 18:00 a 22:00.", "#8FB8D4"],
            ["cesia", "Cesia", "Junior", "[\"14–20\",\"14–20\",\"8–14\",\"14–20\",\"14–20\"]", "Única mañana libre: miércoles. Su fuerte son los toques de tarde.", "#6B3FA0"],
        ];
        foreach ($consultores as $c) { $insCons->execute($c); }
    }

    // 2. Proyectos de la cohorte
    $proyectos = [
        ["crova", 25, "Los Crovas", "Carlos Javier Crova", "Raíz", 4.22, 1, "leandro", "cesia", "[\"Uno de los 4 o 5 piperos del país. Pieza en el Museo de la Pipa de Ámsterdam y en el Museo del Tabaco de Salta. Miembro de la Asociación de Piperos Interamericana y del Hobbit Pipe Club.\",\"Ya exporta a Francia, Estados Unidos e Italia, y genera turismo de cofradía espontáneo: le llegan clientes desde Santa Cruz, Tierra del Fuego y Neuquén.\",\"Taller, maquinaria e insumos propios. Viabilidad operativa inmediata, sin inversión previa.\",\"Producto con Sello Origen Chubut.\",\"El cuello no es el producto: es difusión y comercialización. No tiene tiempo ni recursos propios y depende de su hijo para el video.\",\"No busca masificar la venta. Quiere movimiento dentro de un nicho definido.\"]", "[\"Camino de acceso al taller severamente deteriorado. Condiciona cualquier visita organizada.\",\"No disponible lunes ni miércoles por la mañana.\",\"Costo y logística de envío internacional, hoy artesanal.\"]", "[{\"t\":\"Monetizar la visita al taller\",\"items\":[\"Cuantificar el tiempo de producción que cede en cada visita.\",\"Guion segmentado: cofrades y coleccionistas por un lado, turistas y familias por otro.\",\"Precio por visita más esquema de escasez: de 3 a 5 días por pieza significa agenda acotada.\"]},{\"t\":\"Contenido y comunicación\",\"items\":[\"Producción audiovisual 4K y dron con equipo de la Subsecretaría, vinculando la pipa al entorno patagónico.\",\"Curaduría del canal de YouTube existente y de las redes.\"]},{\"t\":\"Vinculación institucional y comercial\",\"items\":[\"Presencia con respaldo de Turismo en encuentros locales (Carao, Hotel Tehuelche, CIEFAP), no solo stand.\",\"Circuito de regalo institucional y empresarial.\",\"Gestión del camino de acceso ante el área que corresponda.\"]}]", "[\"Precio de visita guiada fijado y comunicado.\",\"Guion de visita segmentado por público.\",\"Repositorio audiovisual 4K y dron.\",\"Al menos un vínculo institucional o comercial nuevo iniciado.\"]", "{\"estado\":\"completada\",\"titulo\":\"Minuta Cero · Entrevista Inicial de Diagnóstico\",\"fecha\":\"07/09/2026\",\"hora\":\"10:30\",\"lugar\":\"Taller Los Crovas, Esquel\",\"participantes\":[\"Carlos Javier Crova (Titular)\",\"Leandro (Conducción / Senior)\",\"Cesia (Junior)\"],\"resumen\":\"Carlos Javier Crova es uno de los 4 o 5 piperos artesanales en actividad en el país, con piezas en el Museo de la Pipa de Ámsterdam y en el Museo del Tabaco de Salta. Exporta a Francia, EE. UU. e Italia, y genera visitas espontáneas de coleccionistas. El cuello de botella no radica en la maestría técnica sino en la monetización ordenada del tiempo de taller y la estructuración de la experiencia para el visitante.\",\"diagnostico_claves\":[\"Taller propio con maquinaria, herramientas e insumos de primer nivel listos para operar sin requerir inversión previa.\",\"Sello Origen Chubut otorgado y validación internacional en la Asociación Interamericana de Piperos y Hobbit Pipe Club.\",\"Flujo espontáneo de turistas de nicho desde Santa Cruz, Neuquén y Buenos Aires que llegan por boca en boca.\",\"Falta de equipo propio para difusión, producción audiovisual y manejo de redes (depende de la ayuda puntual de su hijo).\"],\"trabas_detectadas\":[\"Camino de acceso al taller severamente deteriorado, lo que condiciona traslados organizados en vehículos bajos.\",\"Cada visita no arancelada consume entre 45 y 90 minutos de fabricación neta, frenando las entregas de exportación.\",\"Logística de envíos internacionales artesanal y con costos variables.\"],\"acuerdos_previos\":[\"Fijar y comunicar una tarifa oficial para visitas guiadas al taller con sistema de cupos y escasez programada.\",\"Segmentar el guion de visita: cofrades y coleccionistas por un lado, familias y turistas curiosos por otro.\",\"Coordinar con la Subsecretaría de Turismo la producción de un banco audiovisual en 4K y tomas de dron en el entorno cordillerano.\",\"Iniciar gestiones ante el área vial correspondiente para el mejoramiento del camino vecinal de acceso.\"],\"citas_textuales\":[\"\\\"No busco masificar la venta ni llenarme de gente en el taller; quiero que quien venga entienda el valor de cada pipa y pague lo que vale.\\\"\",\"\\\"Cada pipa me lleva entre 3 y 5 días de trabajo paciente; si atiendo a alguien gratis, ese día no sale una pipa para afuera.\\\"\"],\"texto_completo\":\"## Minuta Cero: Encuentro Diagnóstico Inicial · Los Crovas\\n\\n**Fecha:** 7 de septiembre de 2026 | **Sede:** Taller Los Crovas, Esquel\\n**Asistentes:** Carlos Javier Crova (Titular), Leandro (Conducción/Senior), Cesia (Junior)\\n\\n### 1. Perfil y Oportunidad Detectada\\nCarlos Javier Crova es uno de los 4 o 5 piperos artesanales del país. Cuenta con piezas en el Museo de la Pipa de Ámsterdam y en el Museo del Tabaco de Salta. Exporta de manera recurrente a Europa y Estados Unidos, con Sello Origen Chubut. Ya genera turismo espontáneo de cofradías y coleccionistas que viajan a Esquel exclusivamente a conocer su espacio.\\n\\n### 2. Cuellos de Botella Relevados\\n- **Monetización de la visita:** Recibir visitantes le quita tiempo de fabricación neta sin un retorno económico directo si no compran una pipa de alta gama.\\n- **Acceso vial:** La calle de ingreso al taller presenta zanjas y pozos que dificultan el arribo de autos de alquiler.\\n- **Comunicación:** Depende de la colaboración de su hijo para registrar videos y alimentar canales digitales.\\n\\n### 3. Compromisos de Arranque\\n1. Establecer el valor arancelado de la visita al taller con reserva previa.\\n2. Definir guion diferenciado para visitantes expertos y público general.\\n3. Articular producción fotográfica y de video con el equipo de comunicación municipal.\\n4. Diseñar propuesta para regalos empresariales e institucionales de alto perfil.\"}"],
        ["haiku", 32, "Haiku Casa de Té", "Estrella Cerocchi", "Acelera", 3.57, 4, "mariela", "agustina", "[\"Puntuación muy alta en la selección, con coincidencia entre todos los evaluadores. Propuesta de valor consolidada.\",\"Cuatro años de trayectoria con interrupciones. Local propio abierto en junio de 2022.\",\"Trabaja sola. Historial de colaboradoras en redes y dificultad declarada para delegar.\",\"Ya hace registro manual de datos, sin sistematizar ni graficar.\",\"El cuello real: nunca logró generar clientes regulares ni comunidad. Se la percibe desde afuera como un lugar cerrado, aunque esté operando.\"]", "[\"En algún momento del año pensó en cerrar. El encuadre es de sostén, no solo técnico: no forzar ritmo ni presión de entregables.\",\"Costeo de conservación en frío: los productos con crema duran dos días.\",\"Resistencia local a reservar. Hay que ajustar el mecanismo, no necesariamente eliminarlo.\"]", "[{\"t\":\"Definir qué es Haiku\",\"items\":[\"Resolver la disyuntiva entre alta gastronomía y espacio de encuentro. No conviven sin fricción.\",\"Una vez definida, ordenar qué se sacrifica en función de esa jerarquía.\"]},{\"t\":\"Cápsulas de experiencia y recurrencia\",\"items\":[\"Formalizar Té de amigas, Haiku al atardecer los viernes y una propuesta de sábados, con precio propio.\",\"Menú fijo mensual, ya probado en julio con buen resultado, como base de la oferta accesible.\"]},{\"t\":\"Comunicación y comunidad\",\"items\":[\"Jerarquía visual en las piezas: mensaje grande y claro primero, marca después.\",\"Pedido activo de etiquetado a clientes en redes.\",\"Sistema simple de registro diario para reemplazar la memoria por datos.\"]}]", "[\"Definición escrita de qué es Haiku y jerarquía de lo que no se toca.\",\"Cápsulas con precio y calendario semanal.\",\"Sistema de registro diario en uso y primer indicador de clientes regulares.\"]", "{\"estado\":\"completada\",\"titulo\":\"Minuta Cero · Entrevista Inicial de Diagnóstico\",\"fecha\":\"23/08/2026\",\"hora\":\"15:00\",\"lugar\":\"Haiku Casa de Té, Esquel\",\"participantes\":[\"Estrella Cerocchi (Titular)\",\"Mariela (Senior)\",\"Agustina (Junior)\"],\"resumen\":\"Propuesta de alta gastronomía y pastelería de té con 4 años de trayectoria y local propio desde junio de 2022. Obtuvo una de las puntuaciones más altas del jurado. Sin embargo, Estrella afronta la operación en soledad, con fatiga de gestión, dificultad para delegar y una barrera de percepción externa: gran parte del público asume que el local está cerrado o que es inalcanzable económicamente.\",\"diagnostico_claves\":[\"Calidad de producto superlativa con insumos de primera línea y recetas exclusivas de té en hebras y pastelería europea.\",\"Operación unipersonal crítica: cocina, atención al cliente, compras, cobros y redes dependen de una sola persona.\",\"Registro diario de ventas manual en cuadernos, sin sistematización en planillas ni métricas de recurrencia.\",\"Falta de una comunidad activa de clientes frecuentes que sostenga los meses de baja turística.\"],\"trabas_detectadas\":[\"Resistencia del público residente a reservar mesa con anticipación, generando picos imprevistos o tardes desiertas.\",\"Costos de mermas y frío: la pastelería fresca con crema tiene una vida útil de solo 48 horas.\",\"Disyuntiva de identidad: tensión no resuelta entre salón de té exclusivo de culto o espacio de encuentro cotidiano accesible.\"],\"acuerdos_previos\":[\"Redactar la definición clara y jerárquica de \\\"Qué es Haiku\\\", acordando qué aspectos de la carta no se tocan y cuáles se flexibilizan.\",\"Lanzar cápsulas de consumo con precio cerrado: \\\"Té de Amigas\\\", \\\"Haiku al Atardecer\\\" (viernes) y Menú Fijo Mensual.\",\"Implementar un sistema diario simple de control de comensales y seguimiento de clientes regulares.\",\"Adecuar la cartelería exterior y comunicación visual para dejar en claro horarios de apertura y precios accesibles.\"],\"citas_textuales\":[\"\\\"En algún momento del año pasado pensé seriamente en cerrar. Me desgasta sentir que pongo el alma en la cocina y la gente pasa por la vereda y piensa que no está abierto.\\\"\",\"\\\"Me cuesta mucho delegar porque siento que nadie va a cuidar el detalle como yo, pero si sigo así me quedo sin salud.\\\"\"],\"texto_completo\":\"## Minuta Cero: Encuentro Diagnóstico Inicial · Haiku Casa de Té\\n\\n**Fecha:** 23 de agosto de 2026 | **Sede:** Haiku Casa de Té, Esquel\\n**Asistentes:** Estrella Cerocchi (Titular), Mariela (Senior), Agustina (Junior)\\n\\n### 1. Perfil y Oportunidad Detectada\\nEmprendimiento gastronómico de alta pastelería con 4 años de trayectoria. Cuenta con equipamiento completo y salón ambientado con identidad propia. Reconocimiento unánime de los evaluadores por la calidad de su oferta.\\n\\n### 2. Cuellos de Botella Relevados\\n- **Fatiga operativa y soledad:** Toda la carga recae en Estrella, desde la producción hasta las redes.\\n- **Barrera de acceso percibida:** La fachada cerrada y la exigencia de reserva previa alejan al consumidor local espontáneo.\\n- **Perecibilidad de insumos:** Pérdida económica en productos frescos durante días de bajo flujo de clientes.\\n\\n### 3. Compromisos de Arranque\\n1. Formalizar un documento de identidad y prioridades para Haiku.\\n2. Armar 2 experiencias paquetizadas con calendario fijo semanal.\\n3. Poner en marcha una plantilla ágil de control de clientes y recurrencia.\\n4. Ajustar la visibilidad de apertura hacia la calle con señalética clara y cálida.\"}"],
        ["tambo", 41, "La casa del tambo", "Sofia Winter", "Raíz", 3.24, 2, "adria", "noelia", "[\"Dos hectáreas en la salida de Trevelin. Fue el primer frigorífico de la zona, fundado por su abuelo, luego conservas de la familia Garitano.\",\"Construcción colonial con sótano grande, abandonada casi 40 años y otros 10 sin uso bajo la propiedad de su padre.\",\"Ubicación estratégica junto al molino, los tulipanes, la cascada y La Floral. Zona antes alejada, hoy con barrios y loteos al frente.\",\"Profesora de equitación (Hípico Argentino, Los Pinos), estudió marketing y trabaja como freelancer en comunicación. Flexibilidad horaria.\",\"Prioridad propia: ordenar ideas y arrancar por los caballos, antes que aromáticas, tours, gallinas u ordeñe.\"]", "[\"Su padre, socio inversor, ausente hasta fin de septiembre: las definiciones de inversión esperan su regreso.\",\"Viaja a Buenos Aires hasta el jueves 16 de septiembre.\",\"Habilitaciones municipales pendientes: servicios, calles y agrimensura por deslindes.\",\"La temporada fuerte es la de tulipanes en octubre. El turismo de invierno viene bajo.\"]", "[{\"t\":\"Operaciones\",\"items\":[\"Priorizar equitación como ingreso de corto plazo que financie la infraestructura mayor.\",\"Armar la pista y regularizar servicios y permisos municipales para actividad ecuestre.\",\"Construir de abajo hacia arriba: empezar con lo que hay, sin esperar la infraestructura ideal.\"]},{\"t\":\"Comercialización\",\"items\":[\"Esquema económico-financiero simplificado para el diálogo con el socio inversor.\",\"Paquetizar la actividad ecuestre en experiencia con guion, no como clase suelta.\"]},{\"t\":\"Comunicación\",\"items\":[\"Portfolio de marketing y contenido, aprovechando su oficio de freelancer.\",\"Discurso de macro destino: integrar a Esquel en la narrativa aunque el predio esté en Trevelin.\"]}]", "[\"Documentación del proyecto y portfolio enviados (comprometido para el 16/9).\",\"Pista de equitación operativa con turnos definidos y permisos en trámite.\",\"Esquema económico-financiero para uso interno con el socio inversor.\",\"Al menos una experiencia ecuestre paquetizada, con guion y precio.\"]", "{\"estado\":\"completada\",\"titulo\":\"Minuta Cero · Entrevista Inicial de Diagnóstico\",\"fecha\":\"07/09/2026\",\"hora\":\"11:30\",\"lugar\":\"Predio La Casa del Tambo, Trevelin\",\"participantes\":[\"Sofía Winter (Titular)\",\"Adria (Senior)\",\"Noelia (Junior)\"],\"resumen\":\"Predio histórico de 2 hectáreas ubicado en el acceso a Trevelin, fundado por el abuelo de Sofía como primer frigorífico de la zona y luego fábrica de conservas Garitano. Sofía es instructora de equitación y licenciada en marketing. El proyecto cuenta con un potencial multipropósito enorme, pero requiere ordenar etapas para no dispersar fondos antes del regreso de su padre y socio inversor.\",\"diagnostico_claves\":[\"Inmueble patrimonial de alto valor arquitectónico con sótano colonial y terreno amplio en zona de expansión turística.\",\"Ubicación estratégica sobre el corredor de tulipanes, viñedos, molino y cascadas de Trevelin.\",\"Conocimiento técnico en equitación y marketing, con disponibilidad horaria flexible para conducir el desarrollo.\",\"Riesgo de sobre-ambición inicial (querer abrir simultáneamente tambo, aromáticas, tours, ordeñe y gastronomía).\"],\"trabas_detectadas\":[\"Socio inversor (su padre) ausente hasta fin de septiembre: las inversiones en infraestructura pesada están pausadas.\",\"Trámites de deslinde, agrimensura y permisos municipales de habilitación pendientes en la Municipalidad de Trevelin.\",\"Fuerte estacionalidad comarcal: concentración en octubre (temporada de tulipanes) y meses de invierno con muy baja demanda.\"],\"acuerdos_previos\":[\"Priorizar la actividad ecuestre y la pista de equitación como primer generador de ingresos inmediatos.\",\"Estructurar un dossier económico-financiero claro para presentarle a su padre a su regreso a fines de septiembre.\",\"Paquetizar la primera experiencia turística a caballo (guionada y con precio cerrado) sin esperar las obras edilicias mayores.\",\"Iniciar gestiones de deslinde y permisos municipales para habilitación turística de actividades al aire libre.\"],\"citas_textuales\":[\"\\\"Si esperamos a restaurar todo el edificio colonial y tener el tambo funcionando no arrancamos nunca; los caballos están y la pista la podemos armar ya.\\\"\",\"\\\"Quiero que mi papá vea números claros y un plan por etapas para que se anime a poner el capital que falta sin miedo.\\\"\"],\"texto_completo\":\"## Minuta Cero: Encuentro Diagnóstico Inicial · La Casa del Tambo\\n\\n**Fecha:** 7 de septiembre de 2026 | **Sede:** Predio La Casa del Tambo, Trevelin\\n**Asistentes:** Sofía Winter (Titular), Adria (Senior), Noelia (Junior)\\n\\n### 1. Perfil y Oportunidad Detectada\\nInmueble histórico de 2 hectáreas con edificio colonial en Trevelin. Propiedad de gran arraigo familiar y valor paisajístico. Sofía aporta perfil profesional en marketing y profesorado de equitación, con dedicación plena al proyecto.\\n\\n### 2. Cuellos de Botella Relevados\\n- **Dependencia de capital:** Definiciones presupuestarias mayores a la espera del socio inversor (su padre).\\n- **Trámites de habilitación:** Regularización de mensura y permisos municipales para actividades abiertas al público.\\n- **Dispersión temática:** Necesidad de enfocar el modelo en un servicio ancla antes de diversificar.\\n\\n### 3. Compromisos de Arranque\\n1. Armar la pista de equitación y el esquema de turnos y clases.\\n2. Presentar plan de inversión por fases para la mesa familiar.\\n3. Paquetizar una experiencia ecuestre con relato histórico y degustación local.\"}"],
        ["flypark", 12, "FLYPARK", "FABRICIO GUGLIELMETTI", "Acelera", 4.22, 4, "leandro", "agustina", "[\"Puesto #1 de Esquel Acelera (Puntaje récord 4.22 / 5.00). Proyecto pionero de estación urbana y modular de dryslope (esquí y snowboard sobre alfombra plástica sintética Powplast) que rompe la estacionalidad invernal y desvincula la práctica deportiva de las concesiones de montaña.\",\"Equipo con trayectoria y solvencia técnica comprobada: creadores y operadores del Snowpark original en La Hoya (2006), respaldados por la Asociación Civil de Deportes de Acción Patagonia Freeride (personería jurídica vigente). Disponen de 100 m² de alfombra modular (30 m² propios + 70 m² financiados por el Plan Galina de Chubut Deportes).\",\"Doble impacto socio-turístico: plataforma de freestyle y entrenamiento continuo de pretemporada para clubes andinos locales, combinada con escuela de iniciación al esquí para turistas todo el año y esquí social subsidiado para escuelas públicas de la ciudad.\"]", "[\"Urgencia fatal del Plan Galina (Chubut Deportes): plazo perentorio previo al 7 de octubre de 2026 para montar la pista, operarla y certificar fotográficamente la inversión con cartelería oficial provincial para el cierre del expediente de financiamiento.\",\"Impasse del predio definitivo de 1 hectárea: dilatación en el comodato/alquiler del terreno permanente en Darwin y Humpreys y falta de servicios básicos en el corto plazo; resuelto estratégicamente mediante el préstamo temporal de 3 semanas del predio de la Sociedad Rural de Esquel.\",\"Vacío normativo municipal y estructura jurídica mixta: ausencia de una ordenanza marco para dryslope urbano y necesidad de formalizar un Convenio de Comodato transparente entre la Asociación Civil Patagonia Freeride (titular de la pista) y la firma privada FLYPARK.\"]", "[{\"t\":\"Montaje en Sociedad Rural y Certificación del Plan Galina\",\"items\":[\"Acuerdo de uso temporal del predio de la Sociedad Rural articulado junto a la Secretaría de Producción (Paula Botto).\",\"Ensamble modular de 100 m² de alfombra Powplast, rampa, cajón de salto y tubos de PVC sobre el césped sin impacto ambiental.\",\"Evento Demo Oficial con autoridades (Intendente, Deportes, Turismo), prensa y clubes antes del 7 de octubre para rendir ante Chubut Deportes.\"]},{\"t\":\"Blindaje Político, Ordenanza Marco y Convenio Asociativo\",\"items\":[\"Anteproyecto de ordenanza municipal para parques urbanos de dryslope, con seguros de turismo activo y manual de bioseguridad.\",\"Convenio Marco de Comodato y Articulación entre Asociación Civil Patagonia Freeride y FLYPARK comercial, fijando cupos para escuelas públicas.\",\"Mesa de negociación para la radicación permanente del predio de 1 hectárea.\"]},{\"t\":\"Modelo de Negocio, Tarifario B2B y Merchandising Oficial\",\"items\":[\"Planilla paramétrica de costos y punto de equilibrio por turno de deslizamiento e iniciación.\",\"Tarifario comercial B2C/B2B para agencias receptivas de Esquel y abonos de pretemporada para clubes andinos.\",\"Lanzamiento y monetización de la línea textil de autor de la marca FLYPARK (remeras, buzos, gorritos, buffs).\"]}]", "[\"Montaje de pista modular de 100 m² en Sociedad Rural, Evento Demo Oficial y carpeta de rendición aprobada ante Chubut Deportes (Plan Galina).\",\"Anteproyecto de ordenanza marco para habilitación municipal de dryslope urbano y manual de bioseguridad deportiva.\",\"Convenio Marco de Articulación y Comodato firmado entre la Asociación Civil Patagonia Freeride y FLYPARK comercial.\",\"Planilla paramétrica de costos operativos, amortización de alfombra y tarifario comercial B2C y B2B (agencias y clubes).\",\"Landing page oficial interactiva con motor de reservas y catálogo digital de servicios y merchandising de la marca FLYPARK.\"]", "{\"estado\":\"completada\",\"titulo\":\"Minuta Cero · Entrevista Inicial de Diagnóstico\",\"fecha\":\"18/08/2026\",\"hora\":\"10:40\",\"lugar\":\"Sede Esquel LAB / Predio Flypark\",\"participantes\":[\"Fabricio Guglielmetti (Titular)\",\"Leandro (Conducción)\",\"Adria (Senior)\",\"Noelia (Junior)\"],\"resumen\":\"Fabricio Guglielmetti impulsa FLYPARK, parque de aventuras en altura con circuitos de arborismo, tirolesas y puentes colgantes en el bosque nativo. El proyecto responde a una demanda insatisfecha de actividades al aire libre para familias y turismo joven en Esquel. Requiere estructurar protocolos de seguridad, seguros específicos y un esquema comercial que supere la estacionalidad invernal.\",\"diagnostico_claves\":[\"Emprendimiento de turismo activo y entretenimiento familiar con locación en entorno natural privilegiado.\",\"Circuitos de tirolesa y puentes con diseño técnico que requiere homologación y mantenimiento continuo.\",\"Fuerte impulso motivacional familiar y excelente recepción preliminar en la comunidad y redes sociales.\",\"Oportunidad de traccionar tanto a turistas de La Hoya como a contingentes escolares de la región patagónica.\"],\"trabas_detectadas\":[\"Inestabilidad climática cordillerana (fuertes vientos o nevadas intensas impiden operar en altura).\",\"Costos elevados de pólizas de seguro de responsabilidad civil para turismo aventura.\",\"Falta de un sistema digital de reservas con turnos para evitar aglomeraciones en plataformas de lanzamiento.\"],\"acuerdos_previos\":[\"Formalizar el manual operativo y de contingencia climática para la operación de tirolesas.\",\"Diseñar la matriz tarifaria con precios diferenciados para residentes, turismo provincial y nacional.\",\"Articular acuerdos de comercialización con agencias de viajes receptivas de Esquel y Trevelin.\",\"Desarrollar el protocolo de bienvenida y charla técnica de seguridad previa al ascenso.\"],\"citas_textuales\":[\"\\\"Flypark no es solo colgarse de un arnés; es que una familia entera viva la adrenalina del bosque con la tranquilidad de que la seguridad es total.\\\"\",\"\\\"Necesitamos que la gente pueda reservar y pagar su turno desde el celular antes de subir a la montaña.\\\"\"],\"texto_completo\":\"## Minuta Cero: Encuentro Diagnóstico Inicial · FLYPARK\\n\\n**Fecha:** 18 de agosto de 2026 | **Sede:** Sede Esquel LAB / Predio Flypark\\n**Asistentes:** Fabricio Guglielmetti (Titular), Leandro (Conducción), Adria (Senior), Noelia (Junior)\\n\\n### 1. Perfil y Oportunidad Detectada\\nPropuesta de turismo aventura y recreación activa en altura. Atractivo de alto impacto para romper la estacionalidad y ofrecer alternativas a días sin esquí o tardes familiares.\\n\\n### 2. Cuellos de Botella Relevados\\n- **Seguridad y habilitaciones:** Exigencia de seguros específicos y homologación de anclajes en bosque.\\n- **Operación climática:** Protocolos claros para días con ráfagas de viento o lluvia.\\n- **Canal de reservas:** Necesidad de agenda digital para evitar esperas y sobrecupos.\\n\\n### 3. Compromisos de Arranque\\n1. Redacción del protocolo operativo y ficha de seguridad para el usuario.\\n2. Definición del tarifario oficial de temporada.\\n3. Contacto con agencias locales para inclusión en paquetes receptivos.\"}"],
        ["porota", 19, "LO DE POROTA... \"meriendas de campo y arqueología familiar patagónica\"", "Alda Inés Mateo Garín (\"Pelusa\")", "Acelera", 3.85, 3, "adria", "francisco", "[\"Propuesta de turismo cultural, arqueológico y gastronómico de inmenso valor testimonial e identitario, ubicada en Don Bosco 920 (Barrio Don Bosco, Esquel). Rescata el legado centenario de la familia Mateo-Garín (pioneros de Tecka desde 1875 en Estancia La Central).\",\"El corazón del proyecto es la 'Colección Arqueológica Clara Rosa Garín (Porota)', conformada por 7.552 piezas milenarias (puntas de flecha, hachas de piedra, pipas, raspadores, boleadoras y trawiles) recolectadas a caballo durante décadas por Porota Garín. Colección privada legalmente registrada e inventariada técnicamente por los antropólogos Heidi y Leandro.\",\"La experiencia fusiona la memoria viva de la Patagonia con la hospitalidad hogareña de Alda Inés Mateo Garín ('Pelusa', jubilada): merienda casera campera (pan horneado en casa, manteca de campo, mermeladas de frutos del bosque, tortas fritas calientes), recorrido guiado por las vitrinas y mesas vidriadas de la casa, y asesoramiento museológico cercano del Prof. Marcelo Troiano (vecino y co-seleccionado de la cohorte).\"]", "[\"Acondicionamiento museográfico y mobiliario seguro: necesidad de transformar el mobiliario existente (escritorio antiguo, vitrina de pared y mesas de té con tapas de vidrio templado de seguridad) para exhibir las piezas de forma protegida sin permitir la manipulación riesgosa o extravío, además de pintura y puesta a punto de sanitarios domésticos para recepción.\",\"Protocolización bromatológica y comercial de la merienda: transición desde una actividad familiar informal hacia un servicio gastronómico habilitado con cupo máximo estricto (6 a 10 comensales por turno) que preserve la intimidad y la custodia patrimonial.\",\"Creación de identidad de marca, canales digitales y souvenir físico: carencia de logotipo, identidad visual y web de reservas; ausencia de un souvenir tangible (réplicas de puntas de flecha en arcilla/madera o postales ilustradas con la historia de Tecka) para capitalizar la 'economía de los recuerdos'.\"]", "[{\"t\":\"Curaduría Museográfica, Conservación Patrimonial y Guion Emocional\",\"items\":[\"Adaptación del mobiliario de la casa (escritorio histórico con caja vidriada de seguridad, vitrina de pared y mesas de té vidriadas) e iluminación de las piezas arqueológicas.\",\"Redacción del guion interpretativo en 4 momentos: 1) Linaje de los pioneros de Tecka (1875); 2) Exposición de las 7.552 piezas y métodos líticos ancestrales; 3) Taller de mate y torta frita casera en el comedor/jardín; y 4) Relato íntimo de la pieza más preciada de Porota.\",\"Asesoramiento cruzado con Marcelo Troiano y los antropólogos Heidi y Leandro.\"]},{\"t\":\"Identidad de Marca 'Lo de Porota', Plataforma Web y Souvenirs de Autor\",\"items\":[\"Desarrollo de la marca e identidad visual (logo, paleta de colores tierra/piedra, tipografía evocativa y señalética exterior discreta).\",\"Landing page de reservas online en esquel.site con cupos limitados por turno (martes, jueves y sábados de 16:30 a 18:30 hs para no interferir con las mañanas de Newcom de Pelusa).\",\"Desarrollo del souvenir oficial: réplicas artesanales de puntas de proyectil en arcilla/madera con packaging rústico y cuadernillo ilustrado 'Memorias de Porota Garín'.\"]},{\"t\":\"Estructura de Costos, Habilitación Bromatológica y Alianzas B2B\",\"items\":[\"Planilla paramétrica de costos de la merienda de campo y fijación de tarifario dual (general turistas vs residentes) y comisiones del 20-25% para agencias EVyT.\",\"Adecuación a las normativas de bromatología municipal para salones de té y meriendas hogareñas.\",\"Alianzas de derivación con hoteles boutique céntricos y sinergias con otros proyectos de Célula 3 (El Arroyo Que Nos Ve Crecer... y Sabor Mapuche).\"]}]", "[\"Guion interpretativo y protocolo de visita de 'Lo de Porota: meriendas de campo y arqueología familiar', con tiempos, capacidad de carga (máx. 10 personas) y catálogo de piezas destacadas.\",\"Mobiliario museográfico adaptado y seguro en sala principal (escritorio antiguo vidriado, vitrina y mesas temáticas) con fichas técnicas explicativas.\",\"Identidad visual consolidada (logotipo, tipografía, paleta de colores y cartelería de bienvenida) y landing page de reservas online.\",\"Prototipo del souvenir de autor conector (réplicas de puntas de flecha artesanales en cofre rústico y folleto ilustrado con relatos de Tecka).\",\"Planilla paramétrica de costos y tarifario oficial B2C/B2B para comercialización con agencias receptivas y alojamientos.\",\"Manual de manipulación segura y custodia legal de la Colección Arqueológica Clara Rosa Garín avalado ante las áreas de Patrimonio Cultural.\"]", "{\"estado\":\"completada\",\"titulo\":\"Minuta Cero · Entrevista Inicial de Diagnóstico\",\"fecha\":\"18/08/2026\",\"hora\":\"12:15\",\"lugar\":\"Casa histórica de Pelusa, Esquel\",\"participantes\":[\"Alda Inés \\\"Pelusa\\\" Mateo Garín (Titular)\",\"Leandro (Conducción)\",\"Mariela (Senior)\",\"Cesia (Junior)\"],\"resumen\":\"Pelusa rescata la historia de su familia, pioneros llegados a Tecka en 1865/1875, ofreciendo meriendas de campo en su propia casa acompañadas de \\\"arqueología familiar patagónica\\\". Custodia un archivo vivo de cartas, fotos originales, muebles, baúles y vajilla histórica. El encanto es absoluto pero requiere cuidar la intimidad del hogar, fijar límites de capacidad de carga y estandarizar la merienda.\",\"diagnostico_claves\":[\"Propuesta de turismo vivencial y memoria histórica con autenticidad inigualable.\",\"Archivo documental y objetos de época de alto valor patrimonial para la región patagónica.\",\"Excelente mano culinaria tradicional (tortas galesas, panes caseros, dulces regionales y repostería de campo).\",\"Espacio en vivienda particular que debe acondicionarse para recorridos guiados sin invadir áreas íntimas.\"],\"trabas_detectadas\":[\"Capacidad de carga física reducida: máximo 8 a 10 personas por turno para preservar la experiencia.\",\"Dificultad de Pelusa para resumir su relato sin extenderse excesivamente durante la visita.\",\"Trámites de habilitación de cocina artesanal y protocolo de manipulación de alimentos.\"],\"acuerdos_previos\":[\"Guionar la experiencia en 3 momentos de 30 minutos: relato y archivo, merienda de campo, y charla de cierre.\",\"Fijar tarifa exclusiva por persona con cobro de seña previa del 50% para compra de insumos frescos.\",\"Crear una línea de souvenirs de autor: tarjetones históricos facsimilares con recetas tradicionales familiares.\",\"Acondicionar el circuito de circulación en el living y patio con señalética discreta.\"],\"citas_textuales\":[\"\\\"Tengo cajas con cartas de 1880 y la vajilla original de mi bisabuela; la gente se sienta a merendar y se emociona hasta las lágrimas al ver las fotos.\\\"\",\"\\\"A veces me engancho hablando y no me doy cuenta del tiempo; necesito una estructura para que sea un servicio hermoso y ordenado.\\\"\"],\"texto_completo\":\"## Minuta Cero: Encuentro Diagnóstico Inicial · Lo de Porota\\n\\n**Fecha:** 18 de agosto de 2026 | **Sede:** Casa histórica de Pelusa, Esquel\\n**Asistentes:** Alda Inés Mateo Garín (Titular), Leandro (Conducción), Mariela (Senior), Cesia (Junior)\\n\\n### 1. Perfil y Oportunidad Detectada\\nExperiencia vivencial que combina gastronomía tradicional de campo y museo vivo de una familia pionera patagónica. Propuesta de altísima diferenciación para grupos reducidos.\\n\\n### 2. Cuellos de Botella Relevados\\n- **Gestión del tiempo:** Necesidad de pautar la duración de la charla para no sobrecargar a la anfitriona.\\n- **Espacio doméstico:** Delimitar claramente las zonas de visita respecto de las áreas familiares privadas.\\n- **Esquema de reservas:** Obligatoriedad de confirmación previa para garantizar la frescura de la elaboración.\\n\\n### 3. Compromisos de Arranque\\n1. Guion estructurado del recorrido (1 hora y media total).\\n2. Definición del menú fijo de campo y costo por comensal.\\n3. Prototipo de souvenir gráfico con historia familiar.\"}"],
        ["senderos", 31, "Senderos con Identidad", "Gabriela Verónica Farias y Florencia Micaela Couget", "Acelera", 3.33, 3, "adria", "francisco", "[\"Equipo interdisciplinario idóneo y complementario radicado en Barrio Badén: Florencia Micaela Couget es Guía de Senderismo Habilitada (Matrícula N° 26312), socorrista en zonas agrestes (WFR/RCP) y especialista en herbolaria (Alquimiandina); Gabriela Verónica Farias posee Diplomatura Técnico-Profesional en Cosmética Natural (UTN La Plata), trayectoria de 4 años en elaboración (Auténtica Cosmética Natural) y cursa la tecnicatura de guía en el CFP N° 655.\",\"Propuesta de valor transformadora: senderismo botánico interpretativo y bienestar que supera el 'caminar por caminar'. El sendero funciona como un aula viva a cielo abierto donde el visitante aprende a reconocer plantas nativas (palo piche, paramela, llantén, caléndula, ñire), experimenta sus principios activos in situ, vive un ritual de 'bajada a tierra' (mindfulness, respiración consciente y descalzado en mirador) y comparte mateada campesina con pan casero.\",\"Articulación activa con el ecosistema de Esquel: vecindad con La Cruz y Cañadón de Bórquez, vinculación con INTA, CIEFAP (hongos silvestres) y sinergias con prestadores de la cohorte (Las Margaritas en Nahuelpan, Haiku té verde, El Mugre en La Zeta).\"]", "[\"Inseguridad inicial sobre requerir un laboratorio o aula física para dictar talleres (resuelto en el diagnóstico: el taller es el propio sendero a cielo abierto, sin costos de alquiler).\",\"Equipamiento de seguridad y comunicación: necesidad de radios VHF/UHF para zonas sin señal, plan de contingencias y evacuación visado por Protección Civil y bastones de trekking para excursionistas.\",\"Falta de estructura de costos y tarifario para salidas regulares: dependencia de la demanda espontánea, necesidad de fijar días fijos y formalizar la comercialización mediante el Registro de Turismo Alternativo y agencias receptivas (EVyT).\"]", "[{\"t\":\"Estandarización y Traqueo de 3 Circuitos\",\"items\":[\"Circuito 1: 'Paseo del Arroyo & La Cascada' (accesible / familiar / adultos mayores con canteros de nativas).\",\"Circuito 2: 'Cañadón de Bórquez a La Zeta' (paisajístico / botánico intermedio con arroyo y miradores).\",\"Circuito 3: 'Cañadón de las Palomas & El Palomar' (panorámico y geológico con regreso por La Palestra).\"]},{\"t\":\"Dinámica Sensorial, Souvenir y Guion de Autor\",\"items\":[\"Estructuración de la pausa de 'bajada a tierra' (respiración consciente, descalzado en la tierra y cata de mate campesino con hierbas recolectadas).\",\"Tríptico botánico de bolsillo de autor y entrega de muestra de cosmética natural (ungüento de paramela o bálsamo de caléndula) como souvenir tangible.\"]},{\"t\":\"Seguridad Agreste, Costeo y Comercialización\",\"items\":[\"Plan de emergencias y frecuencias de radio coordinadas con Protección Civil Municipal (Sergio Caneo).\",\"Matriz de costeo por salida (punto de equilibrio en 4 personas), tarifario B2C/B2B y convenio con agencias receptivas de Esquel.\"]}]", "[\"Fichas técnicas y mapas con tracks GPS de los 3 circuitos estandarizados.\",\"Plan de Contingencias y Evacuación visado por Protección Civil con frecuencias VHF.\",\"Tríptico Botánico de Bolsillo impreso y validado en campo.\",\"Planilla de costeo integral parametrizada y tarifario para agencias y hoteles.\",\"Convenio marco de comercialización con al menos 1 agencia receptiva habilitada y ficha de inscripción en Turismo Alternativo.\"]", "{\"estado\":\"completada\",\"titulo\":\"Minuta Cero · Entrevista Inicial de Diagnóstico\",\"fecha\":\"21/08/2026\",\"hora\":\"14:30\",\"lugar\":\"Sede Esquel LAB\",\"participantes\":[\"Gabriela Farías (Titular)\",\"Florencia Couget (Titular)\",\"Mariela (Senior)\",\"Agustina (Junior)\"],\"resumen\":\"Gabriela y Florencia son profesionales del turismo y la educación ambiental que impulsan guiadas de senderismo con interpretación biológica, histórica y cultural en el periurbano de Esquel. Dominan el terreno técnico pero venían operando de manera discontinua, a la gorra o con salidas esporádicas. Buscan consolidar una empresa formal con circuitos fijos y convenios hoteleros.\",\"diagnostico_claves\":[\"Formación técnica de excelencia en guiadas de montaña, primeros auxilios y rescate de flora nativa.\",\"Rutas periurbanas de fácil acceso (Laguna La Zeta, Cerro 21, Cañadón de Borquez) sin costos de traslado complejos.\",\"Excelente química de equipo y vocación pedagógica para público familiar y principiantes.\",\"Falta de empaque comercial formal: no cuentan con folletos en conserjerías ni tarifario profesional.\"],\"trabas_detectadas\":[\"Inseguridad al momento de cobrar tarifas acordes a su formación profesional.\",\"Falta de equipamiento de seguridad homologado y botiquín de respuesta avanzada.\",\"Poca articulación con alojamientos y agencias receptivas locales.\"],\"acuerdos_previos\":[\"Definir 3 circuitos oficiales con ficha técnica, desnivel, duración y público objetivo.\",\"Fijar calendario semanal con días y horarios predeterminados para garantizar regularidad.\",\"Diseñar la tarjeta digital de presentación para distribuir en hoteles y cabañas de Esquel.\",\"Armar alianzas con otros prestadores gastronómicos para ofrecer caminata + merienda cordillerana.\"],\"citas_textuales\":[\"\\\"Queremos que caminar no sea solo poner un pie adelante del otro, sino entender por qué ese árbol crece ahí y qué huella dejó la historia.\\\"\",\"\\\"Nos costaba ponerle precio a nuestro trabajo; ahora entendemos que la gente valora la seguridad y el conocimiento que transmitimos.\\\"\"],\"texto_completo\":\"## Minuta Cero: Encuentro Diagnóstico Inicial · Senderos con Identidad\\n\\n**Fecha:** 21 de agosto de 2026 | **Sede:** Sede Esquel LAB\\n**Asistentes:** Gabriela Farías, Florencia Couget (Titulares), Mariela (Senior), Agustina (Junior)\\n\\n### 1. Perfil y Oportunidad Detectada\\nSenderismo interpretativo de media y baja dificultad en el cordón montañoso y áreas naturales de Esquel. Fuerte componente ambiental y cultural.\\n\\n### 2. Cuellos de Botella Relevados\\n- **Monetización:** Superar el esquema informal o a la gorra y adoptar tarifas de guías habilitadas.\\n- **Regularidad:** Mantener salidas garantizadas aunque haya pocos inscriptos iniciales.\\n- **Canales de venta:** Establecer presencia física y digital en los puntos de arribo de turistas.\\n\\n### 3. Compromisos de Arranque\\n1. Fichas descriptivas de los 3 circuitos insignia.\\n2. Calendario semanal con días fijos de salida.\\n3. Material promocional para conserjerías y agencias.\"}"],
        ["yamamori", 22, "Yamamori Travel", "María Julia Montero", "Acelera", 3.33, 4, "mariela", "agustina", "[\"María Julia Montero aporta un perfil profesional de excelencia: Técnica Superior en Hotelería (CESyT), estudios de Licenciatura en Administración Hotelera y Gastronómica (UNSAM), 16 años como Tripulante de Cabina de Pasajeros (Emirates Airlines y Aerolíneas Argentinas) y más de 7 años de estudio del idioma y cultura japonesa (inmersión en Sapporo, enero 2026).\",\"Apasionada embajadora de Esquel: monitorea a diario los medios locales y promueve el destino proactivamente. Organizó a pulmón su primer viaje piloto grupal (10 pasajeros, 4D/3N) del 30 de octubre al 2 de noviembre de 2026, con 9 plazas confirmadas, combi, hoteles (Sur Sur y Trevelin), La Trochita y guiada en Museo Histórico con Carla.\",\"Propuesta de valor diferencial: curaduría de viajes de autor en grupos reducidos (8 a 10 personas), introduciendo la filosofía de hospitalidad japonesa 'Omotenashi' (cuidado en el detalle, pantuflas en habitación, termo con té verde al regresar del frío, atención pausada y respetuosa) para captar al turismo receptivo japonés/asiático de alto poder adquisitivo y al segmento emisivo nacional de alta gama.\"]", "[\"Falta de encuadre normativo propio para comercialización turística: al desempeñarse formalmente como tripulante de cabina, requiere operar bajo convenio marco con una Agencia de Viajes Receptiva (EVyT) habilitada en Esquel.\",\"Sobrecostos y saturación en temporada alta (vivió la 'trampa de tulipanes' con tarifas duplicadas y plazas colapsadas), lo que exige enfocar la comercialización en productos desestacionalizados.\",\"Necesidad de estructurar acuerdos de tarifas netas B2B confidenciales con prestadores comarcales (hotelería, transporte, gastronomía y estancias) y coordinar su disponibilidad horaria como TCP.\"]", "[{\"t\":\"Desestacionalización y Productos de Autor\",\"items\":[\"Diseño de dos itinerarios de alta gama para 2027: 'Otoño de Lenga & Fotografía' (marzo/abril) y 'Ciruelos en Flor & El Sakura Patagónico' (septiembre/octubre en Av. Ameghino).\",\"Monitoreo técnico y capitalización de aprendizajes del viaje piloto del 30 de octubre al 2 de noviembre.\"]},{\"t\":\"Hospitalidad Omotenashi y Sinergia con la Cohorte\",\"items\":[\"Protocolo de atención omotenashi y kit de bienvenida con insumos locales (té verde de Haiku, pantuflas de lana y recuerdos de artesanos de la cohorte).\",\"Integración de visitas exclusivas a talleres y predios de compañeros de incubación (Crova tornería de madera, Haiku casa de té, estancias ovinas).\"]},{\"t\":\"Encuadre Legal Receptivo y Alianza EVyT\",\"items\":[\"Convenio marco comercial con agencia receptiva habilitada (EVyT) de Esquel para respaldo legal, emisión y seguros de turismo activo.\",\"Matriz de costeo B2B con margen del 15% al 20%, tarifario confidencial y brochure digital bilingüe (español/japonés).\"]}]", "[\"Informe de balance y métricas de satisfacción del viaje piloto de octubre.\",\"Fichas técnicas y comerciales de los 2 paquetes desestacionalizados 2027 ('Otoño de Lenga' y 'Sakura de Esquel').\",\"Manual del Protocolo de Hospitalidad 'Omotenashi Patagónico' y ficha del Kit de Bienvenida.\",\"Convenio marco de cooperación comercial con Agencia Receptiva EVyT de Esquel.\",\"Tarifario B2B confidencial, matriz de costeo integral y brochure digital bilingüe para comercialización.\"]", "{\"estado\":\"completada\",\"titulo\":\"Minuta Cero · Entrevista Inicial de Diagnóstico\",\"fecha\":\"31/08/2026\",\"hora\":\"11:45\",\"lugar\":\"Sede Esquel LAB / Virtual\",\"participantes\":[\"María Julia Montero (Titular)\",\"Mariela (Senior)\",\"Francisco (Junior)\"],\"resumen\":\"María Julia Montero cuenta con amplia trayectoria en agencias de viajes de gran escala en Buenos Aires y eligió radicarse en Esquel para desarrollar una agencia de viajes receptiva de experiencias auténticas. Conoce la lógica del mercado emisor pero necesita fortalecer su red de proveedores locales para diseñar paquetes boutique exclusivos que no compitan por precio.\",\"diagnostico_claves\":[\"Experiencia probada en comercialización turística, venta de pasajes, seguros y contratación con mayoristas.\",\"Visión clara del perfil de pasajero de alta gama que busca experiencias personalizadas sin intermediarios masivos.\",\"Trabajo previo de relevamiento en territorio durante sus viajes de prospección por Trevelin y Esquel.\",\"Necesidad de construir alianzas de confianza con productores locales y artesanos para visitas exclusivas.\"],\"trabas_detectadas\":[\"Ausencia de tarifas netas pactadas con prestadores de la comarca, lo que dificulta cotizar en el acto.\",\"Dificultad para diferenciarse de las agencias tradicionales que venden únicamente La Trochita y el Parque Nacional.\",\"Inversión requerida en campañas de marketing digital dirigidas a centros emisores (CABA, Córdoba, Santa Fe).\"],\"acuerdos_previos\":[\"Diseñar 2 programas exclusivos de 3 y 5 días articulados con los emprendimientos de la cohorte del LAB.\",\"Elaborar el modelo de convenio de prestador con políticas de comisión y cancelación transparentes.\",\"Crear catálogo digital B2B para presentar a agencias minoristas seleccionadas de grandes ciudades.\",\"Establecer protocolo de atención personalizada y guardia 24/7 para el pasajero en destino.\"],\"citas_textuales\":[\"\\\"El pasajero que viene a la Patagonia hoy no quiere subirse a un micro de 40 personas; quiere tomarse un vino con el dueño del viñedo o aprender a tallar una pipa.\\\"\",\"\\\"Mi fuerte es la venta y la relación con las agencias de afuera; necesito que los productos de acá estén listos para cotizar y operar sin sorpresas.\\\"\"],\"texto_completo\":\"## Minuta Cero: Encuentro Diagnóstico Inicial · Yamamori Travel\\n\\n**Fecha:** 31 de agosto de 2026 | **Sede:** Sede Esquel LAB / Virtual\\n**Asistentes:** María Julia Montero (Titular), Mariela (Senior), Francisco (Junior)\\n\\n### 1. Perfil y Oportunidad Detectada\\nAgencia de viajes receptiva especializada en turismo boutique y vivencial. Nexo estratégico entre la demanda de centros urbanos y la oferta auténtica de la cordillera.\\n\\n### 2. Cuellos de Botella Relevados\\n- **Convenios de tarifas:** Acordar valores de operador con prestadores de turismo rural y artesanal.\\n- **Posicionamiento diferencial:** Romper el circuito tradicional y vender experiencias de autor.\\n- **Canal digital:** Reforzar presencia online y pauta segmentada.\\n\\n### 3. Compromisos de Arranque\\n1. Matriz de 2 itinerarios exclusivos de 3 y 5 noches.\\n2. Formato estándar de convenio prestador-agencia.\\n3. Carpeta comercial digital para el canal B2B.\"}"],
        ["arroyo", 15, "EL ARROYO QUE NOS VE CRECER...", "Prof. Marcelo Troiano", "Acelera", 3.32, 3, "adria", "francisco", "[\"Profesor de historia y museólogo con orientación en museología social comunitaria, residente en Esquel desde hace 40 años (1986). Posee amplia trayectoria docente y sólida solvencia investigativa sobre los barrios de las laderas y la evolución sociohistórica urbana de la ciudad.\",\"Propuesta de valor disruptiva de turismo cultural y regenerativo: rescate de la memoria viva a la vera del arroyo Esquel y las vías de La Trochita. Supera la mirada tradicional del paisaje para convertir a la ciudad y a sus vecinos en protagonistas del relato histórico, integrando arqueología urbana (Molino Weber, Planta de Gas, pasarelas históricas) con las laderas populares (Barrio Ceferino, La Gruta del Padre Parolini).\",\"Activo tangible diferenciador: autor del libro-souvenir publicado 'Postales históricas de Esquel', que funciona como soporte de conocimiento de alta gama para el turista, complementado con material fotográfico de época y relatos orales de vecinos emblemáticos.\"]", "[\"Transición de evento cultural o charla académica a producto turístico comercializable: necesidad de estandarizar 2 circuitos cerrados con tiempos, mapas GPS y paradas definidas, superando la dispersión de contenidos.\",\"Fijación de precios y estructura de costos: falta de una matriz paramétrica que determine tarifas de salidas regulares, comisiones de agencias receptivas y acuerdos económicos de refrigerio con vecinos del barrio (tortas fritas caseras y mate).\",\"Brecha digital y canal de reservas: ausencia de canales digitales de difusión, venta online (Mercado Pago) y folletería de bolsillo para agencias y hoteles.\"]", "[{\"t\":\"Estandarización de 2 Circuitos de Arqueología Urbana\",\"items\":[\"Circuito 1: 'El Origen entre el Arroyo y las Vías' (Baja dificultad, 90 min, plano y accesible: Av. Fontana, Molino Weber, Planta de Gas, terraplén y descanso en Panadería Genes).\",\"Circuito 2: 'Laderas, Gruta y Memoria Viva' (Dificultad media, 135 min: ascenso por escalinata barrial a La Gruta del Ceferino, mirador panorámico de la cuenca, relatos del Padre Parolini y parada comunitaria de tortas fritas con Doña Pepa).\"]},{\"t\":\"Guion Interpretativo, Experiencia Inmersiva y Libro-Souvenir\",\"items\":[\"Dramaturgia de las paradas: relato empático y emocionante de 5 actos que combina rigor histórico con vivencias cotidianas y memoria barrial.\",\"Puesta en valor del libro 'Postales históricas de Esquel' con packaging de autor y edición del tríptico cartográfico de bolsillo de la cuenca histórica.\"]},{\"t\":\"Modelo Económico, Ecosistema Digital y Rueda Comercial B2B\",\"items\":[\"Planilla paramétrica de costos (punto de equilibrio en 4 personas), tarifario B2C/B2B y comisiones para agencias receptivas y hoteles.\",\"Landing page en esquel.site con mapa interactivo geolocalizado, 5 micro-audioguías y botón de cobro online Mercado Pago.\",\"Alianzas de cohorte: paquete combinado de cicloturismo patrimonial junto a Corcho Bikes y articulación horaria con La Trochita.\"]}]", "[\"Guion interpretativo formal y fichas técnicas con track georreferenciado de los 2 Circuitos ('El Origen' y 'Laderas y Gruta').\",\"Tríptico cartográfico de bolsillo de la cuenca histórica y packaging de autor para el libro 'Postales históricas de Esquel'.\",\"Planilla paramétrica de costos unitarios, punto de equilibrio y tarifario comercial minorista y mayorista (B2B/B2C).\",\"Landing page oficial con mapa interactivo, 5 micro-audioguías y pasarela de cobro digital (Mercado Pago / WhatsApp Business).\",\"Convenio de articulación con al menos 1 prestador barrial de hospitalidad (Doña Pepa / tortas fritas) y acuerdo de derivación con agencias receptivas de Esquel.\"]", "{\"estado\":\"completada\",\"titulo\":\"Minuta Cero · Entrevista Inicial de Diagnóstico\",\"fecha\":\"21/08/2026\",\"hora\":\"09:30\",\"lugar\":\"Sede Esquel LAB / Borde del Arroyo Esquel\",\"participantes\":[\"Prof. Marcelo Troiano (Titular)\",\"Leandro (Conducción)\",\"Mariela (Senior)\",\"Agustina (Junior)\"],\"resumen\":\"El profesor e historiador Marcelo Troiano propone un circuito interpretativo guiado a pie a lo largo del arroyo Esquel, poniendo en valor la memoria fundacional del pueblo, las comunidades originarias y los primeros pobladores. Su bagaje cultural es extraordinario, pero la propuesta requiere pasar de una charla académica abierta a una experiencia turística arancelada y estructurada.\",\"diagnostico_claves\":[\"Investigador respetado con décadas de archivo, publicaciones y memoria viva de la comunidad.\",\"Sendero ribereño público con puntos neurálgicos de gran carga simbólica e histórica.\",\"Excelente capacidad oratoria y empatía para cautivar tanto a residentes como a turistas.\",\"Falta de delimitación de paradas, horarios y mecanismo formal de cobro de boletos.\"],\"trabas_detectadas\":[\"Puntos del arroyo con falta de mantenimiento urbano o malezas que afectan el paso pedestre.\",\"Resistencia interna del titular a cobrar por compartir el conocimiento histórico de la ciudad.\",\"Inexistencia de un soporte gráfico o souvenir que el visitante pueda conservar tras el recorrido.\"],\"acuerdos_previos\":[\"Delimitar el recorrido en 5 hitos históricos con una duración total fija de 80 minutos.\",\"Diseñar un mapa facsimilar ilustrado para entregar como entrada/recuerdo a cada caminante.\",\"Fijar tarifa turística oficial y calendario de 2 salidas semanales (miércoles y sábados por la tarde).\",\"Articular gestiones ante Obras Públicas para mejorar la transitabilidad de los tramos críticos del sendero.\"],\"citas_textuales\":[\"\\\"El arroyo es el pulso de la historia de Esquel: ahí se lavó la primera lana, se tomó el agua y se levantaron los primeros ranchos de chapa.\\\"\",\"\\\"Me daba pudor cobrar por contar la historia de mi pueblo, pero entiendo que si no es sustentable, la historia se pierde y no llega a las nuevas generaciones.\\\"\"],\"texto_completo\":\"## Minuta Cero: Encuentro Diagnóstico Inicial · El Arroyo Que Nos Ve Crecer...\\n\\n**Fecha:** 21 de agosto de 2026 | **Sede:** Sede Esquel LAB / Borde del Arroyo Esquel\\n**Asistentes:** Prof. Marcelo Troiano (Titular), Leandro (Conducción), Mariela (Senior), Agustina (Junior)\\n\\n### 1. Perfil y Oportunidad Detectada\\nPaseo histórico pedestre con relato de autor a la vera del arroyo Esquel. Rescate del patrimonio fundacional y la identidad intercultural.\\n\\n### 2. Cuellos de Botella Relevados\\n- **Estructuración:** Delimitar tiempo y estaciones para evitar que el paseo se extienda en demasía.\\n- **Comercialización:** Definir valor de entrada y puntos de partida oficiales.\\n- **Entorno físico:** Estado de conservación de las pasarelas y márgenes del arroyo.\\n\\n### 3. Compromisos de Arranque\\n1. Guion oficial de 5 paradas con tiempos estandarizados.\\n2. Diseño del mapa-souvenir histórico para el visitante.\\n3. Lanzamiento de las salidas regulares con reserva previa.\"}"],
        ["vicotita", 45, "Vico + Tita · Diseño Mapuche Contemporáneo", "María Eugenia y María José Gutiérrez", "Acelera", 3.27, 1, "mariela", "cesia", "[\"Emprendimiento con más de 11 años de trayectoria ininterrumpida (desde 2013/2014) liderado por las hermanas María Eugenia y María José Gutiérrez, docentes de formación (Eugenia en nivel superior y Majo en artes visuales y preservación de patrimonio bibliográfico). Participaron oficialmente en dos ediciones de Puro Diseño en Buenos Aires.\",\"Propuesta identitaria de 'Diseño Mapuche Contemporáneo'. Como mujeres mapuche que participan activamente de la vida comunitaria y ceremonial (Camarruco), reinterpretan la memoria oral ancestral, la simbología cuatripartita (Choique), los puntos de telar (nimín) y leyendas de flora/fauna (Quñegüe) en piezas utilitarias modernas.\",\"Complementariedad técnica de excelencia: Majo domina ilustración manual/digital y encuadernación artística (costura en cuero/tela, mosaico en relieve, gofrado, hot stamping dorado/plateado y restauración). Euge domina marroquinería y serigrafía artesanal textil con matrices dobles sobre telas impermeables y repelentes al agua.\",\"Clientes corporativos y turísticos fieles de larga data: confeccionan desde hace 9 años las bitácoras de viaje y senderismo para una empresa de trekking en Tierra del Fuego; producen líneas para el Campo de Tulipanes y Casa Shagüe/Yagüe; libros de registro para Viñas de Nant y Fall y encuadernaciones para Cultura de Provincia.\",\"Canales actuales y dependencia de ferias: Históricamente comercializan en la feria artesanal municipal y por pedidos directos. Requieren formalizar un catálogo comercial B2B para que hoteles boutique, lodges de pesca y agencias de viaje incorporen su merchandising de manera recurrente.\"]", "[\"Dificultad para condensar el relato sin desvirtuar su valor: La cosmovisión mapuche y memoria oral de las piezas es profunda, pero en mostrador o feria el visitante muchas veces no dispone de tiempo para escucharla. Requieren un sistema de etiquetado de autor y marbetes con código QR que comuniquen el valor de la pieza en 30 segundos.\",\"Dispersión de talleres y asimetría de horarios docentes: Euge tiene disponibilidad por las mañanas y Majo por las tardes con horarios escolares rotativos. Cada una produce en su propio taller domiciliario (Barrio Chanico Navarro), lo que condiciona la producción en serie o la apertura permanente de taller al público.\",\"Inexistencia de catálogo comercial B2B para prestadores: Los prestadores turísticos (hoteles boutique, cabañas, agencias) no pueden visualizar cómo adaptar un estuche o bitácora a su establecimiento sin un muestrario claro de co-branding, escalas de precios por volumen y plazos de entrega.\",\"Dispersión de costos y necesidad de productos estandarizados de entrada: Piezas complejas de marroquinería ($40.000) o encuadernación pesada tienen rotación lenta. Se requiere consolidar una pirámide de productos con opciones de entrada ágiles (libretas de campo y bitácoras de viaje entre $8.000 y $15.000).\"]", "[{\"t\":\"Storytelling de Marca, Etiquetado y Colección 'Estampa Esquel'\",\"items\":[\"Sistema de marbetes colgantes y tarjetas de autenticidad de autor, con micro-relato identitario (nimín, Quñegüe, Choique) y código QR ampliado con fotos del proceso de serigrafía y encuadernación.\",\"Consolidación de la paleta cromática de temporada (colores tierra y verano patagónico) para la colección 'Estampa Esquel: Naturaleza Ancestral' en marroquinería y papelería.\",\"Estructuración de una pirámide de precios de 3 niveles: Acceso (libretas de mano y señaladores), Medio (bitácoras cosidas, cartucheras, tote bags impermeables) y Colección (cuadernos de cuero con grabado, mochilas de autor).\"]},{\"t\":\"Catálogo Comercial para Prestadores y Convenios de Canal\",\"items\":[\"Diseño de catálogo comercial digital interactivo (PDF interactivo y presentación web) orientado específicamente a hoteles boutique, agencias receptivas y organizadores de eventos.\",\"Muestrario de co-branding y personalización: mockups visuales de libretas y estuches que integran la estampa de autor con logotipos de establecimientos turísticos de Esquel.\",\"Fijación de lista de precios mayorista por escalas de volumen (pedidos de 20, 50 y 100 unidades) con plazos de entrega estandarizados (7 a 15 días) y facturación con monotributo.\"]},{\"t\":\"Prototipado de la Bitácora de Campo y Experiencia Piloto de Taller\",\"items\":[\"Desarrollo y testeo de la 'Bitácora de Campo y Registro de Montaña': libreta rústica de tapa blanda con cuadrícula de coordenadas (latitud/longitud), mapas de senderos, flora nativa y micro-poesías patagónicas.\",\"Prueba de campo de la bitácora con prestadores y guías de senderismo de la Célula 1 (Oficio) y Célula 4 (Canal).\",\"Proto-armado de un formato de 'Taller Abierto / Clínica de Estampado' para fechas especiales (temporada de tulipanes en octubre o verano) en grupos reducidos de 4 a 6 personas.\"]}]", "[\"Sistema de etiquetado narrativo y marbete con código QR listo para imprenta.\",\"Catálogo comercial B2B para hoteles, agencias y eventos turísticos con opciones de co-branding.\",\"Prototipo final de la 'Bitácora de Campo y Montaña' para senderismo y excursionismo.\",\"Matriz de costeo por volumen y capacidad de producción estandarizada para pedidos mayoristas.\",\"Muestrario de la Colección 'Estampa Esquel: Naturaleza Ancestral' en marroquinería y encuadernación.\",\"Al menos 3 convenios comerciales o acuerdos de provisión cerrados con alojamientos o receptivos.\"]", "{\"estado\":\"completada\",\"titulo\":\"Minuta Cero · Entrevista Inicial de Diagnóstico\",\"fecha\":\"20/08/2026\",\"hora\":\"11:00\",\"lugar\":\"Taller Vico + Tita, Esquel\",\"participantes\":[\"María Eugenia Gutiérrez (Titular)\",\"María José Gutiérrez (Titular)\",\"Mariela (Senior)\",\"Cesia (Junior)\"],\"resumen\":\"María Eugenia y María José llevan adelante Vico + Tita, proyecto de diseño textil y accesorios con impronta mapuche contemporánea. Emplean tintes naturales, serigrafía y estampas inspiradas en la flora andina. Cuentan con un producto consolidado y estéticamente impecable, pero necesitan profesionalizar la estructura de costos y planificar el volumen para el canal mayorista.\",\"diagnostico_claves\":[\"Propuesta de diseño de autor con narrativa identitaria potente y acabados de alta calidad.\",\"Taller propio equipado con mesas de estampado, máquinas de coser y depósito de materiales.\",\"Excelente respuesta del público en ferias de diseño y ventas directas por Instagram.\",\"Dificultad para calcular el costo por minuto de mano de obra y los costos indirectos de taller.\"],\"trabas_detectadas\":[\"Insumos textiles base (liencillos, gabardinas, lanas) provenientes de Buenos Aires con altos fletes.\",\"Cuello de botella en la etapa de confección y estampado durante los meses de alta demanda.\",\"Falta de un catálogo mayorista con precios diferenciales para boutiques patagónicas.\"],\"acuerdos_previos\":[\"Armar la planilla de costeo unitario de cada línea de productos (bolsos, pañuelos, estuches, delantales).\",\"Desarrollar el catálogo mayorista digital con cantidades mínimas y condiciones de envío.\",\"Crear etiquetas colgantes con la explicación cultural y botánica de la estampa de cada pieza.\",\"Planificar la producción con 60 días de anticipación a la temporada de verano.\"],\"citas_textuales\":[\"\\\"Nuestras estampas no son dibujos al azar: cada una tiene el nombre de una hierba de acá y un significado que nos transmitió nuestra abuela.\\\"\",\"\\\"Vendemos todo lo que producimos, pero a fin de mes nos cuesta ver reflejada la ganancia porque no teníamos bien medidos los costos.\\\"\"],\"texto_completo\":\"## Minuta Cero: Encuentro Diagnóstico Inicial · Vico + Tita\\n\\n**Fecha:** 20 de agosto de 2026 | **Sede:** Taller Vico + Tita, Esquel\\n**Asistentes:** María Eugenia y María José Gutiérrez (Titulares), Mariela (Senior), Cesia (Junior)\\n\\n### 1. Perfil y Oportunidad Detectada\\nDiseño textil y objetos de autor con identidad mapuche y flora nativa. Fuerte potencial para posicionarse en tiendas de diseño y hotelería boutique de toda la Patagonia.\\n\\n### 2. Cuellos de Botella Relevados\\n- **Costos y rentabilidad:** Transparentar el valor hora de confección y fijar precios con margen seguro.\\n- **Capacidad productiva:** Organizar lotes de producción para no agotar stock en los primeros días del verano.\\n- **Canal B2B:** Necesidad de material gráfico para locales que quieran revender la marca.\\n\\n### 3. Compromisos de Arranque\\n1. Planilla de costos y precios de venta minorista/mayorista.\\n2. Catálogo digital de temporada.\\n3. Etiquetas narrativas para cada prenda o accesorio.\"}"],
        ["carpint", 33, "Carpintero Esquel", "José Maximiliano Manquin", "Acelera", 3.25, 1, "mariela", "cesia", "[\"Artesano de la madera nacido y criado en Barrio Estación (Esquel, 38 años), con formación técnica formal de 3 años en carpintería de banco y torneado en el Centro de Formación Profesional (CFP) Nº 655 de calle Chacabuco, egresado con honores.\",\"Capacidad técnica y productiva demostrada en torno de madera y banco: confecciona cuencos, mates torneados, platos de asado, fuentes y mobiliario artesanal en maderas nobles (lenga, ciprés, radal). Dispone de taller de armado, torneado y lijado en el patio de su vivienda (calle Brown 1570) y utiliza la maquinaria pesada del Centro de Apoyo a la Producción de Esquel (CAPEC) pagando el canon de uso comunitario ('CAM') para tareas de cepillado y dimensionado grueso.\",\"Estructura familiar y vocación de arraigo: padre de 4 hijos (de 14, 10, 8 años y un lactante de 10 meses), su esposa es docente de nivel inicial y apoya en la gestión comercial. Disponibilidad horaria neta en turnos matutinos (08:30 a 14:30) y fines de semana para recepción turística.\"]", "[\"Cuello de botella en maquinado primario y estacionalidad edilicia: dependencia del taller del CAPEC para escuadrado y cepillado de tablones en bruto; taller hogareño expuesto al invierno cordillerano por falta de cerramiento y aislación térmica adecuada.\",\"Dispersión de catálogo y sub-costeo artesanal: coexistencia de pedidos a medida de carpintería general (muebles, aberturas) con piezas torneadas de souvenirs, sin una matriz que dimensione horas-hombre de torno, desgaste de gubias, lijas y acabados alimentarios no tóxicos (cera de abejas y aceite mineral).\",\"Falta de canales de comercialización fijos y experiencia vivencial inexplorada: inexistencia de puntos de venta en el circuito céntrico o tiendas de montaña, y desaprovechamiento del valor patrimonial del torno en vivo como experiencia turística comunitaria en Barrio Estación.\"]", "[{\"t\":\"Curaduría del Catálogo Turístico B2B (4 Piezas Estrella)\",\"items\":[\"Selección y estandarización de las 4 piezas insignia: Cuenco Mediano Torneado, Mate Rústico con Virola o Base Firme, Plato de Asado Patagónico y Cuchara Rústica con Grabado.\",\"Identidad y autenticidad: marca 'Carpintero Esquel' aplicada a fuego, etiqueta colgante de madera noble con origen regional y acabado no tóxico con aceites naturales.\"]},{\"t\":\"Experiencia 'Taller Abierto en Barrio Estación'\",\"items\":[\"Diseño de la vivencia turística para grupos reducidos (2 a 4 personas): demostración de torneado en vivo, participación en lijado y pulido de su propia pieza, marcado a fuego y mateada campesina tradicional.\",\"Protocolo estricto de bioseguridad: zona segura demarcada a 1,5 metros del torno, uso obligatorio de antiparras y protección auditiva; turista nunca opera herramientas de corte.\"]},{\"t\":\"Estructura de Costos, Canales Comerciales y Mejora de Infraestructura\",\"items\":[\"Planilla paramétrica de costos y fijación de precios mayoristas y minoristas para regionales y hoteles.\",\"Colocación en consignación en al menos 2 comercios céntricos con remito formal a 15 días.\",\"Articulación con Secretaría de Producción / CAPEC (Paula Botto) para formulación de proyecto de financiamiento para cerramiento y aislación del taller.\"]}]", "[\"Ficha técnica y costos estandarizados de las 4 piezas de la Línea Turística Estrella.\",\"Catálogo digital profesional (PDF y ficha técnica de producto) con fotografía 4K de piezas.\",\"Protocolo operativo y de seguridad para la experiencia 'Taller Abierto en Barrio Estación'.\",\"Acuerdo de consignación y colocación de stock inicial en al menos 2 comercios céntricos o regionales de Esquel.\",\"Proyecto técnico-económico de mejora edilicia del taller formulado para presentación ante líneas de crédito productivas.\"]", "{\"estado\":\"completada\",\"titulo\":\"Minuta Cero · Entrevista Inicial de Diagnóstico\",\"fecha\":\"21/08/2026\",\"hora\":\"16:00\",\"lugar\":\"Taller Carpintero Esquel, Esquel\",\"participantes\":[\"José Maximiliano Manquin (Titular)\",\"Leandro (Conducción)\",\"Mariela (Senior)\",\"Francisco (Junior)\"],\"resumen\":\"Maximiliano Manquin produce objetos de diseño y tablas gourmet en maderas nativas caídas y recuperadas (lenga, radal, ciprés, maitén). Posee un oficio minucioso y pasión por la madera. Sin embargo, su producción está atomizada en pedidos a medida y carece de una línea seriada de piezas transportables pensada para el equipaje del turista.\",\"diagnostico_claves\":[\"Maestría en el trabajo de maderas nobles y uso de acabados atóxicos con ceras naturales de abejas.\",\"Maquinaria pesada propia de carpintería y espacio de trabajo operativo.\",\"Gran atractivo visual y táctico de sus piezas en exhibiciones artesanales.\",\"Precios fijados por comparación y no por tiempo de elaboración y desgaste de herramientas.\"],\"trabas_detectadas\":[\"Piezas de gran volumen o peso que dificultan su traslado en avión por parte de los turistas.\",\"Falta de stock continuo de productos listos para la venta inmediata.\",\"Inexistencia de packaging y folletería que certifique la especie botánica y el cuidado de la pieza.\"],\"acuerdos_previos\":[\"Estandarizar la \\\"Línea Cordillera\\\": 3 modelos de tablas de autor y accesorios gourmet de peso reducido.\",\"Diseñar packaging plano en cartón reciclado con instrucciones de curado y origen de la madera.\",\"Calcular el costo real por pieza incluyendo hora de taller y amortización de maquinaria.\",\"Vincular con tiendas de delicatessen y bodegas de la comarca para venta consignada.\"],\"citas_textuales\":[\"\\\"Una tabla de lenga tiene 80 años de viento y nieve adentro; cuando el turista la toca, siente el peso y el aroma de la cordillera.\\\"\",\"\\\"Quiero dejar de hacer muebles pesados por encargo y enfocarme en piezas de diseño que la gente se pueda llevar en la valija.\\\"\"],\"texto_completo\":\"## Minuta Cero: Encuentro Diagnóstico Inicial · Carpintero Esquel\\n\\n**Fecha:** 21 de agosto de 2026 | **Sede:** Taller Carpintero Esquel, Esquel\\n**Asistentes:** José Maximiliano Manquin (Titular), Leandro (Conducción), Mariela (Senior), Francisco (Junior)\\n\\n### 1. Perfil y Oportunidad Detectada\\nObjetos de diseño y utilitarios en maderas nativas recuperadas. Oportunidad en el segmento de regalos turísticos premium y gastronomía de autor.\\n\\n### 2. Cuellos de Botella Relevados\\n- **Transportabilidad:** Rediseñar dimensiones y peso para facilitar el embarque aéreo.\\n- **Estandarización:** Crear modelos repetibles sin perder el carácter artesanal.\\n- **Costos:** Estructurar el valor hora de taller para asegurar margen comercial.\\n\\n### 3. Compromisos de Arranque\\n1. Fichas técnicas de la Línea Cordillera (3 piezas insignia).\\n2. Prototipo de packaging con historia y sello de origen.\\n3. Planilla de costos de producción y lista de precios.\"}"],
        ["corcho", 14, "Corcho Bikes", "Néstor Andrés Colinecul", "Acelera", 3.13, 4, "leandro", "agustina", "[\"Néstor Andrés 'Corcho' Colinecul pedalea desde los 11 años de forma continua (cumpliendo 50 años). Su padre le construyó su primera bicicleta en 1989, iniciando una carrera con múltiples títulos provinciales y regionales en ruta y MTB. Posee una autoridad técnica, deportiva y territorial inobjetable.\",\"Su taller mecánico en Barrio Los Sauces (calle 44, casa 28) opera desde 2019 a solo 2 cuadras de La Trochita y 3 de la subida al cementerio. Funciona espontáneamente como un club social barrial donde clientes y ciclistas pasan horas tomando mate mientras él realiza services mecánicos.\",\"Emprendimiento familiar con rol activo de su compañera y su hija (competidora y estudiante). Su compañera elabora dulces caseros tradicionales con fruta de la zona, aportando un elemento gastronómico de enorme calidez para complementar las paradas de las guiadas.\",\"Cuenta con posicionamiento orgánico en Google Maps con excelentes reseñas espontáneas de turistas de distintas provincias y de Brasil, quienes destacan su honestidad, rapidez y rescate mecánico inmediato.\",\"Presentó un proyecto social aprobado por la sede vecinal Los Sauces para enseñar mecánica básica, reciclaje de piezas y destreza a niños del barrio. El desafío es reorientar esa vocación comunitaria hacia un modelo de turismo activo rentable y sostenible.\"]", "[\"Carencia total de flota de bicicletas para excursionistas: Corcho solo cuenta con su propia bicicleta MTB de competición (habiendo vendido unidades previas). Se requiere resolver una flota puente de 6 a 8 unidades con cascos homologados.\",\"Protección del taller y delimitación horaria: El taller mecánico diario es el sustento de la familia. El cicloturismo debe circunscribirse estrictamente a martes, jueves y sábados por la tarde (a partir de las 14:30), preservando las mañanas para reparaciones.\",\"Reencuadre de guardería a turismo activo y seguros: Superar la idea original de 'guardería comunitaria' e inscribirse formalmente en el registro de Turismo Activo de Esquel, con póliza de seguro de accidentes personales para cicloturistas.\",\"Inexistencia de plataforma web institucional y material audiovisual profesional: Falta un sitio institucional que detalle los circuitos y permita reservas online. La conducción (Leandro) programará e implementará la plataforma web de forma gratuita.\",\"Fijación de costos y tarifario comercial: Superar la oferta ad-honorem o a la gorra, estructurando una matriz de costos que permita fijar tarifas rentables y ofrecer comisiones (15% a 20%) a agencias y recepciones de hoteles.\"]", "[{\"t\":\"Paquetización de Experiencias y Cápsula Familiar\",\"items\":[\"Circuito Familiar 'Pedaleo y Merienda en las Vías': dinámica de 2 hs donde los niños tienen una clínica lúdica de destreza y mecánica básica en un entorno seguro, mientras los padres descansan con mateada y degustación de dulces caseros frente a La Trochita.\",\"Circuito 'Esquel Lado B y Taller Abierto': para jóvenes y parejas, con un 'mini service participativo' de 15 min en el taller (calibración de frenos y cadena, mate con anécdotas de competencia) y pedaleo por senderos panorámicos del cementerio y Calle 10.\",\"Souvenir identitario sustentable: lapicero o portallaves de escritorio confeccionado en el taller con piezas recicladas (eslabones, piñones, rayos) y frasco de dulce casero artesanal con etiqueta 'Corcho Bikes · Esquel'.\"]},{\"t\":\"Gestión de Flota, Operatividad y Normativa\",\"items\":[\"Esquema de provisión de flota puente mediante convenio con bicicleterías locales o rodados municipales (6 bicis calibradas) y fondo de amortización para flota propia.\",\"Adquisición de kit de seguridad homologado: cascos para niños y adultos, chalecos reflectivos, conos de señalización y botiquín de primeros auxilios.\",\"Inscripción en Turismo Activo de Esquel, contratación de póliza de seguro de accidentes personales para excursionistas y fichas de deslinde de responsabilidad.\"]},{\"t\":\"Plataforma Web, Producción Audiovisual y Comercialización\",\"items\":[\"Benchmarking internacional de sitios web de bike-tours de autor (EE.UU., Europa) para definir layout y narrativa.\",\"Desarrollo y puesta en línea de la plataforma web oficial de Corcho Bikes por parte de Leandro (historia de Corcho, circuitos, galería y botón de reserva WhatsApp Business).\",\"Producción audiovisual oficial con equipo de la Subsecretaría: video 4K con dron sobre las vías de La Trochita y tomas cinematográficas de taller.\",\"Diseño e impresión de la ficha comercial de una carilla para mostradores de hoteles, cabañas y agencias de viaje con tarifario y comisiones cerradas.\"]}]", "[\"Guion técnico de los dos circuitos ('Familiar en las Vías' y 'Lado B Taller Abierto').\",\"Sitio web institucional de Corcho Bikes programado y puesto en línea (con motor de reservas WhatsApp).\",\"Banco audiovisual profesional (video 4K con dron en La Trochita + tomas de taller en alta resolución).\",\"Protocolo de flota operativa y kit de seguridad homologado (cascos y elementos de protección).\",\"Prototipo del souvenir identitario conector (lapicero de partes recicladas + dulce casero con packaging).\",\"Ficha comercial y tarifario cerrado con esquema de comisiones para el sector receptivo.\"]", "{\"estado\":\"completada\",\"titulo\":\"Minuta Cero · Entrevista Inicial de Diagnóstico\",\"fecha\":\"21/08/2026\",\"hora\":\"17:30\",\"lugar\":\"Taller Corcho Bikes, Esquel\",\"participantes\":[\"Néstor Andrés Colinecul (Titular)\",\"Mariela (Senior)\",\"Francisco (Junior)\"],\"resumen\":\"Néstor Andrés Colinecul lidera Corcho Bikes, taller de referencia para ciclistas en Esquel. Está dando el salto hacia el servicio de alquiler de mountain bikes y cicloturismo para visitantes que quieren recorrer Laguna La Zeta, senderos de La Hoya y circuitos rurales. Requiere dotar al servicio de formalidad legal, protocolos de auxilio y rutas autoguiadas.\",\"diagnostico_claves\":[\"Reconocimiento unánime de la comunidad local como el mecánico de bicicletas más idóneo de Esquel.\",\"Ubicación céntrica estratégica para entrega y devolución de bicicletas.\",\"Flota inicial de bicicletas de montaña en excelente estado mecánico.\",\"Falta de contratos de deslinde, seguros y material orientativo para el turista no experto.\"],\"trabas_detectadas\":[\"Riesgo de roturas o robos por falta de contrato de comodato y tarjeta de crédito en garantía.\",\"Temor de los turistas a perderse en caminos de montaña o no saber reparar una pinchadura.\",\"Costos elevados de repuestos importados para renovar transmisiones y frenos.\"],\"acuerdos_previos\":[\"Redactar contrato de alquiler con deslinde de responsabilidad y toma de garantía.\",\"Desarrollar 3 tracks digitales descargables vía código QR en el manubrio (La Zeta, Valle Chico, La Hoya).\",\"Equipar cada bicicleta con casco homologado, kit de parches, inflador y candado de seguridad.\",\"Establecer servicio de auxilio mecánico coordinado en caso de emergencias en ruta.\"],\"citas_textuales\":[\"\\\"El turista quiere pedalear pero tiene miedo de perderse o de quedarse tirado en una subida. Si le das la bici perfecta y el mapa en el celular, sale feliz.\\\"\",\"\\\"La mecánica ya la tengo resuelta; lo que necesito es el papel, el contrato y la forma de cobrar para que sea un negocio rentable y seguro.\\\"\"],\"texto_completo\":\"## Minuta Cero: Encuentro Diagnóstico Inicial · Corcho Bikes\\n\\n**Fecha:** 21 de agosto de 2026 | **Sede:** Taller Corcho Bikes, Esquel\\n**Asistentes:** Néstor Andrés Colinecul (Titular), Mariela (Senior), Francisco (Junior)\\n\\n### 1. Perfil y Oportunidad Detectada\\nAlquiler y soporte técnico para cicloturismo en Esquel y la Comarca. Demanda creciente de movilidad sustentable y paseos autoguiados.\\n\\n### 2. Cuellos de Botella Relevados\\n- **Marco contractual:** Contratos de alquiler y garantías para resguardo del equipamiento.\\n- **Experiencia de usuario:** Facilitar navegación sencilla por circuitos escénicos seguros.\\n- **Tarifas y paquetes:** Definir esquemas por medio día, día completo y fin de semana.\\n\\n### 3. Compromisos de Arranque\\n1. Modelo legal de contrato y deslinde de responsabilidad.\\n2. Fichas digitales con tracks QR para los 3 circuitos principales.\\n3. Estandarización del kit de seguridad por unidad alquilada.\"}"],
        ["retro", 8, "Patagonia Retro", "Paula Salvo", "Acelera", 3.12, 1, "mariela", "cesia", "[\"Colección nostálgica de más de 7 años de objetos cotidianos e históricos de Esquel.\",\"Espacio físico en complejo de alojamiento.\",\"Gran potencial para museo vivencial y tienda vintage.\"]", "[\"Separación física del acceso para no invadir la privacidad de las cabañas.\",\"Guion museográfico y cédulas explicativas.\"]", "[{\"t\":\"Apertura al Público\",\"items\":[\"Diseño de recorrido y señalética independiente.\",\"Horarios fijos de visita para tardes de lluvia/descanso.\"]},{\"t\":\"Tienda Vintage\",\"items\":[\"Selección de antigüedades y réplicas a la venta.\",\"Entrada arancelada con consumición o recuerdo.\"]}]", "[\"Guion museográfico de las salas temáticas.\",\"Entrada y horarios fijados y comunicados a Turismo.\"]", "{\"estado\":\"pendiente\",\"titulo\":\"Minuta Cero · Entrevista Inicial de Diagnóstico (Pendiente)\",\"fecha\":\"\",\"hora\":\"\",\"lugar\":\"Predio Patagonia Retro, Esquel\",\"participantes\":[\"Paula Salvo (Titular)\"],\"resumen\":\"Encuentro diagnóstico preliminar pendiente de realización. Proyecto seleccionado en el Puesto #10 de la línea Esquel Acelera. El emprendimiento consiste en un museo y quincho de antigüedades cotidianas patagónicas (botellas históricas, sifones, carteles enlozados, juguetes retro y objetos de época).\",\"diagnostico_claves\":[],\"trabas_detectadas\":[],\"acuerdos_previos\":[],\"citas_textuales\":[],\"texto_completo\":\"\"}"],
        ["margher", 3, "Establecimiento Margherita", "Dante José Oliva y compañera", "Raíz", 4.42, 2, "adria", "noelia", "[\"Iniciativa de excelencia y máxima puntuación de la línea Esquel Raíz (Puesto #1 · 4.42/5.00 con calificación perfecta 5.00 de la Dirección). Establecimiento agropecuario de 500 hectáreas sobre la ladera sur del Cerro Nahuelpan, a 18 km de Esquel y en el límite con Trevelin, en un entorno de imponente belleza cordillerana.\",\"Solvencia productiva y patrimonio arquitectónico: cabaña de ovinos (mejora genética de carneros), cría y reproducción de asnos mansos de interacción, y apicultura profesional con la marca 'Oro de Esquel' (elaborada en la sala habilitada de CAPEC con tránsito federal). Cuenta con una casita centenaria de más de 100 años de adobe y tejuelas de alerce restaurada.\",\"Definición estratégica del modelo: priorización del Agroturismo de Día de Campo, talleres vivenciales y eventos de calendario cerrado (Fiesta de la Esquila en coincidencia con Tulipanes en octubre, y jornadas nocturnas de Astroturismo con pizzas a la parrilla), preservando la casita histórica como refugio boutique estacional para no sobrecargar las tareas rurales de los titulares.\"]", "[\"Sobrecarga operativa y riesgo de dispersión: necesidad de acotar la oferta al agroturismo diurno programado con reserva previa y cupos estrictos (8 a 15 personas), evitando la demanda de limpieza y lavandería continua que exigiría un hospedaje masivo.\",\"Soberanía comercial frente a intermediarios: evitar esquemas abusivos donde agencias externas revenden el acceso cobrando el doble y relegando al productor a un simple alquiler de predio; fijación de un precio único oficial y comisiones formalizadas del 20% para agencias EVyT y recepcionistas de hotel.\",\"Comercialización digital y atención de consultas: ausencia de plataforma web y pérdida de energía en mensajes manuales de WhatsApp sin cobro automatizado de señas; necesidad de producción audiovisual profesional con dron y cámaras 4K financiada por el LAB.\"]", "[{\"t\":\"Curaduría de Experiencias y Estandarización de Calidad Turística\",\"items\":[\"Diseño del guion interpretativo del 'Día de Campo Margherita' (apicultura con trajes y ahumador, interacción con asnos mansos y amasado participativo de tortas fritas en la galería).\",\"Estandarización de los eventos estrella: la 'Fiesta de la Esquila & Asado de Cordero Patagónico' (octubre) y las veladas de 'Astroturismo & Cielos del Nahuelpan' con pizzas a la parrilla y telescopio.\"]},{\"t\":\"Plataforma Web Transaccional y Producción Audiovisual 4K con Dron\",\"items\":[\"Desarrollo ad-honorem a cargo de Leandro Choi de la plataforma web transaccional con pasarela de pagos integrada, reserva de turnos online y catálogo de productos de la granja.\",\"Jornada de filmación y fotografía profesional con cámaras 4K y dron en la ladera sur del Nahuelpan para banco de contenidos y cápsulas de apicultura, ovinos y casita de adobe.\"]},{\"t\":\"Costeo Paramétrico, Tarifario Unificado B2C/B2B y Fam Tour\",\"items\":[\"Planilla paramétrica de costos y fijación de tarifas con margen del 20% de comisión formal para agencias receptivas y recepcionistas de hoteles boutique de Esquel y Trevelin.\",\"Realización de un Fam Tour exclusivo para fidelizar a los operadores locales y normalización de la etiqueta de miel 'Oro de Esquel' con la estética de la tranquera histórica.\"]}]", "[\"Manual operativo y guiones interpretativos estandarizados de las 3 experiencias (Día de Campo, Fiesta de la Esquila y Noche de Astroturismo).\",\"Plataforma web transaccional institucional desarrollada por Leandro Choi con motor de reservas y cobro de señas automatizado.\",\"Banco de contenidos audiovisuales profesionales: 30 fotografías 4K en alta resolución y cápsulas institucionales con tomas aéreas de dron.\",\"Planilla paramétrica de costos y tarifario oficial unificado minorista/mayorista (B2C y B2B) con comisiones del 20%.\",\"Etiqueta rediseñada de la miel 'Oro de Esquel' vinculada a la identidad visual de la tranquera y la casita de adobe.\",\"Convenios comerciales de derivación turística firmados con al menos 2 agencias receptivas habilitadas y 2 hoteles boutique de la Comarca.\"]", "{\"estado\":\"completada\",\"titulo\":\"Minuta Cero · Entrevista Inicial de Diagnóstico\",\"fecha\":\"11/09/2026\",\"hora\":\"15:30\",\"lugar\":\"Establecimiento Margherita, Valle de Trevelin\",\"participantes\":[\"Dante José Oliva (Titular)\",\"Leandro (Conducción)\",\"Adria (Senior)\",\"Noelia (Junior)\"],\"resumen\":\"Dante Oliva conduce Establecimiento Margherita, finca agroturística con viñedos de clima extremo, plantaciones experimentales de olivos, frutales y elaboración de vinos y licores artesanales. El predio posee una belleza paisajística imponente. El desafío reside en organizar el flujo de visitantes para que la atención turística no perjudique las demandantes tareas agrícolas.\",\"diagnostico_claves\":[\"Viñedo en espaldero y monte frutal cuidado con prácticas agroecológicas sustentables.\",\"Elaboración propia de vinos con tipicidad patagónica y licores de frutos cordilleranos.\",\"Excelente ubicación sobre los circuitos turísticos del valle cordillerano.\",\"Gran pasión y conocimiento botánico y enológico por parte de sus titulares.\"],\"trabas_detectadas\":[\"Ausencia de espacio cubierto calefaccionado para recibir visitantes en días de lluvia o frío.\",\"Trámites de registro formal de marcas y etiquetas de bebidas ante los organismos competentes.\",\"Atención turística que hoy interrumpe tareas de poda, raleo o vendimia.\"],\"acuerdos_previos\":[\"Diseñar el recorrido guiado \\\"Del Frutal a la Copa\\\" con estaciones delimitadas y horario fijo.\",\"Establecer una tarifa de visita con cata dirigida y voucher de descuento para compra de botellas.\",\"Protocolizar la atención de grupos bajo reserva previa obligatoria en días puntuales de la semana.\",\"Adecuar un sector de recepción al aire libre con pérgola y cartelería explicativa de las variedades.\"],\"citas_textuales\":[\"\\\"Acá las plantas tienen que bancarse las heladas y el viento; cuando abrís una botella de nuestro vino sentís el sacrificio de años de domesticar el valle.\\\"\",\"\\\"Nos encanta recibir a la gente, pero no podemos parar de podar en medio de la temporada; necesitamos días fijos y turnos ordenados.\\\"\"],\"texto_completo\":\"## Minuta Cero: Encuentro Diagnóstico Inicial · Establecimiento Margherita\\n\\n**Fecha:** 11 de septiembre de 2026 | **Sede:** Establecimiento Margherita, Trevelin\\n**Asistentes:** Dante José Oliva (Titular), Leandro (Conducción), Adria (Senior), Noelia (Junior)\\n\\n### 1. Perfil y Oportunidad Detectada\\nAgroturismo y enoturismo en viñedo y frutales de clima frío. Experiencia sensorial completa de cata y aprendizaje productivo.\\n\\n### 2. Cuellos de Botella Relevados\\n- **Compatibilidad de tareas:** Separar los tiempos de trabajo en campo de la atención al visitante.\\n- **Espacio de cata:** Acondicionar un sector de degustación confortable y resguardado.\\n- **Marco normativo:** Avanzar en registros de marca y habilitaciones de enoturismo.\\n\\n### 3. Compromisos de Arranque\\n1. Guion del paseo \\\"Del Frutal a la Copa\\\" y estaciones de degustación.\\n2. Esquema de turnos de visita con reserva anticipada.\\n3. Diseño de la propuesta de cata y maridaje regional.\"}"],
        ["lucero", 18, "Centro Integral Ecuestre Lucero", "María Soledad Arrechea", "Raíz", 4.02, 2, "adria", "noelia", "[\"Iniciativa de excelencia en turismo rural, de naturaleza y bienestar en predio cordillerano sobre Ruta 259 (km 25 / Barrio Los Cóndores), a mitad de camino entre Esquel y Trevelin. Cuenta con bosque centenario de pinos ('El Pinar'), matera histórica alemana, pista de monta y corrales en comodato con Carlos Baroli.\",\"Trayectoria consolidada y solvencia interdisciplinaria: titular bióloga y docente de biología (Colegio Salesiano), cofundadora de la Fundación Patagónica de Equinoterapia (2011). Integra un equipo de salud (psicomotricista, kinesiólogo, psicóloga, docentes especiales y ecuestres) junto al programa comunitario 'Guardianes de Lucero'. Compromiso personal de Leandro Choi (conducción del LAB, padre de un niño con autismo) para asumir personalmente el desarrollo de la plataforma web transaccional.\",\"Propuesta integral cuádruple: 1) Granja Educativa de Rescate (chinchillas, ratas de laboratorio, cerdita minipig Rita Uva, Pamperito de 35 años); 2) Escuela de Monta Consciente y Respetuosa (sin someter al caballo, pie a tierra y rienda suave); 3) Equinoterapia Interdisciplinaria con alta demanda sostenida; y 4) Terapias de Bienestar (yoga, meditación y constelaciones con caballos, coaching y feria El Paseo del Pinar).\"]", "[\"Dispersión operativa y falta de paquetización comercial: necesidad de acotar la oferta para el visitante espontáneo a 2 experiencias claras con días fijos (martes, miércoles y sábados) para no interferir con la docencia escolar ni con la equinoterapia de los viernes.\",\"Estacionalidad forrajera invernal y ciclo natural: cierre en invierno por descanso de la manada y alto costo de fardos de alfalfa y avena (sin pastura en el pinar), requiriendo un flujo turístico en temporada que subsidie la sustentabilidad y el recambio de suelo con compost orgánico cada septiembre.\",\"Gestión de reservas y seguros (Patagonia Broker / Mercantil Andina): necesidad de prueba de pista obligatoria previa a la cabalgata para evaluar la mano del jinete y cuidar la boca del caballo, requiriendo un sistema digital que exija antelación para el alta de póliza y evite la subvaloración tarifaria frente al mercado (Frisón Baroque cobra $90.000 vs $20.000-$40.000 de Lucero).\"]", "[{\"t\":\"Curaduría de 2 Experiencias Estrella, Seguridad y Seguros\",\"items\":[\"Experiencia 1: 'Granja Educativa & Saberes Vivos' (75 min, familiar y niños, historias de rescate, interacción perimetral sin boyero y merienda en la matera).\",\"Experiencia 2: 'Bautismo Ecuestre & Encuentro con el Caballo' (90 min, vínculo pie a tierra, cepillado, prueba en pista obligatoria para cuidar la boca del animal y paseo en El Pinar).\",\"Protocolo formal de seguridad y gestión de seguros (Patagonia Broker / Mercantil Andina) con recolección previa obligatoria de datos vía web.\"]},{\"t\":\"Plataforma Web Transaccional y Producción Audiovisual 4K\",\"items\":[\"Desarrollo a cargo de Leandro Choi de la plataforma web transaccional con backend para gestión de cupos, días disponibles (mar/mié/sáb), cobro de señas y datos para el alta de seguros.\",\"Producción audiovisual profesional financiada por el LAB (cámaras 4K + dron): 3 cápsulas documentales (historia de arraigo de Sol y su abuelo Toto Arrechea, coaching en El Pinar y Guardianes de Lucero).\"]},{\"t\":\"Estructura de Costos Forrajeros, Tarifario Dual y Alianzas B2B\",\"items\":[\"Planilla paramétrica de costos que amortice el forraje invernal y nuevo tarifario comercial: tarifa general turista vs tarifa social para residentes esquelenses/trevelinenses.\",\"Kit físico infantil 'Pequeño Cuidador / Guardián de Lucero', souvenirs de compost/semillas, alianzas con agencias receptivas de la Comarca y sinergia con Haiku Casa de Té.\"]}]", "[\"Fichas técnicas y guiones interpretativos estandarizados de las 2 Experiencias Turísticas ('Granja Educativa' y 'Bautismo Ecuestre').\",\"Protocolo de bioseguridad, deslinde de responsabilidad y circuito de alta previa de seguros Patagonia Broker con prueba en pista obligatoria.\",\"Plataforma web transaccional operativa desarrollada por Leandro Choi con panel de administración de turnos y cupos.\",\"Banco de contenidos audiovisuales 4K con tomas aéreas con dron y 3 cápsulas de video institucionales.\",\"Planilla de costeo paramétrico de forraje invernal y tarifario comercial minorista/mayorista (B2C general y residente / B2B agencias receptivas).\",\"Kit del 'Pequeño Cuidador / Guardián de Lucero' prototipado (libreta de campo, pin de madera y pack de semillas/compost) y acuerdos con agencias.\"]", "{\"estado\":\"completada\",\"titulo\":\"Minuta Cero · Entrevista Inicial de Diagnóstico\",\"fecha\":\"21/08/2026\",\"hora\":\"10:15\",\"lugar\":\"Predio Centro Lucero, Esquel\",\"participantes\":[\"María Soledad Arrechea (Titular)\",\"Leandro (Conducción)\",\"Adria (Senior)\",\"Noelia (Junior)\"],\"resumen\":\"María Soledad Arrechea es docente con más de 25 años en Esquel y conduce el Centro Ecuestre Lucero, espacio dedicado a la equinoterapia y equitación adaptada. El proyecto busca crear una unidad de turismo ecuestre formativo y paseos familiares para generar ingresos sostenibles que financien y subsidien la atención de pacientes con discapacidad.\",\"diagnostico_claves\":[\"Predio propio acondicionado con corrales, pista de arena y caballos con adiestramiento específico.\",\"Trayectoria intachable y reconocimiento social profundo en toda la comunidad de Esquel.\",\"Demanda turística constante de familias que buscan contacto seguro con caballos en vacaciones.\",\"Vocación docente y terapéutica que asegura un trato cálido y profesional a cada visitante.\"],\"trabas_detectadas\":[\"Riesgo de superposición entre los turnos de terapia de los chicos y los paseos recreativos de turistas.\",\"Costo de forraje y veterinario durante el invierno, cuando la actividad baja drásticamente.\",\"Pólizas de seguro que diferencien equinoterapia de turismo ecuestre recreativo.\"],\"acuerdos_previos\":[\"Separar tajantemente los días y horarios de terapias respecto del turismo ecuestre.\",\"Lanzar la experiencia \\\"Bautismo a Caballo en la Cordillera\\\" (cepillado, monta asistida y merienda).\",\"Elaborar tarifario por hora de actividad y convenios de difusión con cabañas y hoteles.\",\"Estructurar una planilla de seguimiento de costos de manutención equina.\"],\"citas_textuales\":[\"\\\"El caballo tiene una energía que sana; un chico que sube asustado se baja sonriendo y con otra postura ante el mundo.\\\"\",\"\\\"Quiero que el turismo sea el motor que me permita seguir atendiendo a los chicos que necesitan la terapia y no pueden pagarla.\\\"\"],\"texto_completo\":\"## Minuta Cero: Encuentro Diagnóstico Inicial · Centro Integral Ecuestre Lucero\\n\\n**Fecha:** 21 de agosto de 2026 | **Sede:** Predio Centro Lucero, Esquel\\n**Asistentes:** María Soledad Arrechea (Titular), Leandro (Conducción), Adria (Senior), Noelia (Junior)\\n\\n### 1. Perfil y Oportunidad Detectada\\nTurismo ecuestre consciente y equinoterapia en predio propio. Propuesta con fuerte impacto social y conexión con la naturaleza.\\n\\n### 2. Cuellos de Botella Relevados\\n- **Segmentación de público:** Distinguir claramente la propuesta turística del servicio de salud.\\n- **Sustentabilidad invernal:** Generar fondos en verano para cubrir la alimentación de los caballos todo el año.\\n- **Aseguramiento:** Contratación de pólizas acordes a la actividad turística.\\n\\n### 3. Compromisos de Arranque\\n1. Paquete turístico \\\"Bautismo Ecuestre\\\" con ficha y precio.\\n2. Calendario semanal con turnos exclusivos para turismo.\\n3. Material de difusión para alojamientos de Esquel.\"}"],
        ["sabor", 7, "Sabor Mapuche", "Lauriano Jose Rios y Nora Yanina Nahuelpan", "Raíz", 3.74, 3, "adria", "francisco", "[\"Baluarte patrimonial, cultural y gastronómico de turismo rural comunitario en la histórica Comunidad Nahuelpan (a 15 km de Esquel), sobre paisaje de transición precordillera-estepa. Epicentro en 'Casa de Piedra', la antigua escuela comunitaria recuperada y techada por la familia de Nora Yanina Nahuelpan.\",\"Trayectoria de 15 años liderada por Lauriano Ríos (formado en producción avícola en Rauch, exdirigente juvenil de Federación Agraria y delegado RENAP) junto a Yanina Nahuelpan. Antecedente emblemático de las 5 ediciones del Festival 'Sabor Mapuche - Alimentos de la Tierra', apadrinado por Rubén Patagonia y con renombrados chefs patagónicos (Fefe Domínguez, Bruno de Berbina, Freddy Álvarez).\",\"Propuesta integral multidimensional: 1) Producción de alimentos con identidad (sales de la abuela, merkén ahumado, alfajores de ñaco, licores); 2) Conservación genética de la Gallina Mapuche (huevo celeste/verde de cáscara gruesa, incubadora comunitaria de 1.000 huevos); 3) Sendero interpretativo 'La Huella del Cóndor' con taller de amasado participativo y merienda campesina en Casa de Piedra; y 4) Ceremonia ancestral del Curanto al Hoyo con ramas de Maqui de Los Alerces.\"]", "[\"Cuello de botella en infraestructura sanitaria en Casa de Piedra: cámara séptica y pozo ciego ya terminados y operativos, pero faltan terminaciones finas (cerámicos, grifería, artefactos sanitarios y pintura exterior) para habilitar contingentes regulares.\",\"Logística e insumo regulado para el Curanto Ancestral: necesidad de autorización formal de Parques Nacionales para que el poblador Paulo Rosales pueda extraer sustentablemente 5 m³ de ramas de maqui en Los Alerces (que reemplazan la nalca evitando sabores amargos y optimizando retención de calor).\",\"Dispersión comunicacional y falta de canal transaccional: marcas divididas (@sabormapucheok vs @huelladelcondor), ausencia de sitio web y necesidad de visibilizar y empoderar a Nora Yanina Nahuelpan como la portadora legítima del linaje e identidad comunitaria.\"]", "[{\"t\":\"Curaduría de Experiencias Turísticas, Bienestar Animal y Sendero\",\"items\":[\"Estandarización de la experiencia 'Sendero La Huella del Cóndor & Taller de Amasado Comunitario' (2h 30min), con Yanina Nahuelpan al frente de los panificados campesinos y merienda en Casa de Piedra.\",\"Protocolo estricto de bienestar animal (erradicación total de prácticas invasivas, circuito avícola delimitado con pallets y postes, observación de incubadora y Gallina Mapuche) y guion ceremonial del respeto al agua en la vertiente.\"]},{\"t\":\"Plataforma Web Transaccional, Identidad Paraguas y Estrategia Audiovisual\",\"items\":[\"Desarrollo de la plataforma web transaccional (sabormapuche.com.ar) con tienda online de productos gourmet y sistema de reservas con cupos por turno (hasta 15 personas).\",\"Estrategia audiovisual en redes: 5 microvideos dinámicos de 15 segundos (fuego en las piedras, amasado, destape de curanto, ritual del agua), banco de 30 fotos 4K y diseño de tazas enlosadas institucionales con logo Sabor Mapuche.\"]},{\"t\":\"Costeo Paramétrico, Comercialización B2B, Habilitación Sanitaria y Curanto Mensual\",\"items\":[\"Planilla paramétrica de costos y tarifario dual (general turista vs social residente), más 20-25% de comisión para agencias receptivas de Esquel y Trevelin.\",\"Gestión de financiamiento ante Producción/CAPEC (Paula Botto) para terminación de sanitarios en Casa de Piedra, seguimiento de la autorización de Parques Nacionales para ramas de maqui y estandarización del curanto mensual.\"]}]", "[\"Ficha técnica estandarizada y guion interpretativo de la experiencia 'Sendero La Huella del Cóndor & Taller de Amasado Comunitario en Casa de Piedra', con protocolo de bienestar animal.\",\"Manual operativo y de seguridad del 'Curanto de Nahuelpan', con circuito sustentable de recolección de ramas de maqui autorizado por Parques Nacionales.\",\"Plataforma web transaccional operativa (sabormapuche.com.ar) con pasarela de pagos integrada, tienda online y sistema de reservas de experiencias.\",\"Banco de contenidos audiovisuales profesionales: 30 fotografías 4K en alta resolución y serie de 5 microvideos de 15 segundos para redes sociales.\",\"Planilla paramétrica de costos y tarifario comercial minorista/mayorista (B2C y B2B) oficializado para agencias receptivas y prestadores.\",\"Expediente técnico de financiamiento ante Producción/CAPEC para la terminación de sanitarios en Casa de Piedra y acuerdos comerciales con al menos 2 agencias receptivas.\"]", "{\"estado\":\"completada\",\"titulo\":\"Minuta Cero · Entrevista Inicial de Diagnóstico\",\"fecha\":\"11/09/2026\",\"hora\":\"14:00\",\"lugar\":\"Comunidad Nahuelpán / Río Percy\",\"participantes\":[\"Lauriano José Ríos (Titular)\",\"Nora Yanina Nahuelpan (Titular)\",\"Leandro (Conducción)\",\"Adria (Senior)\",\"Francisco (Junior)\"],\"resumen\":\"Lauriano Ríos y Yanina Nahuelpan lideran Sabor Mapuche, colectivo gastronómico que rescata recetas ancestrales, curantos, panes al rescoldo y salsas silvestres con hierbas cordilleranas. Su participación en ferias y eventos demostró una atracción magnética. Requieren formalizar su esquema de atención turística con fechas regulares y cumplimiento de normativas bromatológicas.\",\"diagnostico_claves\":[\"Propuesta culinaria de raíz con identidad originaria auténtica y reconocimiento a nivel provincial y nacional.\",\"Conocimiento profundo de las materias primas nativas (brotes, hongos, especias y carnes tradicionales).\",\"Experiencia previa en programas de jóvenes emprendedores y giras de turismo rural con INTA.\",\"Gran capacidad de convocatoria en fechas especiales y eventos comunitarios.\"],\"trabas_detectadas\":[\"Falta de un espacio físico propio con habilitación bromatológica permanente para recibir contingentes.\",\"Logística de traslado de comensales desde Esquel hacia los puntos de banquete en Nahuelpán.\",\"Estacionalidad estricta de las materias primas silvestres de recolección.\"],\"acuerdos_previos\":[\"Establecer el ciclo de \\\"Banquetes Ancestrales\\\": 2 encuentros mensuales programados con menú por pasos.\",\"Calcular el costo detallado de insumos y mano de obra por comensal para fijar una tarifa rentable.\",\"Formalizar acuerdos con transportistas y agencias para ofrecer el combo \\\"Traslado + Banquete\\\".\",\"Avanzar en la estandarización de sus salsas y sales saborizadas para comercialización como producto empaquetado.\"],\"citas_textuales\":[\"\\\"Nuestra cocina no es comida rápida ni de restaurante común; es compartir el fuego, el relato y lo que la tierra nos brinda.\\\"\",\"\\\"Queremos que quien venga a Nahuelpán se siente a la mesa y entienda que cada bocado tiene cientos de años de historia viva.\\\"\"],\"texto_completo\":\"## Minuta Cero: Encuentro Diagnóstico Inicial · Sabor Mapuche\\n\\n**Fecha:** 11 de septiembre de 2026 | **Sede:** Nahuelpán / Río Percy\\n**Asistentes:** Lauriano Ríos, Yanina Nahuelpan (Titulares), Leandro (Conducción), Adria (Senior), Francisco (Junior)\\n\\n### 1. Perfil y Oportunidad Detectada\\nGastronomía ancestral mapuche y banquete vivencial en territorio. Propuesta emblemática de rescate cultural con demanda internacional.\\n\\n### 2. Cuellos de Botella Relevados\\n- **Instalaciones y habilitación:** Protocolos higiénico-sanitarios y cocina habilitada.\\n- **Logística:** Organización del traslado de pasajeros hacia la comunidad.\\n- **Previsibilidad:** Fijar fechas fijas de servicio para que las agencias puedan venderlas con meses de antelación.\\n\\n### 3. Compromisos de Arranque\\n1. Calendario formal de los primeros Banquetes Ancestrales.\\n2. Menú cerrado con costeo y precio por persona.\\n3. Alianza con transporte turístico para salidas coordinadas.\"}"],
        ["laberin", 44, "El secreto del laberinto", "Marta Isabel San Martín", "Raíz", 3.63, 2, "adria", "noelia", "[\"Predio de 75 hectáreas (chacra familiar histórica, sucesión Austin) a 4 km de Esquel sobre Ruta 259, con frente de faldeo de monte y vistas panorámicas. Situación dominial resuelta y saneada. Parcela de casi 2 hectáreas asignada exclusivamente al laberinto vegetal.\",\"Equipo familiar con saberes complementarios: Marcelo Codesal (trabajo de campo y equinos), Florencia (Ingeniera Agrónoma que se recibe en diciembre 2026 y aporta rigor edáfico/botánico), Rocío (Lic. en Negocios Agropecuarios) y Joaquín (estudiante de Zootecnia y operador de cabalgatas). Marta posee amplia trayectoria en gastronomía (confitería concesionada) y terapias naturales.\",\"Infraestructura base avanzada: Perforación de agua nueva con bomba de alto caudal para riego por goteo, agua de vertiente para consumo, electricidad de red y platea de hormigón construida con acopio de materiales para salón de eventos/té de campo de 120 m² con sanitarios.\",\"Elección botánica perenne de 4 estaciones: Ligustro (Ligustrum) como especie estructurante para mantener el follaje verde en otoño e invierno bajo la nieve, complementado con especies florales nativas y arbustos decorativos en canteros centrales.\",\"Potencial de unidades puente inmediatas: En el predio habitan 14 a 15 caballos (6 propios mansos aptos para cabalgatas de faldeo), posibilitando activar paseos ecuestres, visitas al vivero de propagación y servicio de casa de té antes de la maduración definitiva del laberinto.\"]", "[\"Tiempos biológicos de crecimiento: El ligustro tarda de 3 a 5 temporadas en alcanzar altura adulta (1,80 a 2 m), aunque puede habilitarse prematuramente a 1 metro de altura con dinámicas lúdicas escolares y familiares. Se requiere estructurar actividades puente para generar ingresos inmediatos.\",\"Inversión económica inicial y necesidad de autoabastecimiento: Adquirir 4.000 plantas desarrolladas en viveros comerciales ($7.000 c/u) exigiría decenas de millones de pesos. Es imprescindible montar un vivero propio de multiplicación por esquejes con bioestimulación de sauce y riego asistido.\",\"Acondicionamiento del suelo árido y compactado: Para que los esquejes enraícen con vigor y ganen meses de crecimiento, se requiere un análisis agronómico de nutrientes/pH y una fuerte enmienda orgánica con abono de oveja (disponible en corrales familiares) y tierra negra antes de plantar.\",\"Trazado geométrico y replanteo de senderos: La traza circular concéntrica exige un Master Plan con mojones topográficos y asesoramiento paisajístico previo al zanjeo, además de rectificar la curva del camino de servidumbre que invadió parte de la parcela.\",\"Accesibilidad y validación comercial: Ubicado a 4 km del centro, debe validarse el perfil de transporte del visitante (auto particular vs taxi/receptivo), delimitar un estacionamiento para 30 vehículos y realizar encuestas de demanda (product-market fit) para afinar tarifas.\"]", "[{\"t\":\"Proyecto Agronómico, Suelo y Vivero de Multiplicación\",\"items\":[\"Muestreo y análisis de suelo en 4 sectores de la parcela para determinar pH, textura y nutrientes (conducido por Florencia Codesal), con enmienda masiva de abono de oveja y tierra negra.\",\"Diseño y montaje de un módulo rústico de vivero en el predio para propagar 4.000 esquejes de ligustro con enraizante natural de sauce y sistema de riego por goteo automatizado.\",\"Implantación de una parcela testigo con ligustros bajo condiciones óptimas para monitorear la tasa mensual de crecimiento y cerramiento perimetral con malla anti-liebres.\"]},{\"t\":\"Master Plan Paisajístico y Geometría del Laberinto\",\"items\":[\"Plano técnico del laberinto en formato circular concéntrico con senderos de 1,80 a 2,00 m de ancho, caminos ciegos, plazoleta central de descanso y mirador elevado.\",\"Asesoramiento paisajístico (Carolina de INTA) para fijar la densidad exacta de plantación por metro lineal y dimensionar la red de mangueras de goteo autocompensante.\",\"Zonificación del predio: sector laberinto, estacionamiento para 30 vehículos, salón de té/eventos, sendero de faldeo y corrales ecuestres.\"]},{\"t\":\"Prefactibilidad Económica, Fases de Apertura y Servicios Puente\",\"items\":[\"Matriz económica y presupuesto integral por etapas (Fase 1: cerco, vivero y salón de té; Fase 2: plantación y apertura a 1 m de altura; Fase 3: consolidación a 2 m todo el año).\",\"Estructuración de servicios puente inmediatos: casa de té de campo con repostería artesanal de Marta, cabalgatas guiadas de faldeo por Joaquín y visitas educativas al vivero.\",\"Encuesta de validación de demanda (product-market fit) para turistas en Esquel sobre movilidad, interés en atractivos rurales y disposición a pagar.\"]}]", "[\"Master Plan paisajístico y zonificación del predio (escala 1:500) con traza circular y replanteo de senderos.\",\"Informe agronómico de suelo y plan de enmienda orgánica con abono de oveja y tierra negra.\",\"Guía técnica y diseño del módulo de vivero para multiplicación de 4.000 esquejes de ligustro.\",\"Estudio de prefactibilidad económica y presupuesto por etapas a 3 años para búsqueda de financiamiento.\",\"Ficha técnica y operativa de los 'Servicios Puente' (casa de té de campo, cabalgatas y agroturismo).\",\"Informe de validación comercial y resultados de la encuesta de demanda turística en Esquel.\"]", "{\"estado\":\"completada\",\"titulo\":\"Minuta Cero · Entrevista Inicial de Diagnóstico\",\"fecha\":\"20/08/2026\",\"hora\":\"14:00\",\"lugar\":\"Predio El Laberinto, El Hoyo / Esquel\",\"participantes\":[\"Marta Isabel San Martín (Titular)\",\"Mariela (Senior)\",\"Francisco (Junior)\"],\"resumen\":\"Marta San Martín gestiona El Secreto del Laberinto, parque temático de naturaleza y cerco vivo en la Comarca Andina. Es un hito consolidado en la temporada estival de enero y febrero, pero sufre una marcada estacionalidad el resto del año. El objetivo es desestacionalizar la afluencia con experiencias místicas y botánicas en otoño y primavera, y aumentar el gasto promedio por visitante.\",\"diagnostico_claves\":[\"Parque con cerco vivo maduro de gran extensión y ambientación de cuentos y leyendas cordilleranas.\",\"Reconocimiento masivo de marca en turistas que recorren la Ruta 40 entre Esquel y Bariloche.\",\"Infraestructura básica con boletería, senderos y estacionamiento para vehículos.\",\"Fuerte potencial para sumar talleres escolares, fotografía nocturna y confitería de autor.\"],\"trabas_detectadas\":[\"Caída estrepitosa de visitantes de abril a noviembre por condiciones climáticas y cierre comarcal.\",\"Alto costo mensual de riego, poda y mantenimiento del cerco vivo durante todo el año.\",\"Bajo consumo dentro del predio más allá del ticket de ingreso básico.\"],\"acuerdos_previos\":[\"Diseñar el programa \\\"Búsqueda del Tesoro Otoñal\\\" para escuelas de la región y familias locales.\",\"Desarrollar una línea de souvenirs temáticos (duendes, hadas, mapas del laberinto, infusiones herbales).\",\"Articular con prestadores de Esquel para ofrecer promociones cruzadas y entradas combinadas.\",\"Mejorar la cartelería interna con acertijos y relatos interactivos en cada bifurcación.\"],\"citas_textuales\":[\"\\\"El laberinto en verano explota de gente, pero en mayo no entra nadie y el cerco hay que seguir regándolo y cuidándolo igual.\\\"\",\"\\\"Queremos que la gente no solo venga a caminar entre los pinos, sino que se quede a merendar y se lleve un recuerdo mágico a su casa.\\\"\"],\"texto_completo\":\"## Minuta Cero: Encuentro Diagnóstico Inicial · El Secreto del Laberinto\\n\\n**Fecha:** 20 de agosto de 2026 | **Sede:** Predio El Laberinto, El Hoyo / Esquel\\n**Asistentes:** Marta Isabel San Martín (Titular), Mariela (Senior), Francisco (Junior)\\n\\n### 1. Perfil y Oportunidad Detectada\\nParque temático y laberinto vegetal consolidado. Atractivo turístico emblemático de la comarca con alto volumen potencial.\\n\\n### 2. Cuellos de Botella Relevados\\n- **Estacionalidad severa:** Concentración en 60 días de verano y meses fríos con nulo ingreso.\\n- **Gasto por visitante:** Aumentar el consumo complementario de confitería y souvenirs.\\n- **Narrativa interactiva:** Renovar los desafíos dentro del recorrido para estimular la visita repetida.\\n\\n### 3. Compromisos de Arranque\\n1. Propuesta de actividades temáticas de otoño/primavera.\\n2. Catálogo de recuerdos de autor y confitería.\\n3. Convenios de difusión y venta anticipada con hoteles.\"}"],
        ["nire", 23, "Pausa de ñire", "Walter Cerdá", "Raíz", 3.32, 2, "adria", "noelia", "[\"Walter adquirió una fracción de 2 hectáreas de bosque de ñire hace 12 años tras desvincularse de un empleo formal de dos décadas. Construyó un cerco perimetral, abrió un camino de circunvalación interno y edificó una casita/salón cerrada con baño interno (biodigestor), estufa a leña, electricidad y agua.\",\"La propuesta no es trekking atlético ni aventura ni yoga. Se basa en el shinrin-yoku (técnica japonesa de inmersión en la naturaleza y conexión sensorial), enfocada en grupos reducidos (4 a 8 personas) que caminan despacio, se detienen, contemplan, escuchan y respiran el bosque cordillerano.\",\"Su esposa y colegas del CONICET identificaron una sorprendente variedad de microflora: líquenes raros en raíces y cortezas (con morfología de cornetitas o trúfulas), hongos patagónicos y flores nativas. Un recorrido de apenas 50 metros puede extenderse dos horas reloj con alto valor interpretativo y de macrofotografía.\",\"Walter cuenta con carnet profesional habilitante para transporte de personas, movilidad propia (camioneta apta para caminos de tierra) y experiencia como chofer trasladando visitantes a La Zeta. Además, dispone de 100% de dedicación horaria para el proyecto.\",\"Su hijo Imanol (13 años, con síndrome de Down) creció en el predio y desarrolló allí una notable independencia y seguridad. Esta vivencia real abre un diferencial conmovedor y escaso en la comarca: diseñar una experiencia de naturaleza y descanso accesible y sin miedos para familias con niños o personas con discapacidad.\"]", "[\"El predio está emplazado en Altos de Nant y Fall (jurisdicción de Trevelin). Si bien el programa adopta una visión comarcal de macrodestino, se hace imprescindible fijar una 'pata en Esquel' mediante experiencias en Laguna La Zeta para blindar el respaldo institucional ante sensibilidades políticas entre comunas.\",\"Desde la Ruta 17 hasta la tranquera del predio hay 1.500 metros de huella de campo que en invierno y deshielo se vuelve intransitable para autos convencionales sin tracción alta.\",\"El curso de guía con Forest Therapy Hub quedó demorado por cuestiones climáticas. Debe completarse la certificación vía remota mientras se avanza operativamente con lo que ya está en marcha, sin paralizar el negocio.\",\"Para el turista promedio, pagar por 'caminar entre los árboles' puede parecer poco tangible. La propuesta debe justificar su valor a través de un guion estructurado, dinámicas guiadas de silencio, ejercicios sensoriales y un cierre gastronómico/ceremonial con infusión nativa.\"]", "[{\"t\":\"Guion Sensorial y Turismo Inclusivo\",\"items\":[\"Estructurar un recorrido de 2 horas con momentos pautados: apertura y respiración, caminata en silencio ultra-lenta, observación de líquenes y microflora (lupa/macrofotografía), contemplación y cierre con infusión caliente de hojas de ñire.\",\"Formatear una cápsula para familias con integrantes con discapacidad, con actividades sencillas de conexión con el entorno, tiempos flexibles, apoyo a los padres y pautas de seguridad agreste.\",\"Creación de bolsitas de infusión de hojas de ñire con recolección sustentable, etiqueta artesanal con relato del árbol nativo y ficha de preparación para obsequiar o comercializar como recuerdo vivo.\"]},{\"t\":\"Estrategia de Macrodestino y Doble Nodo (La Zeta & Nant y Fall)\",\"items\":[\"Diseñar una variante periurbana en la Reserva Natural Urbana Laguna La Zeta (1h30m) para operar como opción de tarde inmediata en Esquel (días sin esquí o descanso entre excursiones largas).\",\"Operar la chacra como experiencia de medio día (3h a 4h) con traslado propio en camioneta desde el centro de Esquel o punto de encuentro sobre Ruta 17.\",\"Establecer un punto seguro de estacionamiento en la entrada del callejón para transbordar a los visitantes en la camioneta de Walter los días de lluvia o barro.\"]},{\"t\":\"Comercialización, Costeo y Alianzas\",\"items\":[\"Estructurar costos de combustible, seguro de accidentes personales, infusiones y honorarios del guía. Fijar tarifa individual y paquete cerrado para familias.\",\"Armado de la ficha técnica comercial en una carilla para recepcionistas de hoteles boutique de Esquel y agencias de turismo receptivo.\",\"Conexión con los prestadores de la Ruta 259 (Viñas de Nant y Fall, Chacra de Azafrán, Casas de Té) para recomendarse mutuamente en recorridos combinados de día completo.\"]}]", "[\"Guion técnico de la experiencia 'Pausa de Ñire' (Versión Chacra Nant y Fall y Versión periurbana Laguna La Zeta).\",\"Ficha comercial y tarifario cerrado para agencias y hoteles boutique.\",\"Prototipo de souvenir botánico empaquetado (bolsita de hojas de ñire con etiqueta y relato).\",\"Propuesta y protocolo de Turismo Accesible Familiar.\",\"Articulación comercial iniciada con al menos 2 alojamientos de Esquel o prestadores de la Ruta 259.\"]", "{\"estado\":\"completada\",\"titulo\":\"Minuta Cero · Entrevista Inicial de Diagnóstico\",\"fecha\":\"11/09/2026\",\"hora\":\"11:00\",\"lugar\":\"Predio Pausa de Ñire, Esquel\",\"participantes\":[\"Walter Cerdá (Titular)\",\"Leandro (Conducción)\",\"Adria (Senior)\",\"Cesia (Junior)\"],\"resumen\":\"Walter Cerdá desarrolla Pausa de Ñire, espacio de hospitalidad consciente, retiros y bienestar inmerso en un bosque nativo de ñires. Inspirado en modelos europeos de desconexión y baños de bosque (shinrin-yoku). El proyecto busca posicionarse en un segmento premium de descanso y salud mental, requiriendo afinar el mensaje y el público objetivo.\",\"diagnostico_claves\":[\"Propiedad en bosque nativo con una atmósfera de serenidad y privacidad absoluta.\",\"Enfoque holístico de bienestar basado en el silencio, la contemplación y la sustentabilidad.\",\"Titular con formación internacional y claridad conceptual sobre las tendencias de turismo de salud.\",\"Excelente oportunidad para captar ejecutivos y profesionales de grandes ciudades saturados por el ritmo urbano.\"],\"trabas_detectadas\":[\"Riesgo de que lleguen turistas que busquen recreación ruidosa o convencional, quebrando la paz del lugar.\",\"Fijación de tarifas que cubran la exclusividad y el bajo volumen intencional de plazas.\",\"Camino de acceso con tramos de tierra que demandan vehículos adecuados en invierno.\"],\"acuerdos_previos\":[\"Redactar el \\\"Manifiesto de Convivencia y Silencio\\\" para alinear expectativas antes de la reserva.\",\"Diseñar el programa de \\\"Inmersión en el Bosque\\\": fin de semana de desconexión digital guiada.\",\"Estructurar la estrategia de precios premium con servicios personalizados incluidos.\",\"Generar contenido audiovisual sensible enfocado en los beneficios del bosque nativo para la salud.\"],\"citas_textuales\":[\"\\\"En Pausa de Ñire no alquilamos habitaciones; ofrecemos el lujo del silencio y la posibilidad de volver a escuchar la respiración propia.\\\"\",\"\\\"No quiero que venga cualquiera a poner música fuerte; quien elige venir acá sabe que el valor supremo es el respeto por el bosque.\\\"\"],\"texto_completo\":\"## Minuta Cero: Encuentro Diagnóstico Inicial · Pausa de Ñire\\n\\n**Fecha:** 11 de septiembre de 2026 | **Sede:** Predio Pausa de Ñire, Esquel\\n**Asistentes:** Walter Cerdá (Titular), Leandro (Conducción), Adria (Senior), Cesia (Junior)\\n\\n### 1. Perfil y Oportunidad Detectada\\nTurismo de bienestar y retiros conscientes en bosque de ñires. Segmento de nicho de alta valoración y baja masividad.\\n\\n### 2. Cuellos de Botella Relevados\\n- **Filtro de público:** Garantizar que el visitante comparta la filosofía de calma y silencio.\\n- **Estrategia tarifaria:** Cobrar la exclusividad del servicio y la baja densidad de plazas.\\n- **Comunicación:** Transmitir la propuesta con estética refinada y sin caer en clichés de spa tradicional.\\n\\n### 3. Compromisos de Arranque\\n1. Manifiesto y código de estancia del huésped.\\n2. Paquete de retiro de fin de semana con actividades contemplativas.\\n3. Plan de comunicación digital para audiencias de nicho.\"}"],
        ["truepat", 13, "TRUE PATAGONIA", "Cecilia Fernanda Simonini", "Raíz", 3.25, 4, "mariela", "noelia", "[\"Cecilia Fernanda Simonini (radicada en Esquel hace 10 años por elección pura) combina un perfil técnico, artístico y naturalista excepcional: técnica en electrónica, diseñadora gráfica, formación en pastelería, naturalista egresada de Aves Argentinas (trabajo de campo y educación ambiental) y tejedora en telar mapuche, crochet, peine e hilandera en huso tradicional en el Centro Cultural Melipal.\",\"Amplia experiencia en el sector turístico receptivo de Esquel: trayectoria en Las Bayas (hotelería boutique), Frontera Sur (agencia receptiva, rental, esquí y concesiones en Parque Nacional Los Alerces como Cabañas El Chaltén, Camping Lago Verde y Restaurante El Aura), y piezas textiles para Maipú. Reside en el periurbano (detrás de Chacra Los Álamos), en conexión directa con la vida de campo.\",\"Propuesta de valor transformadora y vivencial: 'hacer y experimentar en lugar de solo observar'. Ciclo completo de la lana (oveja, esquila, hilado en huso, recolección botánica de tintes naturales y telar mapuche), alfarería rústica, cosmovisión con nociones de mapuzungun y cocina al rescoldo/horno de barro, complementado con cápsulas de crochet en el paisaje cordillerano.\"]", "[\"Disonancia del nombre provisorio anglosajón ('True Patagonia') frente a una propuesta de raíz ancestral mapuche-tehuelche y criolla profunda, señalada unánimemente por el jurado.\",\"Cuello de botella en la base de alojamiento: pretender concentrar todo en una sola chacra rural con ovejas frena el proyecto por falta de infraestructura hotelera adecuada (calefacción, camas de confort, baños privados) en parajes comarcales.\",\"Sobrecarga operativa al estar sola: necesidad de estructurar el encuadre legal, seguros de turismo activo/asistencia al viajero y comercialización mediante convenios con agencias de viajes receptivas (EVyT) habilitadas.\"]", "[{\"t\":\"Deconstrucción de Marca y Reposicionamiento de Autor\",\"items\":[\"Reemplazo de 'True Patagonia' por una denominación de autor con anclaje comarcal y calidez patagónica.\",\"Construcción de la persona pública de Cecilia como activo irreplicable, anfitriona y puente de confianza con el campo.\"]},{\"t\":\"Modelo 'Punta de Lanza' y Curaduría Emocional\",\"items\":[\"Base de alojamiento en cabañas periurbanas o predios seleccionados (Establecimiento Las Margaritas de Lorena Cogos en Nahuelpan) e incursiones diarias a chacras de Alto Río Percy y parajes.\",\"Diseño del itinerario de 4 días / 3 noches con curva dramática: momentos de calma, silencios, mateadas campesinas y picos de asombro artesanal.\"]},{\"t\":\"Souvenir Físico Conector y Comercialización Receptiva\",\"items\":[\"Diseño y prototipado editorial de la 'Bitácora Textil y Carpeta de Saberes' (fichas botánicas, fórmulas de tinte, glosario mapuzungun y muestras de lana hilada/teñida).\",\"Estructuración de costos B2B/B2C, punto de equilibrio (4 pasajeros), encuadre de turismo activo y convenio marco con agencia receptiva (EVyT) para venta anticipada.\"]}]", "[\"Manual de Marca y Relato de Autor desarticulando el nombre foráneo.\",\"Itinerario Técnico Guionado (4 Días / 3 Noches) y Cápsula Full Day 'Patrones de Montaña & Crochet'.\",\"Prototipo Editorial Impreso de la 'Bitácora Textil y Carpeta de Saberes' con packaging de bienvenida.\",\"Convenio preliminar de uso de espacio con Establecimiento Las Margaritas y predios campesinos de Percy.\",\"Ficha Comercial B2B, matriz de costeo integral con margen de agencia y modelo de seguro de turismo activo.\"]", "{\"estado\":\"completada\",\"titulo\":\"Minuta Cero · Entrevista Inicial de Diagnóstico\",\"fecha\":\"21/08/2026\",\"hora\":\"12:45\",\"lugar\":\"Sede Esquel LAB / Sede True Patagonia\",\"participantes\":[\"Cecilia Fernanda Simonini (Titular)\",\"Leandro (Conducción)\",\"Adria (Senior)\",\"Agustina (Junior)\"],\"resumen\":\"Cecilia Simonini lidera TRUE PATAGONIA, empresa especializada en expediciones lacustres en kayak de travesía, senderismo y avistaje de fauna en el Parque Nacional Los Alerces. Posee un parque de equipamiento de primer nivel y habilitaciones completas. El cuello de botella radica en la venta de último momento en destino y la falta de alianzas estratégicas con hoteles y agencias receptivas.\",\"diagnostico_claves\":[\"Guía profesional habilitada con estándares internacionales de seguridad en aguas frías.\",\"Flota de kayaks de travesía, remos de carbono, chalecos salvavidas y trajes secos en perfecto estado.\",\"Operación en los lagos más cristalinos del Parque Nacional Los Alerces (Menéndez, Futalaufquen, Verde).\",\"Excelente reputación y calificaciones de los pasajeros que completaron las travesías.\"],\"trabas_detectadas\":[\"Logística pesada de transporte de kayaks en trailer con alto consumo de combustible.\",\"Turistas que deciden contratar en el día, complicando la asignación de guías y viandas.\",\"Falta de un sistema de cobro online con pasarela de pago para reservas anticipadas desde el exterior o CABA.\"],\"acuerdos_previos\":[\"Paquetizar 2 salidas estrella: \\\"Remada Turquesa en Lago Verde\\\" (medio día) y \\\"Expedición Glaciar\\\" (día completo).\",\"Implementar pasarela de reservas anticipadas con política de cancelación y contingencia meteorológica.\",\"Firmar acuerdos comerciales con hosterías y hoteles 4 estrellas de Esquel y Trevelin con comisión fijada.\",\"Incluir fotos y tomas con cámara de acción de cortesía como diferencial del servicio.\"],\"citas_textuales\":[\"\\\"Remar un lago de deshielo en silencio entre los cipreses es algo que no se olvida en la vida; la gente se baja del kayak llorando de la emoción.\\\"\",\"\\\"Me paso el día manejando la camioneta y bajando botes; necesito que las reservas entren organizadas por internet y no a las 11 de la noche por WhatsApp.\\\"\"],\"texto_completo\":\"## Minuta Cero: Encuentro Diagnóstico Inicial · TRUE PATAGONIA\\n\\n**Fecha:** 21 de agosto de 2026 | **Sede:** Sede Esquel LAB / Sede True Patagonia\\n**Asistentes:** Cecilia Fernanda Simonini (Titular), Leandro (Conducción), Adria (Senior), Agustina (Junior)\\n\\n### 1. Perfil y Oportunidad Detectada\\nTurismo aventura de aguas y montaña en Parque Nacional Los Alerces. Experiencias de kayak de travesía premium con seguridad certificada.\\n\\n### 2. Cuellos de Botella Relevados\\n- **Anticipación de venta:** Reducir la dependencia de ventas espontáneas de mostrador.\\n- **Logística operativa:** Optimizar viajes y traslados de equipamiento.\\n- **Canal digital:** Venta directa mediante reservas web prepagas.\\n\\n### 3. Compromisos de Arranque\\n1. Fichas de producto de las 2 salidas principales con tarifas y qué incluye.\\n2. Integración de reservas anticipadas digitales.\\n3. Convenios con alojamientos de la zona de influencia.\"}"],
    ];
    $countProy = (int) $pdo->query("SELECT COUNT(*) FROM lab_proyectos")->fetchColumn();
    if ($countProy === 0) {
        $insProy = $pdo->prepare("INSERT INTO lab_proyectos (id, application_id, nombre, titular, linea, puntaje, celula, consultor_sr_id, consultor_jr_id, diagnostico, trabas, ejes, entregables, minuta_cero) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)");
        $checkApp = $pdo->prepare("SELECT 1 FROM applications WHERE id = ?");
        foreach ($proyectos as $p) {
            $checkApp->execute([(int)$p[1]]);
            if (!$checkApp->fetchColumn()) { $p[1] = null; }
            $insProy->execute($p);
        }
    }

    // 3. Sincronización continua de proyectos
    $updProy = $pdo->prepare("UPDATE lab_proyectos SET titular = ?, diagnostico = ?, trabas = ?, ejes = ?, entregables = ?, minuta_cero = ? WHERE id = ?");
    foreach ($proyectos as $p) {
        $updProy->execute([$p[3], $p[9], $p[10], $p[11], $p[12], $p[13], $p[0]]);
    }

    // 4. Reuniones oficiales (4 Fuertes + 3-4 Toques Base + 1 Cierre Plenario)
    $reunionesOficiales = [
        ["crova-01", "crova", 1, "Diagnóstico en terreno y relevamiento de taller", "ind", "Taller", "2026-09-16", "08:30", "10:30", "programada", "Relevar el espacio físico de trabajo, la maquinaria existente y el estado del camino de acceso. Identificar dónde se puede ubicar un rincón de showroom sin entorpecer la producción.", "[\"¿Cuántas horas reales de producción te quita recibir una visita de 45 minutos?\",\"¿Qué piezas tenés terminadas listas para exhibición hoy?\",\"¿Qué reclamos o dificultades te manifestaron los clientes que ya vinieron por el camino?\"]", "[\"Relevar medidas y layout del taller para el sector de visita.\",\"Evaluar el estado del camino y puntos críticos de acceso.\",\"Establecer los días y horarios intocables de producción.\"]", "[{\"id\":1,\"texto\":\"Fotografiar el estado del camino y puntos de acceso\",\"done\":false},{\"id\":2,\"texto\":\"Medir el espacio disponible para showroom\",\"done\":false},{\"id\":3,\"texto\":\"Inventariar maquinaria y ubicar puntos de riesgo por polvo\",\"done\":false},{\"id\":4,\"texto\":\"Definir días de visita (descartar lunes y miércoles mañana)\",\"done\":false}]", ["leandro","cesia"]],
        ["crova-02", "crova", 2, "Eje comunicación y contenidos", "ind", "Turismo", "2026-09-22", "14:30", "16:00", "programada", "Analizar el material existente de video y redes. Definir una línea editorial que conecte la artesanía del pipero con el misticismo patagónico.", "[\"¿Quién te ayuda hoy a filmar y editar?\",\"¿Qué repercusión tienen los videos en YouTube y de dónde te escriben?\"]", "[\"Inventariar el material audiovisual propio.\",\"Definir la línea editorial y el tono de la marca.\"]", "[{\"id\":1,\"texto\":\"Revisar el canal de YouTube\",\"done\":false},{\"id\":2,\"texto\":\"Inventariar el material audiovisual propio\",\"done\":false},{\"id\":3,\"texto\":\"Definir línea editorial\",\"done\":false},{\"id\":4,\"texto\":\"Acordar frecuencia de publicación\",\"done\":false}]", ["cesia"]],
        ["crova-03", "crova", 3, "Guion de visita y cuantificación de tiempos", "ind", "Taller", "2026-09-24", "14:30", "16:00", "programada", "Segmentar la experiencia entre cofrades/coleccionistas y turistas familiares. Calcular el costo de oportunidad del artesano.", "[\"¿Qué espera ver un coleccionista experto vs una familia turista?\",\"¿Cuánto vale tu hora de trabajo de torno y lijado?\"]", "[\"Estructurar dos versiones del guion de visita.\",\"Fijar el valor de cesión de tiempo de producción.\"]", "[{\"id\":1,\"texto\":\"Cronometrar una visita tipo\",\"done\":false},{\"id\":2,\"texto\":\"Redactar el guion para cofrades\",\"done\":false},{\"id\":3,\"texto\":\"Redactar el guion para turistas y familias\",\"done\":false},{\"id\":4,\"texto\":\"Calcular las horas de producción que cede por visita\",\"done\":false}]", ["cesia"]],
        ["crova-04", "crova", 4, "Costeo, escasez y consignación (Célula 1)", "ind", "Célula 1 (Turismo)", "2026-09-29", "14:00", "15:30", "programada", "Encuentro grupal de la Célula 1 (Oficio y pieza). Poner en común criterios de fijación de precios, esquemas de escasez y condiciones de consignación.", "[\"¿Cómo trasladamos el costo hora-hombre al precio de la experiencia?\",\"¿Qué comisión es justa dejarle al intermediario o comercio?\"]", "[\"Comparar matrices de costeo entre proyectos de oficio.\",\"Definir tope mensual de visitas.\"]", "[{\"id\":1,\"texto\":\"Llevar la planilla de costeo completa\",\"done\":false},{\"id\":2,\"texto\":\"Comparar con Carpintero, Vico+Tita y Patagonia Retro\",\"done\":false},{\"id\":3,\"texto\":\"Definir tope de visitas mensuales\",\"done\":false}]", ["leandro","cesia"]],
        ["crova-05", "crova", 5, "Producción audiovisual en taller", "ind", "Taller", "2026-10-08", "14:00", "15:30", "programada", "Sesión de rodaje profesional con equipo audiovisual y dron de la Subsecretaría para generar el banco de contenidos oficial.", "[\"¿Qué fases del proceso de torneado son las más fotogénicas y llamativas?\"]", "[\"Grabar tomas 4K de detalle y tomas aéreas del entorno.\",\"Generar clips para reels y web.\"]", "[{\"id\":1,\"texto\":\"Agendar equipo 4K y dron\",\"done\":false},{\"id\":2,\"texto\":\"Armar el guion de tomas previas\",\"done\":false},{\"id\":3,\"texto\":\"Firmar autorización de uso de imagen\",\"done\":false},{\"id\":4,\"texto\":\"Hacer backup del material el mismo día\",\"done\":false}]", ["leandro","cesia"]],
        ["crova-06", "crova", 6, "Precio de visita y esquema de escasez cerrado", "ind", "Taller", "2026-10-15", "14:30", "16:00", "programada", "Fijar el precio final de la visita y los días estrictos de atención.", "[\"¿Confirmamos el precio en pesos y en dólares para extranjeros?\",\"¿Cómo se cobrará la reserva anticipada?\"]", "[\"Cerrar política de tarifas y cupos.\"]", "[{\"id\":1,\"texto\":\"Fijar el precio de la visita guiada\",\"done\":false},{\"id\":2,\"texto\":\"Definir cupo máximo por turno\",\"done\":false},{\"id\":3,\"texto\":\"Confirmar calendario de días habilitados\",\"done\":false}]", ["cesia"]],
        ["crova-07", "crova", 7, "Ficha comercial y canales receptivos", "ind", "Turismo", "2026-10-22", "14:30", "16:00", "programada", "Redactar la ficha comercial para agencias receptivas premium y cofradías de fumadores internacionales.", "[\"¿Qué porcentaje de comisión aceptamos para agencias de viaje?\"]", "[\"Tener la ficha técnica lista para distribución.\"]", "[{\"id\":1,\"texto\":\"Redactar la ficha para receptivos\",\"done\":false},{\"id\":2,\"texto\":\"Redactar la ficha para cofradía internacional\",\"done\":false},{\"id\":3,\"texto\":\"Definir política de cancelación\",\"done\":false}]", ["cesia"]],
        ["crova-08", "crova", 8, "Ficha técnica y tarifario final", "ind", "Taller", "2026-10-29", "14:00", "15:30", "programada", "Revisión final de tarifas, acuerdos y piezas gráficas terminadas.", "[\"¿Está todo listo para la rueda de negocios del cierre?\"]", "[\"Cerrar carpetas comerciales.\"]", "[{\"id\":1,\"texto\":\"Cerrar la ficha técnica definitiva\",\"done\":false},{\"id\":2,\"texto\":\"Cerrar tarifario con comisiones\",\"done\":false},{\"id\":3,\"texto\":\"Revisar material audiovisual editado\",\"done\":false}]", ["leandro","cesia"]],
        ["crova-09", "crova", 9, "Distinción, resultados y rueda de negocios en Melipal", "cie", "Centro Cultural Melipal", "2026-11-19", "10:00", "13:00", "programada", "Acto plenario final de la 1ª cohorte de Esquel LAB. Entrega de certificados, exposición de resultados y vinculación comercial.", "[\"¿Cuál es el próximo paso de tu proyecto para 2027?\"]", "[\"Cerrar al menos un acuerdo comercial formal.\"]", "[{\"id\":1,\"texto\":\"Confirmar asistencia\",\"done\":false},{\"id\":2,\"texto\":\"Llevar material de exhibición\",\"done\":false},{\"id\":3,\"texto\":\"Cerrar al menos una reunión con una empresa local\",\"done\":false}]", ["leandro","adria","mariela","francisco","agustina","cesia","noelia"]],
        ["haiku-01", "haiku", 1, "Definir qué es Haiku: identidad y prioridades", "ind", "Local", "2026-09-17", "09:30", "11:30", "programada", "Abordar la disyuntiva entre alta gastronomía y espacio de encuentro comunitario. Enfoque de sostén emocional y claridad estratégica.", "[\"¿Qué es lo innegociable de Haiku que no querés perder?\",\"¿Dónde sentís que se te va la energía en el día a día?\"]", "[\"Escribir la definición medular de Haiku.\",\"Listar qué aspectos de la operación se simplifican.\"]", "[{\"id\":1,\"texto\":\"Escribir en una frase qué es Haiku\",\"done\":false},{\"id\":2,\"texto\":\"Listar lo que no se toca\",\"done\":false},{\"id\":3,\"texto\":\"Listar lo que sí se puede ceder o simplificar\",\"done\":false}]", ["mariela","agustina"]],
        ["haiku-02", "haiku", 2, "Cápsulas de experiencia y recurrencia", "ind", "Local", "2026-10-01", "09:30", "11:30", "programada", "Estructurar productos empaquetados con precio propio (Té de amigas, Haiku al atardecer los viernes, propuesta de sábados).", "[\"¿Cuánto cuesta hoy una merienda completa y qué margen real te deja?\",\"¿Qué día de la semana tenés el salón más vacío?\"]", "[\"Nombrar y costear 3 cápsulas semanales.\"]", "[{\"id\":1,\"texto\":\"Nombrar cada cápsula\",\"done\":false},{\"id\":2,\"texto\":\"Fijar precio propio de cada una\",\"done\":false},{\"id\":3,\"texto\":\"Definir día y horario fijo\",\"done\":false},{\"id\":4,\"texto\":\"Definir cupo mínimo y máximo\",\"done\":false}]", ["agustina"]],
        ["haiku-03", "haiku", 3, "Conservación en frío y cálculo de mermas", "ind", "Local", "2026-10-08", "09:30", "11:30", "programada", "Resolver el cuello de botella de productos con crema que vencen a los 2 días. Diseñar línea de pastelería congelable de alta calidad.", "[\"¿Cuánta pastelería descartás por semana?\",\"¿Qué masas y bases admiten congelado sin alterar textura?\"]", "[\"Reducir el desperdicio en un 50% mediante planificación de horneado.\"]", "[{\"id\":1,\"texto\":\"Medir la merma de una semana completa\",\"done\":false},{\"id\":2,\"texto\":\"Identificar qué productos admiten congelado\",\"done\":false},{\"id\":3,\"texto\":\"Costear la conservación en frío\",\"done\":false}]", ["mariela","agustina"]],
        ["haiku-04", "haiku", 4, "Identidad visual y señalética de vereda", "ind", "Local", "2026-10-15", "09:30", "11:30", "programada", "Cambiar la percepción externa de que el local está cerrado. Jerarquía visual: mensaje grande primero, marca después.", "[\"¿Qué ve alguien que pasa caminando por la vereda?\",\"¿Dice claramente los horarios y que se puede entrar sin reserva?\"]", "[\"Rediseñar pizarrón de vereda y señalética de puerta.\"]", "[{\"id\":1,\"texto\":\"Rediseñar tres piezas con el mensaje primero\",\"done\":false},{\"id\":2,\"texto\":\"Definir una plantilla reutilizable\",\"done\":false},{\"id\":3,\"texto\":\"Revisar qué comunica la vidriera desde la vereda\",\"done\":false}]", ["agustina"]],
        ["haiku-05", "haiku", 5, "Sistema de registro diario de ventas y clientes", "ind", "Local", "2026-10-22", "09:30", "11:30", "programada", "Implementar una planilla simple de 4 columnas para reemplazar la memoria por datos reales.", "[\"¿Cuántos clientes regulares vinieron esta semana?\",\"¿Cuál fue el ticket promedio?\"]", "[\"Tener el primer registro diario sistematizado.\"]", "[{\"id\":1,\"texto\":\"Armar la planilla diaria\",\"done\":false},{\"id\":2,\"texto\":\"Definir quién la carga y a qué hora\",\"done\":false},{\"id\":3,\"texto\":\"Cargar la primera semana completa\",\"done\":false}]", ["mariela","agustina"]],
        ["haiku-06", "haiku", 6, "Lectura de datos y ajuste operativo", "ind", "Local", "2026-10-29", "09:30", "11:30", "programada", "Tomar decisiones basadas en los datos registrados de ventas.", "[\"¿Qué productos tienen mayor margen y rotación?\"]", "[\"Consolidar el menú mensual fijo.\"]", "[{\"id\":1,\"texto\":\"Graficar las tres semanas cargadas\",\"done\":false},{\"id\":2,\"texto\":\"Decidir qué cápsula se discontinúa\",\"done\":false},{\"id\":3,\"texto\":\"Ajustar precios si hace falta\",\"done\":false}]", ["agustina"]],
        ["haiku-07", "haiku", 7, "Cierre de ejes y red con alojamientos", "ind", "Local", "2026-11-05", "09:30", "11:30", "programada", "Conectar Haiku con hoteles boutique y cabañas para derivación de desayunos y meriendas.", "[\"¿Qué alojamientos te quedan cerca para coordinar un voucher exclusivo?\"]", "[\"Listar 5 alojamientos clave y armar propuesta.\"]", "[{\"id\":1,\"texto\":\"Listar alojamientos a contactar\",\"done\":false},{\"id\":2,\"texto\":\"Preparar la presentación de 5 minutos\",\"done\":false}]", ["mariela","agustina"]],
        ["haiku-08", "haiku", 8, "Distinción, resultados y rueda de negocios en Melipal", "cie", "Centro Cultural Melipal", "2026-11-19", "10:00", "13:00", "programada", "Acto plenario y cierre del programa con el sector turístico de Esquel.", "[\"¿Cuál es la proyección de Haiku para este verano?\"]", "[\"Cerrar acuerdos con prestadores y alojamientos.\"]", "[{\"id\":1,\"texto\":\"Confirmar asistencia\",\"done\":false},{\"id\":2,\"texto\":\"Llevar muestras de pastelería\",\"done\":false},{\"id\":3,\"texto\":\"Cerrar al menos una reunión con un alojamiento\",\"done\":false}]", ["leandro","adria","mariela","francisco","agustina","cesia","noelia"]],
        ["tambo-01", "tambo", 1, "Brainstorming y relevamiento en terreno", "ter", "Predio (Trevelin)", "2026-09-24", "09:30", "12:00", "programada", "Recorrer las 2 hectáreas, evaluar el estado de la construcción colonial histórica y definir la ubicación de la pista de equitación.", "[\"¿Qué servicios básicos (agua, luz) están disponibles hoy en la zona de la pista?\",\"¿Qué inversión mínima se requiere para tener la pista operativa?\"]", "[\"Relevar el predio y fotografiar el edificio histórico.\",\"Delimitar el área ecuestre inicial.\"]", "[{\"id\":1,\"texto\":\"Recorrer las 2 ha completas\",\"done\":false},{\"id\":2,\"texto\":\"Fotografiar la construcción histórica y el sótano\",\"done\":false},{\"id\":3,\"texto\":\"Marcar la ubicación de la pista\",\"done\":false},{\"id\":4,\"texto\":\"Listar los servicios que faltan\",\"done\":false}]", ["adria","noelia"]],
        ["tambo-02", "tambo", 2, "Priorización de actividades: foco ecuestre", "ind", "Turismo", "2026-10-01", "14:30", "16:30", "programada", "Frenar la dispersión (aromáticas, gallinas, ordeñe) y concentrarse 100% en la equitación como fuente de ingresos inmediata.", "[\"¿Qué actividad te genera flujo de fondos más rápido sin gran inversión?\"]", "[\"Ordenar las ideas en una sola lista priorizada.\"]", "[{\"id\":1,\"texto\":\"Ordenar las ideas en una sola lista priorizada\",\"done\":false},{\"id\":2,\"texto\":\"Definir qué arranca ahora y qué queda para la temporada siguiente\",\"done\":false}]", ["noelia"]],
        ["tambo-03", "tambo", 3, "Esquema económico-financiero para inversor", "ind", "Turismo", "2026-10-15", "09:30", "12:00", "programada", "Armar una planilla simple de ingresos, costos fijos y variables para presentarle a su padre a su regreso de Buenos Aires.", "[\"¿Qué monto de inversión inicial se le va a pedir al padre y en cuántos meses se amortiza?\"]", "[\"Tener la matriz económica lista para presentar.\"]", "[{\"id\":1,\"texto\":\"Completar la matriz simplificada\",\"done\":false},{\"id\":2,\"texto\":\"Dejarla en formato presentable para el padre\",\"done\":false},{\"id\":3,\"texto\":\"Definir la inversión mínima para arrancar\",\"done\":false}]", ["adria","noelia"]],
        ["tambo-04", "tambo", 4, "Paquetización de la experiencia ecuestre", "ind", "Turismo", "2026-10-20", "14:00", "16:00", "programada", "Diseñar la experiencia con guion, curva emocional y protocolo de seguridad para turistas.", "[\"¿Qué duración debe tener la clase/paseo y qué nivel de destreza requiere?\"]", "[\"Escribir el guion de la actividad ecuestre.\"]", "[{\"id\":1,\"texto\":\"Escribir el guion de la experiencia\",\"done\":false},{\"id\":2,\"texto\":\"Definir duración y cupo\",\"done\":false},{\"id\":3,\"texto\":\"Fijar el precio\",\"done\":false}]", ["noelia"]],
        ["tambo-05", "tambo", 5, "Comunicación y narrativa de macro destino", "ind", "Turismo", "2026-10-29", "09:30", "12:00", "programada", "Aprovechar sus habilidades de marketing digital e integrar la narrativa de Esquel aunque el predio esté en Trevelin.", "[\"¿Cómo conectamos la visita al Tambo con el circuito de tulipanes y los atractivos de Esquel?\"]", "[\"Definir el plan de contenido y portfolio.\"]", "[{\"id\":1,\"texto\":\"Revisar el portfolio de contenidos\",\"done\":false},{\"id\":2,\"texto\":\"Escribir el párrafo de presentación con el encuadre de macro destino\",\"done\":false},{\"id\":3,\"texto\":\"Definir el plan de contenido\",\"done\":false}]", ["adria","noelia"]],
        ["tambo-06", "tambo", 6, "Habilitaciones municipales y agrimensura", "ind", "Turismo", "2026-11-05", "14:00", "16:00", "programada", "Seguimiento de trámites municipales, seguros de equitación y deslindes de agrimensura.", "[\"¿Qué requisitos exige la municipalidad de Trevelin para actividad ecuestre comercial?\"]", "[\"Iniciar expediente de habilitación.\"]", "[{\"id\":1,\"texto\":\"Listar los permisos necesarios\",\"done\":false},{\"id\":2,\"texto\":\"Iniciar el trámite municipal\",\"done\":false},{\"id\":3,\"texto\":\"Pedir presupuesto de agrimensor\",\"done\":false}]", ["noelia"]],
        ["tambo-07", "tambo", 7, "Ficha comercial para receptivos", "ind", "Turismo", "2026-11-12", "09:30", "12:00", "programada", "Armado de la ficha de comercialización para agencias de Esquel y Trevelin.", "[\"¿A qué agencias receptivas les presentaremos el producto en la rueda?\"]", "[\"Cerrar ficha comercial con comisiones.\"]", "[{\"id\":1,\"texto\":\"Cerrar la ficha comercial\",\"done\":false},{\"id\":2,\"texto\":\"Listar receptivos objetivo\",\"done\":false},{\"id\":3,\"texto\":\"Preparar la presentación de 5 minutos\",\"done\":false}]", ["adria","noelia"]],
        ["tambo-08", "tambo", 8, "Distinción, resultados y rueda de negocios en Melipal", "cie", "Centro Cultural Melipal", "2026-11-19", "10:00", "13:00", "programada", "Cierre plenario y rueda comercial.", "[\"¿Cuándo inician las primeras clases en la pista?\"]", "[\"Cerrar acuerdos con agencias y hoteles.\"]", "[{\"id\":1,\"texto\":\"Confirmar asistencia\",\"done\":false},{\"id\":2,\"texto\":\"Llevar fotos del predio\",\"done\":false},{\"id\":3,\"texto\":\"Cerrar al menos una reunión con un receptivo\",\"done\":false}]", ["leandro","adria","mariela","francisco","agustina","cesia","noelia"]],
        ["flypark-01", "flypark", 1, "Relevamiento de terreno en Sociedad Rural y planificación de montaje", "ter", "Predio de la Sociedad Rural de Esquel", "2026-09-16", "14:00", "16:30", "programada", "Visitar el predio de la Sociedad Rural junto a Fabricio y Paula Botto. Inspeccionar el declive natural del terreno con pasto, evaluar las dimensiones para el trazado de la pista modular de 100 m² (1 tira continua con desnivel) y verificar acometida eléctrica, baños y seguridad perimetral. Coordinar la solicitud formal de préstamo temporal por 3 semanas.", "[\"¿Qué dimensiones exactas y pendiente requiere la bajada para asegurar un deslizamiento fluido sin riesgo de frenado brusco?\",\"¿Cuándo arriba el flete desde Buenos Aires con los 70 m² de alfombra Powplast adquiridos con el Plan Galina?\",\"¿Qué personal y herramientas necesitamos para montar la pista en una sola jornada sin impactar el suelo?\"]", "[\"Delimitar la traza exacta de la pista de dryslope en el desnivel del predio rural.\",\"Definir el cronograma de armado y recepción de materiales del Plan Galina.\",\"Gestionar la nota formal de autorización de uso temporal ante la Comisión Directiva de la Rural.\"]", "[{\"id\":1,\"texto\":\"Medir la pendiente y distancia útil en el césped de la Sociedad Rural\",\"done\":false},{\"id\":2,\"texto\":\"Confirmar la llegada del cargamento de 70 m² de alfombra Powplast\",\"done\":false},{\"id\":3,\"texto\":\"Presentar nota oficial firmada por la Secretaría de Producción y el LAB\",\"done\":false}]", ["leandro","agustina"]],
        ["flypark-02", "flypark", 2, "Montaje de pista modular de dryslope, cajones y medidas de seguridad", "ter", "Predio de la Sociedad Rural de Esquel", "2026-09-23", "14:30", "16:30", "programada", "Jornada de ensamblado de los 100 m² de alfombra sintética Powplast entre el equipo de Flypark y colaboradores. Instalación modular por encastre tipo ladrillo sobre el pasto, fijación de anclajes no invasivos, colocación de rampita de inicio, cajón de deslizamiento y tubos de PVC para freestyle. Demarcación de la zona de frenado y colchón de seguridad.", "[\"¿Cómo responde el encastre de las placas plásticas a las ondulaciones del terreno?\",\"¿Qué lubricación superficial con agua o silicona neutra requiere la alfombra para optimizar el deslizamiento?\",\"¿Qué delimitación visual con banderines y redes de contención colocamos en los laterales?\"]", "[\"Dejar la pista de 100 m² completamente armada y operativa en el predio rural.\",\"Testear el deslizamiento con tablas y esquís por parte de riders experimentados.\",\"Verificar que la estructura no altere ni dañe el césped natural.\"]", "[{\"id\":1,\"texto\":\"Ensamblar la totalidad de las placas Powplast (100 m² cubiertos)\",\"done\":false},{\"id\":2,\"texto\":\"Montar 1 cajón y 1 riel de PVC para maniobras de freestyle\",\"done\":false},{\"id\":3,\"texto\":\"Realizar pruebas de deslizamiento y calibrar la zona de detención final\",\"done\":false}]", ["agustina"]],
        ["flypark-03", "flypark", 3, "Evento Demo Oficial, registro para Chubut Deportes y respaldo político", "ter", "Sociedad Rural de Esquel", "2026-10-07", "14:00", "16:30", "programada", "Presentación oficial y Demo de Flypark en La Rural antes del deadline del Plan Galina (7 de octubre). Convocatoria de autoridades provinciales y municipales (Intendente Taccetta, Chubut Deportes, Producción, Turismo), prensa comarcal, Club Andino y jóvenes riders. Demostración en vivo de freestyle e iniciación, fotografía y video oficial con la cartelería del Plan Galina para la rendición definitiva.", "[\"¿Cómo comunicamos el logro histórico de tener esquí urbano todo el año en Esquel ante los medios?\",\"¿Qué tomas y comprobantes exige el formulario de rendición del Plan Galina para cerrar el expediente?\",\"¿Qué devoluciones y compromisos expresaron las autoridades presentes para la radicación definitiva?\"]", "[\"Cerrar la rendición física y audiovisual del Plan Galina ante Chubut Deportes.\",\"Generar un alto impacto mediático y comunitario positivo que blinde el proyecto ante trabas burocráticas.\",\"Demostrar la factibilidad técnica y el atractivo del dryslope urbano en Esquel.\"]", "[{\"id\":1,\"texto\":\"Ejecutar la exhibición en vivo con riders y autoridades presentes\",\"done\":false},{\"id\":2,\"texto\":\"Registrar el set fotográfico con la cartelería oficial del Plan Galina\",\"done\":false},{\"id\":3,\"texto\":\"Presentar la carpeta de rendición completa ante Chubut Deportes\",\"done\":false}]", ["leandro","agustina"]],
        ["flypark-04", "flypark", 4, "Estructura legal mixta: Convenio Asociación Civil - Flypark y radicación", "ind", "LAB Esquel / Secretaría de Turismo", "2026-10-16", "14:00", "16:00", "programada", "Abordar la arquitectura legal del proyecto. Redactar el Convenio Marco de Articulación y Comodato entre la Asociación Civil Patagonia Freeride (titular de la pista financiada) y la firma comercial FLYPARK (operadora privada). Establecer con claridad la contraprestación social (cupos gratuitos para escuelas públicas y entrenamientos de clubes) y avanzar en las negociaciones del terreno definitivo de 1 hectárea.", "[\"¿Cómo garantizamos la transparencia jurídica entre la asociación sin fines de lucro y la empresa comercial?\",\"¿Qué avances hubo con el propietario del terreno de Darwin y Humpreys para el comodato con opción a alquiler?\",\"¿Qué opciones de predios municipales o comodatos alternativos existen si se traba el terreno privado?\"]", "[\"Redactar el borrador del convenio Asociación Civil - Flypark visado legalmente.\",\"Definir el esquema de becas e iniciación escolar comunitaria (esquí social).\",\"Elaborar la estrategia de negociación para el predio definitivo permanente.\"]", "[{\"id\":1,\"texto\":\"Borrador del convenio de comodato y articulación institucional cerrado\",\"done\":false},{\"id\":2,\"texto\":\"Fijar la cuota de horas semanales reservadas para clubes y escuelas públicas\",\"done\":false},{\"id\":3,\"texto\":\"Matriz comparativa de opciones de radicación territorial definitiva\",\"done\":false}]", ["agustina"]],
        ["flypark-05", "flypark", 5, "Marco normativo municipal y protocolo de habilitación de dryslope", "ter", "LAB Esquel", "2026-10-23", "14:00", "16:30", "programada", "Trabajar junto al equipo técnico del municipio en la formulación del anteproyecto de ordenanza marco para Parques y Pistas Urbanas de Deportes de Nieve Sintética (Dryslope). Redactar el protocolo operativo de bioseguridad: uso obligatorio de casco, protecciones corporales, seguro de accidentes personales / turismo activo y deslinde de responsabilidad.", "[\"¿Bajo qué rubro municipal se encuadra hoy una actividad deportiva inédita en Chubut?\",\"¿Qué exigencias de salida de emergencia, matafuegos y botiquín de primeros auxilios se deben prever? \",\"¿Qué aseguradoras operan pólizas de responsabilidad civil para deportes de acción en seco?\"]", "[\"Redactar el anteproyecto de ordenanza municipal para elevar al Concejo Deliberante.\",\"Consensuar los requisitos técnicos con el área de Habilitaciones Comerciales e Inspecciones.\",\"Cotizar y seleccionar la póliza de seguro de turismo activo para usuarios.\"]", "[{\"id\":1,\"texto\":\"Presentar anteproyecto de ordenanza de dryslope en el Concejo Deliberante\",\"done\":false},{\"id\":2,\"texto\":\"Redactar el manual operativo de seguridad y deslinde de responsabilidad civil\",\"done\":false},{\"id\":3,\"texto\":\"Obtener cotizaciones de póliza de seguro de cobertura deportiva integral\",\"done\":false}]", ["leandro","agustina"]],
        ["flypark-06", "flypark", 6, "Planilla paramétrica de costos, tarifario B2C/B2B y merchandising", "ind", "LAB Esquel", "2026-11-04", "14:30", "16:30", "programada", "Estructurar la economía del emprendimiento. Definir costos fijos y variables (amortización de alfombra, alquiler, instructores, seguro, mantenimiento). Fijar el tarifario: pases por turno (45 y 90 min), abonos mensuales para residentes, pases familiares y tarifas para agencias de viajes (EVyT) y hoteles. Integrar la línea de indumentaria oficial de la marca FLYPARK (remeras, buzos, gorritos, buffs).", "[\"¿Cuál es el precio de mercado de un pase de iniciación al esquí frente al costo de subir a La Hoya?\",\"¿Qué margen de comisión del 20-25% se ofrecerá a las agencias receptivas locales?\",\"¿Cuál es el margen y stock inicial de la línea de merchandising de autor FLYPARK?\"]", "[\"Construir la planilla paramétrica de costos y punto de equilibrio operativo.\",\"Emitir la lista de precios oficial para residentes, turistas y agencias receptivas.\",\"Diseñar el packaging y fijar precios para la línea textil de FLYPARK.\"]", "[{\"id\":1,\"texto\":\"Cargar la planilla de costos unitarios y punto de equilibrio financiero\",\"done\":false},{\"id\":2,\"texto\":\"Emitir el tarifario comercial B2C y B2B para la temporada 2026/2027\",\"done\":false},{\"id\":3,\"texto\":\"Catálogo de precios de indumentaria propia (remeras, buzos, gorras y buffs)\",\"done\":false}]", ["agustina"]],
        ["flypark-07", "flypark", 7, "Plataforma digital, canal de reservas y alianzas con agencias y clubes", "ind", "LAB Esquel / Espacio Digital", "2026-11-11", "14:00", "16:30", "programada", "Diseño y lanzamiento de la landing page de FLYPARK en esquel.site con sistema de reservas por turnos y cobro anticipado por Mercado Pago. Firma de convenios marco de colaboración con clubes locales (Club Andino Esquel, Slalom Club, Esquel Ski Club) para pretemporada y entrenamientos continuos. Articulación de paquetes turísticos con agencias receptivas de Esquel.", "[\"¿Qué horarios se reservan para entrenamientos federados y cuáles para turistas y principiantes?\",\"¿Cómo se gestiona el sistema de alquiler (rental) de tablas y botas en el predio?\",\"¿Qué convenios de co-branding podemos acordar con marcas de outdoor y sponsors?\"]", "[\"Publicar la landing page oficial con video institucional y motor de reservas.\",\"Firmar cartas de intención con al menos 2 clubes de montaña de Esquel.\",\"Cerrar convenios de distribución comercial con al menos 2 agencias receptivas.\"]", "[{\"id\":1,\"texto\":\"Landing page operativa con botón de reserva y pasarela digital\",\"done\":false},{\"id\":2,\"texto\":\"Firmar actas de acuerdo con clubes deportivos locales\",\"done\":false},{\"id\":3,\"texto\":\"Distribuir material promocional en alojamientos y centros de información\",\"done\":false}]", ["leandro","agustina"]],
        ["flypark-08", "flypark", 8, "Ronda de Negocios Final, Lanzamiento Oficial y Hoja de Ruta Post-LAB", "ind", "Centro Cultural Melipal / Espacio LAB", "2026-11-16", "14:00", "16:00", "programada", "Participación protagónica de FLYPARK en el Encuentro de Cierre de Esquel LAB como proyecto #1 de Acelera. Montaje de stand temático con placas de alfombra Powplast, esquís de freestyle, indumentaria oficial y proyección audiovisual de la demo en La Rural. Pitch de 3 minutos de Fabricio Guglielmetti. Anuncio de la radicación definitiva y entrega del plan operativo post-incubación.", "[\"¿Qué balance arroja el proceso tras haber superado la urgencia del Plan Galina?\",\"¿Cuál es el cronograma de radicación definitiva para la temporada de verano 2026/2027?\",\"¿Qué articulación se proyecta con el Ministerio de Turismo y Deportes provincial?\"]", "[\"Presentar oficialmente a FLYPARK como el primer parque urbano de esquí y snowboard de la provincia.\",\"Consolidar compromisos comerciales con operadores turísticos y sponsors privados.\",\"Entregar el informe de cierre de asistencia técnica y plan de expansión a 3 años.\"]", "[{\"id\":1,\"texto\":\"Montar stand interactivo de freestyle con equipamiento e indumentaria\",\"done\":false},{\"id\":2,\"texto\":\"Exponer el pitch de 3 minutos ante autoridades, prensa y sector privado\",\"done\":false},{\"id\":3,\"texto\":\"Firmar acuerdos comerciales y presentar la hoja de ruta definitiva\",\"done\":false}]", ["agustina"]],
        ["flypark-09", "flypark", 9, "Distinción, resultados y rueda de negocios en Melipal", "cie", "Centro Cultural Melipal", "2026-11-19", "10:00", "13:00", "programada", "Participación protagónica de FLYPARK en el Encuentro de Cierre de Esquel LAB como proyecto #1 de Acelera. Montaje de stand temático con placas de alfombra Powplast, esquís de freestyle, indumentaria oficial y proyección audiovisual de la demo en La Rural. Pitch de 3 minutos de Fabricio Guglielmetti. Anuncio de la radicación definitiva y entrega del plan operativo post-incubación.", "[\"¿Qué balance arroja el proceso tras haber superado la urgencia del Plan Galina?\",\"¿Cuál es el cronograma de radicación definitiva para la temporada de verano 2026/2027?\",\"¿Qué articulación se proyecta con el Ministerio de Turismo y Deportes provincial?\"]", "[\"Presentar oficialmente a FLYPARK como el primer parque urbano de esquí y snowboard de la provincia.\",\"Consolidar compromisos comerciales con operadores turísticos y sponsors privados.\",\"Entregar el informe de cierre de asistencia técnica y plan de expansión a 3 años.\"]", "[{\"id\":1,\"texto\":\"Montar stand interactivo de freestyle con equipamiento e indumentaria\",\"done\":false},{\"id\":2,\"texto\":\"Exponer el pitch de 3 minutos ante autoridades, prensa y sector privado\",\"done\":false},{\"id\":3,\"texto\":\"Firmar acuerdos comerciales y presentar la hoja de ruta definitiva\",\"done\":false}]", ["leandro","adria","mariela","francisco","agustina","cesia","noelia"]],
        ["porota-01", "porota", 1, "Diagnóstico en Don Bosco 920, relevamiento de las 7.552 piezas y espacio físico", "ter", "Casa de Porota (Don Bosco 920)", "2026-09-22", "10:00", "12:30", "programada", "Visita al domicilio de Pelusa en Don Bosco 920. Inspección ocular de la sala temática de acceso, comedor, cocina, jardín delantero y sanitarios. Relevamiento de las 7.552 piezas de la Colección Arqueológica Clara Rosa Garín ya inventariadas por los antropólogos Heidi y Leandro. Relevamiento del mobiliario existente a adaptar (escritorio antiguo, vitrina de pared y mesas de té).", "[\"¿Qué capacidad máxima de comensales sentados permite el salón y comedor para que la experiencia sea cómoda e íntima?\",\"¿Cómo protegemos las piezas más delicadas (puntas de flecha milimétricas) del contacto directo de los visitantes?\",\"¿Qué disponibilidad de turnos fijamos por la tarde para no interferir con las mañanas de Newcom de Pelusa?\"]", "[\"Mapear el circuito físico de la visita: recepción en jardín, sala arqueológica y salón merendero.\",\"Relevar las medidas del mobiliario para cotizar las tapas de vidrio templado de seguridad.\",\"Definir el cronograma semanal de trabajo conjunto y días fijos de atención: martes, jueves y sábados.\"]", "[{\"id\":1,\"texto\":\"Inspeccionar sala temática, comedor, jardín y sanitarios en Don Bosco 920\",\"done\":false},{\"id\":2,\"texto\":\"Inventariar el mobiliario a intervenir con vidrio templado de seguridad\",\"done\":false},{\"id\":3,\"texto\":\"Establecer los días y horarios fijos semanales para las reuniones de consultoría y visitas\",\"done\":false}]", ["adria","francisco"]],
        ["porota-02", "porota", 2, "Curaduría del guion emocional de Porota, vitrinas y mesas con vidrio de seguridad", "ind", "Don Bosco 920", "2026-09-21", "15:30", "17:00", "programada", "Estructurar el guion narrativo y testimonial de Alda (\"Pelusa\"): la historia de los pioneros de Tecka (1875), la vida en Estancia La Central, las anécdotas de Porota recorriendo el campo a caballo y el rescate de las piezas líticas. Definir con el museólogo y vecino Marcelo Troiano las especificaciones técnicas de las cajas vidriadas y vitrinas para garantizar la conservación patrimonial.", "[\"¿Cuáles son las anécdotas más conmovedoras de Porota a caballo que conectan emocionalmente con el visitante?\",\"¿Qué piezas líticas seleccionamos como muestra estrella para el recorrido de 40 minutos?\",\"¿Cómo organizamos la iluminación puntual y fichas técnicas explicativas en cada mueble?\"]", "[\"Redactar el guion didáctico y emocional paso a paso de la experiencia turística.\",\"Aprobar las especificaciones técnicas de vidrios templados para el escritorio antiguo y mesas.\",\"Elaborar las fichas interpretativas de las 30 piezas arqueológicas más representativas.\"]", "[{\"id\":1,\"texto\":\"Aprobar el borrador del guion narrativo de Alda para la bienvenida y exposición\",\"done\":false},{\"id\":2,\"texto\":\"Definir el presupuesto de vidrios templados y herrajes para el mobiliario\",\"done\":false},{\"id\":3,\"texto\":\"Validar la selección de piezas con el marco de custodia legal de Patrimonio Cultural\",\"done\":false}]", ["francisco"]],
        ["porota-03", "porota", 3, "Estructura de costos, menú de la merienda de campo y tarifario dual B2C/B2B", "ind", "Melipal / Espacio LAB", "2026-10-01", "16:00", "17:30", "programada", "Construir la planilla de costeo paramétrico de la merienda casera (harina, manteca de campo, mermeladas regionales, variedades de té en hebras, café y leña/gas). Fijar la tarifa minorista por persona y un esquema dual (turistas vs residentes comarcales). Establecer comisiones del 20-25% para agencias de viajes receptivas y conserjerías de hoteles boutique de Esquel y Trevelin.", "[\"¿Cuál es el costo unitario de elaboración de la merienda y cuál es el punto de equilibrio mínimo por grupo?\",\"¿Qué precio por cubierto resulta competitivo frente a las casas de té tradicionales de la comarca?\",\"¿Qué política de reservas previas (seña del 50%) implementaremos para evitar cancelaciones?\"]", "[\"Parametrizar los costos fijos y variables de la merienda campestre.\",\"Emitir la lista oficial de precios: público general, tarifa social residente y tarifa mayorista B2B.\",\"Diseñar el protocolo de reservas anticipadas y cancelaciones con 24 hs de margen.\"]", "[{\"id\":1,\"texto\":\"Cargar la planilla de costos y márgenes de rentabilidad en Drive/Excel\",\"done\":false},{\"id\":2,\"texto\":\"Emitir la ficha tarifaria comercial para agencias y hoteles boutique\",\"done\":false},{\"id\":3,\"texto\":\"Establecer el menú fijo estacional de la merienda de campo\",\"done\":false}]", ["francisco"]],
        ["porota-04", "porota", 4, "Desarrollo de marca \"Lo de Porota\", souvenirs de autor y encuadre bromatológico", "ind", "Melipal / Espacio LAB", "2026-10-06", "10:00", "12:30", "programada", "Diseñar la identidad visual del emprendimiento: logotipo evocativo de \"Lo de Porota\", paleta cromática de tierra y piedra, tipografía rústica y elegante, y placa discreta para el portón de entrada. Prototipar el souvenir de autor: cofre rústico con 2 réplicas artesanales de puntas de flecha en arcilla/madera y fascículo biográfico \"Memorias de Porota Garín\". Revisión del trámite bromatológico simplificado.", "[\"¿Qué elementos gráficos sintetizan mejor la unión entre la arqueología lítica y el calor de la merienda hogareña?\",\"¿Qué costo de producción tienen los cofres de réplicas para asegurar un margen sustentable?\",\"¿Qué requisitos bromatológicos municipales deben verificarse en la cocina de Don Bosco 920?\"]", "[\"Aprobar la identidad visual y manual básico de marca de \\\"Lo de Porota\\\".\",\"Cotizar y prototipar la primera serie de 50 cofres de souvenirs con artesanos locales.\",\"Formalizar el cumplimiento de normas de manipulación segura de alimentos.\"]", "[{\"id\":1,\"texto\":\"Aprobar el logotipo oficial, paleta de colores y cartel de bienvenida exterior\",\"done\":false},{\"id\":2,\"texto\":\"Validar el prototipo del cofre con réplicas de puntas de flecha y cuadernillo\",\"done\":false},{\"id\":3,\"texto\":\"Completar el checklist de higiene y bromatología en el salón merendero\",\"done\":false}]", ["adria","francisco"]],
        ["porota-05", "porota", 5, "Producción audiovisual profesional 4K, tomas del jardín y canal de reservas web", "ter", "Don Bosco 920", "2026-10-14", "15:30", "17:00", "programada", "Jornada de producción fotográfica y audiovisual profesional en Don Bosco 920. Registro en video 4K de Alda en la cocina amasando pan, tomas macro de las piezas arqueológicas protegidas bajo vidrio, retratos de Porota y planos del jardín florido. Configuración de la landing page transaccional desarrollada por Leandro Choi en el ecosistema digital de Esquel, con calendario de turnos y WhatsApp Business.", "[\"¿Qué encuadres y secuencias transmiten con mayor fuerza la ternura de Pelusa y el misterio milenario de las piedras?\",\"¿Cómo estructurar la reserva online para que el turista seleccione turnos de 6 a 10 personas sin confusiones?\",\"¿Qué enlace de Mercado Pago / transferencia dejamos asociado a la seña de confirmación?\"]", "[\"Generar un banco de 30 fotografías profesionales de alta calidad y clips para reels.\",\"Publicar la landing page de reservas de \\\"Lo de Porota\\\" con pasarela de pagos.\",\"Capacitar a Pelusa y su familia en la confirmación de turnos por WhatsApp.\"]", "[{\"id\":1,\"texto\":\"Completar la sesión de fotos 4K y registro en video de la anfitriona y la colección\",\"done\":false},{\"id\":2,\"texto\":\"Aprobar la interfaz y textos de la landing page de reservas online\",\"done\":false},{\"id\":3,\"texto\":\"Cargar el catálogo de servicios con precios y horarios en WhatsApp Business\",\"done\":false}]", ["francisco"]],
        ["porota-06", "porota", 6, "Rueda comercial B2B con agencias receptivas, hoteles boutique y Marcelo Troiano", "ind", "Secretaría de Turismo / Melipal", "2026-10-27", "10:00", "12:30", "programada", "Presentar formalmente la propuesta a las principales agencias de turismo receptivo de Esquel y Trevelin, destacando su exclusividad como experiencia de cupo reducido. Coordinar alianzas con hoteles boutique céntricos para recomendar la merienda a huéspedes que buscan vivencias culturales no masivas. Articular con Marcelo Troiano (El Arroyo Que Nos Ve Crecer...) un circuito combinado de memoria urbana y merienda.", "[\"¿Qué receptividad muestran los hoteles boutique en derivar pasajeros para una merienda privada y cultural?\",\"¿Cómo articulamos con las agencias receptivas la venta anticipada de grupos exclusivos?\",\"¿Qué sinergias de promoción cruzada podemos implementar con los demás proyectos de la cohorte?\"]", "[\"Presentar el catálogo oficial a 3 agencias de viajes receptivas y 3 hoteles boutique de Esquel.\",\"Firmar al menos 2 acuerdos comerciales de derivación turística con comisiones formalizadas.\",\"Diseñar un itinerario conjunto optativo con Marcelo Troiano (visita histórica + merienda).\"]", "[{\"id\":1,\"texto\":\"Reunión comercial con agencias y alojamientos seleccionados con muestras de té y souvenirs\",\"done\":false},{\"id\":2,\"texto\":\"Firmar convenios de derivación turística con tarifario mayorista\",\"done\":false},{\"id\":3,\"texto\":\"Coordinar la primera salida combinada piloto con Marcelo Troiano\",\"done\":false}]", ["adria","francisco","leandro"]],
        ["porota-07", "porota", 7, "Simulacro vivencial de merienda (Fam Tour con informantes turísticos y guías)", "ter", "Don Bosco 920", "2026-11-10", "10:00", "12:30", "programada", "Simulacro real en Don Bosco 920 con un grupo de prueba (8 informantes de las Secretarías de Turismo de Esquel y Trevelin, guías del Parque y prestadores de la cohorte). Recorrido completo: bienvenida en el jardín, relato biográfico de Porota, exhibición de piezas en el escritorio vidriado, servicio de merienda casera caliente, entrega de souvenirs y testeo del sistema de reservas.", "[\"¿Cómo evaluaron los participantes la fluidez del guion y la calidez del trato de Alda?\",\"¿La disposición del mobiliario y los vidrios de protección garantizaron la seguridad total de las piezas?\",\"¿Qué sugerencias de mejora gastronómica o de ambientación plantearon los informantes turísticos?\"]", "[\"Validar los tiempos operativos reales de la merienda y exposición (2 horas exactas).\",\"Consolidar la soltura y confianza de Alda frente al público en su propio hogar.\",\"Recoger devoluciones técnicas mediante encuestas para perfeccionar el servicio antes del debut comercial.\"]", "[{\"id\":1,\"texto\":\"Ejecutar el Fam Tour con 8 participantes del sector turístico comarcal\",\"done\":false},{\"id\":2,\"texto\":\"Completar las encuestas de evaluación sobre hospitalidad, guion y degustación\",\"done\":false},{\"id\":3,\"texto\":\"Ajustar detalles finales del servicio de mesa y cartelería informativa\",\"done\":false}]", ["adria","francisco"]],
        ["porota-08", "porota", 8, "Distinción, resultados y rueda de negocios en Melipal", "cie", "Centro Cultural Melipal", "2026-11-19", "10:00", "13:00", "programada", "Participación protagónica en el Encuentro de Cierre de Esquel LAB en el Centro Cultural Melipal. Montaje de mesa temática de \"Lo de Porota\" con fotografías históricas de Tecka, piezas representativas en vitrina cerrada, muestras del cofre de souvenirs y degustación de tortas fritas caseras. Pitch institucional de 3 minutos de Alda Inés Mateo Garín. Firma de acuerdos comerciales y entrega del plan operativo post-LAB.", "[\"¿Qué balance arrojan las primeras reservas turísticas ingresadas a través de la web y agencias?\",\"¿Cómo se organizará el calendario operativo de Pelusa para la temporada alta de verano 2026/2027?\",\"¿Qué pasos siguen para la gestión de fondos de mejora edilicia ante Cultura o Municipio?\"]", "[\"Exhibir el producto consolidado ante autoridades municipales, prestadores y medios de comunicación.\",\"Consolidar convenios comerciales firmes con el sector privado para el verano.\",\"Entregar el informe final de consultoría técnica y hoja de ruta post-incubación.\"]", "[{\"id\":1,\"texto\":\"Montar stand interactivo con vitrina de piezas, souvenirs y degustación campesina\",\"done\":false},{\"id\":2,\"texto\":\"Exponer el pitch de 3 minutos de Alda ante autoridades y empresarios turísticos\",\"done\":false},{\"id\":3,\"texto\":\"Firmar acuerdos comerciales formales y entrega de la hoja de ruta 2026/2027\",\"done\":false}]", ["leandro","adria","mariela","francisco","agustina","cesia","noelia"]],
        ["senderos-01", "senderos", 1, "Relevamiento en terreno del Sendero La Cascada y punto cero", "ter", "Acceso La Cascada / Senda Cámpora", "2026-09-23", "10:00", "12:30", "programada", "Caminar el circuito accesible de La Cascada. Identificar especies nativas presentes (llantén, paramela, palo piche, rosa mosqueta), medir tiempos de caminata pausada y seleccionar los 3 puntos de parada interpretativa.", "[\"¿Cuánto tiempo real demanda recorrer el sendero parando a observar 5 plantas?\",\"¿Qué puntos ofrecen sombra y bancos para la merienda final?\"]", "[\"Mapear las 5 paradas botánicas del sendero La Cascada.\",\"Cronometrar la duración total (máximo 1h 45m).\",\"Fotografiar las plantas nativas para el tríptico.\"]", "[{\"id\":1,\"texto\":\"Mapear las 5 paradas botánicas en La Cascada\",\"done\":false},{\"id\":2,\"texto\":\"Cronometrar duración de caminata pausada\",\"done\":false},{\"id\":3,\"texto\":\"Fotografiar especies nativas para el tríptico\",\"done\":false}]", ["adria","francisco"]],
        ["senderos-02", "senderos", 2, "Traqueo del Cañadón de Bórquez a La Zeta y diseño del tríptico", "ter", "Cañadón de Bórquez a La Zeta", "2026-10-07", "14:30", "16:30", "programada", "Realizar el traqueo GPS del sendero del Cañadón de Bórquez hasta Laguna La Zeta. Revisar el borrador del tríptico de bolsillo y definir el contenido botánico y didáctico.", "[\"¿Cómo resolvemos los tramos con pendiente para personas no habituadas a la montaña?\",\"¿Qué información técnica debe incluir el folleto sin saturar al turista?\"]", "[\"Track GPS exportado en formato GPX/KML.\",\"Textos y fichas botánicas del tríptico corregidos.\",\"Selección de especies para el desafío fotográfico.\"]", "[{\"id\":1,\"texto\":\"Traquear recorrido con GPS hasta La Zeta\",\"done\":false},{\"id\":2,\"texto\":\"Revisar textos botánicos del tríptico de bolsillo\",\"done\":false},{\"id\":3,\"texto\":\"Definir dinámica de desafío fotográfico\",\"done\":false}]", ["francisco"]],
        ["senderos-03", "senderos", 3, "Protocolo de seguridad, evacuación y taller de comunicaciones VHF", "ind", "Protección Civil Municipal", "2026-10-14", "09:30", "12:00", "programada", "Diseñar el Plan de Contingencias y Evacuación de los 3 senderos. Establecer frecuencias de radio VHF/UHF, pautas de aviso a Defensa Civil y repaso de botiquín WFR.", "[\"¿Qué protocolo seguimos si un turista sufre un esguince en el Cañadón de las Palomas?\",\"¿Cuáles son los puntos de extracción vehicular más cercanos?\"]", "[\"Ficha de Gestión del Riesgo y Plan de Evacuación firmada.\",\"Pauta de frecuencias de radio municipal asignada.\",\"Protocolo de aptitud física previa para excursionistas.\"]", "[{\"id\":1,\"texto\":\"Diseñar plan de evacuación para los 3 senderos\",\"done\":false},{\"id\":2,\"texto\":\"Fijar frecuencias VHF con Protección Civil\",\"done\":false},{\"id\":3,\"texto\":\"Verificar botiquín agreste WFR/RCP\",\"done\":false}]", ["adria","francisco"]],
        ["senderos-04", "senderos", 4, "Costeo de salidas y matriz de precios (Célula 3)", "ter", "Célula 3 (Melipal)", "2026-10-21", "14:30", "16:00", "programada", "Calcular la estructura de costos de cada salida: honorarios de las guías, seguro de accidentes personales, impresión de trípticos, insumos del souvenir cosmético, merienda campestre y comisión para agencias (20%).", "[\"¿Cuánto vale el servicio guiado de 2 horas con souvenir incluido?\",\"¿Cuál es el cupo mínimo para no salir a pérdida?\"]", "[\"Planilla de costos fijos y variables completada.\",\"Punto de equilibrio fijado en 4 pasajeros.\",\"Tarifario para venta directa y tarifa neta para agencias hoteleras.\"]", "[{\"id\":1,\"texto\":\"Completar matriz de costeo por salida\",\"done\":false},{\"id\":2,\"texto\":\"Fijar punto de equilibrio en 4 pasajeros\",\"done\":false},{\"id\":3,\"texto\":\"Establecer tarifario B2C y tarifa neta B2B\",\"done\":false}]", ["francisco"]],
        ["senderos-05", "senderos", 5, "Ensayo del guion sensorial y dinámica de \"bajada a tierra\"", "ter", "Mirador La Zeta", "2026-10-28", "09:30", "12:30", "programada", "Probar en terreno la dinámica de meditación, descalzado y respiración consciente en el mirador. Ajustar la transición hacia la mateada campesina y la cata de aromas.", "[\"¿Cómo rompemos la timidez del turista urbano para que se anime a sacarse las zapatillas?\",\"¿Qué tono de voz y silencios acompañan mejor la experiencia?\"]", "[\"Guion de facilitación sensorial cronometrado (15 minutos de meditación).\",\"Logística de termo, mates individuales y hierbas probada en mochila.\",\"Protocolo de higiene para degustación.\"]", "[{\"id\":1,\"texto\":\"Cronometrar pausa de respiración y descalzado\",\"done\":false},{\"id\":2,\"texto\":\"Probar cebado de mates con paramela y llantén\",\"done\":false},{\"id\":3,\"texto\":\"Estandarizar guion narrativo de cierre\",\"done\":false}]", ["adria","francisco"]],
        ["senderos-06", "senderos", 6, "Vinculación institucional con CAPEC y registro de prestadores", "ind", "CAPEC / Producción", "2026-11-04", "14:30", "16:30", "programada", "Evaluar el marco normativo para la elaboración de cosmética natural en salas comunitarias bajo estándares ANMAT/provinciales. Iniciar trámite en el Registro de Turismo Alternativo de la Subsecretaría de Turismo.", "[\"¿Qué requisitos de rotulado y loteado exige la comercialización turística de cosméticos?\",\"¿Cómo formalizamos el alta en turismo alternativo municipal?\"]", "[\"Diagnóstico de adecuación de envases y etiquetas con CAPEC.\",\"Formulario de inscripción en Turismo Alternativo completado.\",\"Asesoramiento contable para monotributo.\"]", "[{\"id\":1,\"texto\":\"Reunión técnica en CAPEC con Paula Botto\",\"done\":false},{\"id\":2,\"texto\":\"Completar solicitud de Turismo Alternativo\",\"done\":false},{\"id\":3,\"texto\":\"Definir encuadre de facturación y monotributo\",\"done\":false}]", ["francisco"]],
        ["senderos-07", "senderos", 7, "Salida piloto con público testigo y producción de contenidos", "ter", "Circuito Cañadón de Bórquez", "2026-11-11", "09:30", "12:00", "programada", "Ejecutar la experiencia completa con un grupo testigo real (invitados de taekwondo y equipo municipal). Registrar fotografías profesionales y clips de video para redes sociales y folletería digital.", "[\"¿Cómo reaccionan los participantes ante el desafío del tríptico y el momento de descalzarse?\",\"¿Qué ajustes de ritmo se requieren?\"]", "[\"Salida piloto completada con 10 personas.\",\"Encuestas de satisfacción recogidas.\",\"Banco de 25 fotos profesionales y 3 reels en alta definición.\"]", "[{\"id\":1,\"texto\":\"Guiar salida piloto con 10 asistentes\",\"done\":false},{\"id\":2,\"texto\":\"Levantar encuestas de satisfacción\",\"done\":false},{\"id\":3,\"texto\":\"Obtener banco de imágenes y clips de video\",\"done\":false}]", ["adria","francisco"]],
        ["senderos-08", "senderos", 8, "Distinción, resultados y rueda de negocios en Melipal", "cie", "Centro Cultural Melipal", "2026-11-19", "10:00", "13:00", "programada", "Presentar el producto terminado ante agencias receptivas, hoteles y comercios comarcales en la rueda de negocios. Exhibir el stand interactivo con ramas secas, muestras de ungüentos y trípticos.", "[\"¿Qué agencias de Esquel incorporan las salidas regulares a su tarifario de verano?\",\"¿Cómo queda enlazado el botón de reserva en la web oficial?\"]", "[\"Stand montado con experiencia de aromas y cosmética.\",\"Pitch de 3 minutos de Gabriela y Florencia.\",\"Firma de cartas de intención con al menos 2 agencias receptivas locales.\"]", "[{\"id\":1,\"texto\":\"Montar stand interactivo con cosmética y flora seca\",\"done\":false},{\"id\":2,\"texto\":\"Exponer pitch de 3 minutos ante prestadores\",\"done\":false},{\"id\":3,\"texto\":\"Firmar al menos 2 cartas de intención con agencias\",\"done\":false}]", ["leandro","adria","mariela","francisco","agustina","cesia","noelia"]],
        ["yamamori-01", "yamamori", 1, "Diagnóstico operativo, análisis del piloto de octubre y devolución técnica", "ind", "Virtual / Esquel LAB", "2026-09-22", "09:30", "11:30", "programada", "Revisar la grilla operativa del viaje piloto del 30 de octubre. Validar el estado de reservas de combi, hotelería (Sur Sur y Trevelin), La Trochita y el Museo Histórico con Carla. Establecer el protocolo de contingencias.", "[\"¿Qué aspecto del itinerario de octubre genera mayor incertidumbre logística?\",\"¿Cómo coordinamos los traslados del aeropuerto con la combi contratada?\",\"¿Qué seguro de viaje cubre a los 10 pasajeros?\"]", "[\"Planilla de reservas y vouchers del viaje de octubre completada.\",\"Cronograma minuto a minuto de las 4 jornadas.\",\"Confirmación de póliza de asistencia médica y seguro de accidentes.\"]", "[{\"id\":1,\"texto\":\"Revisar planilla de reservas y vouchers de octubre\",\"done\":false},{\"id\":2,\"texto\":\"Validar cronograma minuto a minuto con transportista\",\"done\":false},{\"id\":3,\"texto\":\"Confirmar póliza de seguro de viaje para los 10 pasajeros\",\"done\":false}]", ["mariela","agustina"]],
        ["yamamori-02", "yamamori", 2, "Curaduría de itinerarios desestacionalizados (Otoño de Lenga, Invierno & Sakura)", "ind", "Virtual / Gabinete Técnico", "2026-10-02", "10:00", "12:00", "programada", "Estructurar las fichas técnicas de los dos paquetes desestacionalizados para 2027: 1) \"Colores del Otoño & Bosques de Lenga\" (marzo/abril); 2) \"Ciruelos en Flor & El Sakura Patagónico\" (septiembre/octubre). Fijar duraciones de 4 días / 3 noches y cupos cerrados de 8 a 10 pasajeros.", "[\"¿Cómo destacamos el florecimiento de ciruelos en la avenida Ameghino como atractivo cultural?\",\"¿Qué estancias rurales garantizan calidez y gastronomía típica en otoño?\"]", "[\"Redactar ficha descriptiva del paquete Otoño de Lenga.\",\"Redactar ficha del paquete Sakura de Esquel.\",\"Definir fechas tentativas del calendario 2027.\"]", "[{\"id\":1,\"texto\":\"Redactar ficha técnica del paquete Otoño de Lenga\",\"done\":false},{\"id\":2,\"texto\":\"Redactar ficha del paquete Sakura Patagónico en Ameghino\",\"done\":false},{\"id\":3,\"texto\":\"Definir calendario de 4 salidas para 2027\",\"done\":false}]", ["agustina"]],
        ["yamamori-03", "yamamori", 3, "Articulación territorial y cruces con emprendimientos de la cohorte", "ind", "Turismo / Virtual", "2026-10-06", "09:30", "11:30", "programada", "Conectar formalmente a Yamamori con prestadores de la cohorte: provisión de té verde de autor con Sandra Roberts (Haiku), visita a talleres de tornería de madera con Andrés Crova en Alto Río Percy, y coordinación de obsequios artesanales de bienvenida.", "[\"¿Qué formato de cata o servicio de té puede ofrecer Haiku a los grupos de Julia?\",\"¿Cómo organizamos una parada de 45 minutos en el taller de tornería sin entorpecer la producción?\"]", "[\"Acuerdo preliminar de provisión de té con Haiku.\",\"Inclusión de la parada en Percy en el dossier comercial.\",\"Definición del souvenir de madera de lenga o té patagónico.\"]", "[{\"id\":1,\"texto\":\"Pautar provisión de té verde con Haiku\",\"done\":false},{\"id\":2,\"texto\":\"Programar parada de visita con Los Crovas en Percy\",\"done\":false},{\"id\":3,\"texto\":\"Definir recuerdo artesanal de lenga para los grupos\",\"done\":false}]", ["mariela","agustina"]],
        ["yamamori-04", "yamamori", 4, "Costeo B2B, tarifarios netos y márgenes (Célula 4)", "ind", "Célula 4 (Melipal)", "2026-10-16", "10:00", "11:30", "programada", "Construir la matriz de costeo integral de los paquetes de autor. Separar costos fijos (transporte privado, coordinación, guías de sitio) y variables (hotelería, comidas, ingresos, seguros), estableciendo la tarifa neta confidencial y el margen de intermediación comercial.", "[\"¿Cuál es el costo unitario por pasajero en base doble para grupos de 8 personas?\",\"¿Qué honorario de coordinación neta percibe Julia?\",\"¿Qué comisión del 15% al 20% se asigna al canal minorista?\"]", "[\"Planilla Excel de costeo integral parametrizada.\",\"Punto de equilibrio fijado en 6 pasajeros.\",\"Tarifario cerrado en pesos y en dólares para receptivo internacional.\"]", "[{\"id\":1,\"texto\":\"Completar planilla de costeo integral parametrizada\",\"done\":false},{\"id\":2,\"texto\":\"Fijar punto de equilibrio en 6 pasajeros\",\"done\":false},{\"id\":3,\"texto\":\"Definir tarifario neto confidencial y PVP\",\"done\":false}]", ["agustina"]],
        ["yamamori-05", "yamamori", 5, "Protocolo de hospitalidad \"Omotenashi Patagónico\" y kit de bienvenida", "ind", "Virtual / Gabinete", "2026-10-23", "10:00", "12:00", "programada", "Diseñar el manual de procedimientos de hospitalidad omotenashi adaptado a la Patagonia: recepción en aeropuerto, kit de bienvenida en la habitación (pantuflas artesanales, termo con té verde de Haiku), toallas tibias en excursiones y encuesta de satisfacción sensorial.", "[\"¿Qué elementos tangibles componen el kit de bienvenida?\",\"¿Cómo capacitamos al transportista y al personal del hotel para que respeten las pautas de cortesía japonesa?\"]", "[\"Documento del protocolo Omotenashi redactado.\",\"Presupuesto del kit de bienvenida por pasajero.\",\"Modelo de encuesta de satisfacción post-viaje en español e inglés/japonés.\"]", "[{\"id\":1,\"texto\":\"Redactar manual de protocolo Omotenashi\",\"done\":false},{\"id\":2,\"texto\":\"Presupuestar kit de bienvenida por pasajero\",\"done\":false},{\"id\":3,\"texto\":\"Diseñar encuesta de satisfacción sensorial post-viaje\",\"done\":false}]", ["mariela","agustina"]],
        ["yamamori-06", "yamamori", 6, "Encuadre legal, seguros y convenio marco con agencia receptiva (EVyT)", "ind", "Turismo", "2026-11-06", "10:00", "12:00", "programada", "Redactar y suscribir el modelo de convenio marco de cooperación comercial entre Yamamori Travel y una Agencia de Viajes Receptiva (EVyT) habilitada de Esquel. Delimitar responsabilidades legales, cobertura de seguros, facturación y cobro de señas.", "[\"¿Qué agencia local asume la responsabilidad técnica y emisión de vouchers?\",\"¿Cómo se gestionan las pólizas de seguro de turismo alternativo y accidentes personales?\"]", "[\"Borrador del convenio marco con agencia EVyT local.\",\"Protocolo de contratación de pólizas de asistencia médica.\",\"Políticas de reserva, pago anticipado y cancelación estricta.\"]", "[{\"id\":1,\"texto\":\"Redactar modelo de convenio marco con agencia EVyT\",\"done\":false},{\"id\":2,\"texto\":\"Establecer protocolo de seguros y asistencia al viajero\",\"done\":false},{\"id\":3,\"texto\":\"Definir políticas de cobro, señas y cancelación\",\"done\":false}]", ["agustina"]],
        ["yamamori-07", "yamamori", 7, "Estrategia de comunicación bilingüe, Instagram de autor y difusión", "ind", "Virtual / Gabinete", "2026-11-10", "09:30", "11:30", "programada", "Optimizar el perfil de Instagram @yamamoritravel con narrativa bilingüe (español/japonés). Diseñar el brochure digital comercial en PDF con estética minimalista japonesa, destacando las bondades de Esquel como destino seguro, puro y exclusivo.", "[\"¿Cómo explicamos el concepto de Yamamori y Omotenashi en las redes sin perder cercanía con el público argentino?\",\"¿Qué material de registro se tomará durante el viaje piloto de octubre?\"]", "[\"Bio de Instagram optimizada con enlace directo a WhatsApp y brochure.\",\"Ficha técnica comercial digital en PDF lista para agencias.\",\"Pauta de registro fotográfico y video durante el viaje del 30/10.\"]", "[{\"id\":1,\"texto\":\"Optimizar biografía y feed bilingüe en Instagram\",\"done\":false},{\"id\":2,\"texto\":\"Maquetar brochure digital comercial en PDF\",\"done\":false},{\"id\":3,\"texto\":\"Definir pauta de cobertura fotográfica para el viaje del 30/10\",\"done\":false}]", ["mariela","agustina"]],
        ["yamamori-08", "yamamori", 8, "Distinción, resultados y rueda de negocios en Melipal", "cie", "Centro Cultural Melipal", "2026-11-19", "10:00", "13:00", "programada", "Presentar las conclusiones y métricas reales del viaje piloto ejecutado del 30 de octubre al 2 de noviembre. Participar en la rueda de negocios con el sector hotelero y agencias receptivas de Esquel, presentando el calendario oficial de salidas 2027.", "[\"¿Qué devoluciones dieron los 10 pasajeros del viaje de octubre?\",\"¿Qué ajustes operativos requiere el paquete para la temporada 2027?\",\"¿Qué alianzas comerciales quedan selladas?\"]", "[\"Informe de balance y evaluación de satisfacción del viaje piloto.\",\"Presentación del calendario de 4 salidas para 2027.\",\"Firma de convenios comerciales con prestadores locales.\"]", "[{\"id\":1,\"texto\":\"Presentar informe de balance y métricas del viaje piloto\",\"done\":false},{\"id\":2,\"texto\":\"Exponer calendario 2027 en la rueda de negocios\",\"done\":false},{\"id\":3,\"texto\":\"Firmar al menos 2 acuerdos comerciales con prestadores locales\",\"done\":false}]", ["leandro","adria","mariela","francisco","agustina","cesia","noelia"]],
        ["arroyo-01", "arroyo", 1, "Relevamiento en terreno del arroyo y delimitación de paradas sociohistóricas", "ter", "Márgenes del Arroyo Esquel (Punto cero: Av. Fontana y Arroyo)", "2026-09-18", "10:00", "12:30", "programada", "Caminar las riberas del arroyo Esquel junto a Marcelo desde Av. Fontana hasta el Puente de Molinari. Identificar hitos de arqueología urbana (el Molino Weber, la vieja Planta de Gas, la fractura del terraplén ferroviario) y relevar accesibilidad de veredas, cruces peatonales y estado ambiental de las márgenes.", "[\"¿Qué historias orales y personajes cotidianos podemos rescatar en cada uno de estos 5 puntos para que el visitante se sienta inmerso en la vida real de Esquel?\",\"¿Qué riesgos de transitabilidad o cruce identificamos para grupos de adultos mayores o familias con niños?\",\"¿Cómo abordamos didácticamente el contraste ambiental entre la limpieza de los años 90 y los desafíos actuales del cauce?\"]", "[\"Mapear con GPS el trazado físico preliminar del Circuito 1 (El Origen entre el Arroyo y las Vías).\",\"Definir las primeras 5 estaciones interpretativas y sus conceptos históricos vertebrales.\",\"Establecer los criterios de seguridad peatonal y tiempos de permanencia en cada parada.\"]", "[{\"id\":1,\"texto\":\"Caminar el tramo Fontana-Molinari y registrar coordenadas de 5 estaciones clave\",\"done\":false},{\"id\":2,\"texto\":\"Documentar el estado de veredas, pasarelas y accesos a las márgenes del arroyo\",\"done\":false},{\"id\":3,\"texto\":\"Fijar la duración máxima de la caminata peatonal en 90 minutos netos\",\"done\":false}]", ["adria","francisco"]],
        ["arroyo-02", "arroyo", 2, "Prospección en laderas, mirador de La Gruta y articulación vecinal", "ter", "Barrio Ceferino / Gruta del Padre Parolini", "2026-10-02", "15:00", "17:30", "programada", "Recorrer el ascenso peatonal hacia La Gruta del Ceferino por la escalinata barrial. Evaluar el mirador panorámico como estación de interpretación urbana (donde se observa el crecimiento de la ciudad). Contactar a vecinas del barrio (Doña Pepa / elaboradoras de tortas fritas) para evaluar la factibilidad de una parada de mate y sabor campesino.", "[\"¿Cómo reciben los vecinos del barrio la idea de que un grupo reducido de turistas suba a la gruta y comparta una merienda tradicional?\",\"¿Qué relatos del Padre Parolini y de los primeros pobladores de las laderas le dan mística al mirador?\",\"¿Cuál es el esfuerzo físico real que demanda subir la escalinata y cómo lo adaptamos para distintos públicos?\"]", "[\"Definir la viabilidad del Circuito 2 (Laderas, Gruta y Memoria Viva).\",\"Acordar con una vecina o comercio barrial la provisión de tortas fritas caseras y servicio de mate.\",\"Diseñar la parada en La Gruta como punto cúspide de la experiencia inmersiva.\"]", "[{\"id\":1,\"texto\":\"Cronometrar los tiempos de ascenso y descenso por la escalinata del Ceferino\",\"done\":false},{\"id\":2,\"texto\":\"Entrevistar a vecinas del sector para consensuar la dinámica de bienvenida comunitaria\",\"done\":false},{\"id\":3,\"texto\":\"Asegurar condiciones de higiene y calidez para la merienda popular en el mirador\",\"done\":false}]", ["francisco"]],
        ["arroyo-03", "arroyo", 3, "Estructuración del guion interpretativo y diseño del libro-souvenir", "ind", "LAB Esquel / Secretaría de Turismo", "2026-10-09", "10:00", "12:30", "programada", "Trabajar en gabinete la dramaturgia del guiado: transformar la erudición histórica en un relato empático y emocionante de 90 a 120 minutos. Seleccionar las anécdotas, fotografías de época y documentos que componen el libro-souvenir Postales históricas de Esquel, definiendo su formato de entrega y packaging artesanal.", "[\"¿Cómo dosificamos la información para que el visitante no se sienta abrumado por fechas, sino conmovido por la vivencia humana?\",\"¿Qué formato físico de folleto de bolsillo o postal coleccionable acompaña al libro para entregar durante la caminata?\",\"¿Cómo articulamos la figura de Marcelo como anfitrión inspirador con futuros guías jóvenes o estudiantes de turismo co-anfitriones?\"]", "[\"Cerrar el guion narrativo modular de los dos circuitos (estaciones, relatos, remates y preguntas reflexivas).\",\"Prototipar la presentación editorial del libro Postales históricas de Esquel como souvenir de alto valor.\",\"Elaborar el decálogo de buenas prácticas de turismo comunitario y respeto vecinal.\"]", "[{\"id\":1,\"texto\":\"Aprobar el guion literario y técnico de las 5 estaciones del Circuito 1\",\"done\":false},{\"id\":2,\"texto\":\"Definir el costo de imprenta y precio del libro-souvenir de autor\",\"done\":false},{\"id\":3,\"texto\":\"Diseñar el tríptico de mano con el mapa de la cuenca y puntos de memoria\",\"done\":false}]", ["adria","francisco"]],
        ["arroyo-04", "arroyo", 4, "Estructura de costos, tarifario y alianzas con comercios del arroyo", "ind", "LAB Esquel", "2026-10-16", "15:00", "17:00", "programada", "Definir el modelo económico de la experiencia. Desglosar costos: honorarios del historiador/guía, compra de tortas fritas/refrigerio a vecinas, costo de impresión de postales/souvenirs y margen de comercialización. Fijar precio por persona (B2C), tarifa diferenciada para residentes y comisión del 20-25% para agencias receptivas y hoteles.", "[\"¿Cuál es el tamaño óptimo de grupo (mínimo 4, máximo 12 personas) para no perder la intimidad del relato?\",\"¿Qué acuerdo comercial establecemos con Panadería Genes o el Molino para paradas de café y descanso?\",\"¿Qué días y horarios fijos semanales se ofrecerá la salida regular para facilitar la venta en agencias?\"]", "[\"Construir la planilla paramétrica de costos y punto de equilibrio por salida.\",\"Fijar el tarifario comercial oficial B2C y B2B para la temporada primavera/verano 2026.\",\"Establecer el calendario de salidas regulares (ej. viernes y sábados por la tarde).\"]", "[{\"id\":1,\"texto\":\"Calcular costo por pasajero y punto de equilibrio financiero (4 pasajeros)\",\"done\":false},{\"id\":2,\"texto\":\"Emitir la ficha tarifaria formal para agencias receptivas de Esquel\",\"done\":false},{\"id\":3,\"texto\":\"Formalizar el acuerdo de consumo y parada técnica con Panadería Genes / comercio local\",\"done\":false}]", ["francisco"]],
        ["arroyo-05", "arroyo", 5, "Plataforma digital, autoguiado interactivo y pasarela de cobro", "ind", "LAB Esquel / Espacio Digital", "2026-10-30", "10:00", "12:30", "programada", "Diseñar la landing page oficial de El Arroyo que nos ve crecer.... Cargar el mapa geolocalizado en la web de turismo de Esquel con el circuito autoguiado (audioguías breves y fotos históricas de los años 30-50). Configurar el canal de reservas por WhatsApp Business y la pasarela de pagos con Mercado Pago para cobro online de las caminatas guiadas.", "[\"¿Qué locuciones breves (1 minuto por estación) puede grabar Marcelo para el audioguía digital?\",\"¿Cómo facilitamos que un vecino o turista escanee el código QR en la vía pública sin necesidad de app pesada?\",\"¿Qué datos de contacto y comprobantes de reserva automatizamos para el turista?\"]", "[\"Maquetar la landing page con la identidad visual del proyecto y mapa interactivo.\",\"Grabar 5 micro-audios testimoniales de Marcelo para el sistema autoguiado.\",\"Configurar la cuenta de cobro digital Mercado Pago vinculada al sistema de reservas.\"]", "[{\"id\":1,\"texto\":\"Publicar la landing page informativa y el mapa interactivo del recorrido\",\"done\":false},{\"id\":2,\"texto\":\"Subir los 5 archivos de audio interpretativo al servidor de Esquel Destino\",\"done\":false},{\"id\":3,\"texto\":\"Validar el link de pago y el formulario de reserva online\",\"done\":false}]", ["adria","francisco","leandro"]],
        ["arroyo-06", "arroyo", 6, "Sinergias de cohorte (Corcho Bikes, La Trochita) y rueda con agencias", "ind", "Oficinas de Turismo / Centro Cultural Melipal", "2026-11-06", "15:00", "17:00", "programada", "Articulación intersectorial: reunirse con Néstor Colinecul (Corcho Bikes) para diseñar la variante Cicloturismo Histórico del Arroyo (alquiler de bicis + guiado). Presentar la caminata a agencias receptivas locales (EVyT) y prestadores hoteleros como complemento ideal para días sin excursiones largas o tardes libres de La Trochita.", "[\"¿Cómo sincronizamos el horario de llegada del tren de La Trochita con el inicio de la caminata en Av. Fontana?\",\"¿Qué tarifa combinada bici-tour podemos estructurar junto a Corcho Bikes?\",\"¿Qué material gráfico impreso dejamos en los mostradores de información turística y recepciones de hoteles?\"]", "[\"Definir el paquete combinado de cicloturismo histórico junto a Corcho Bikes.\",\"Firmar al menos 2 acuerdos de comercialización y derivación con agencias receptivas habilitadas.\",\"Distribuir el folleto promocional en los centros de informes turísticos municipales.\"]", "[{\"id\":1,\"texto\":\"Redactar la ficha de producto combinado bici-tour con Corcho Bikes\",\"done\":false},{\"id\":2,\"texto\":\"Reunirse con 3 agencias de turismo receptivo de Esquel\",\"done\":false},{\"id\":3,\"texto\":\"Dejar material promocional impreso en la Secretaría de Turismo y Melipal\",\"done\":false}]", ["francisco"]],
        ["arroyo-07", "arroyo", 7, "Caminata de validación en campo (Fam Tour con informantes y guías)", "ter", "Márgenes del Arroyo Esquel y Mirador del Ceferino", "2026-11-13", "10:00", "12:30", "programada", "Salida piloto en terreno con un grupo de prueba de 8 personas (informantes turísticos municipales, guías de turismo matriculados y vecinos invitados). Ejecución completa del guiado, paradas interpretativas, merienda de tortas fritas con doña Pepa y entrega simbólica del libro-souvenir. Medición de tiempos, retroalimentación y ajuste de dinámicas grupales.", "[\"¿Cómo funcionó el ritmo de marcha y la acústica urbana del relato en cada parada?\",\"¿Qué emociones y aprendizajes destacaron los participantes en la encuesta de satisfacción?\",\"¿Qué ajustes finales requiere el trato con los vecinos y la logística de la merienda?\"]", "[\"Validar la experiencia integral en condiciones reales de operación turística.\",\"Recopilar encuestas de calidad, testimonios y sugerencias de mejora del sector profesional.\",\"Generar registro fotográfico y en video de la caminata para promoción en redes y medios.\"]", "[{\"id\":1,\"texto\":\"Realizar el Fam Tour completo con 8 participantes invitados\",\"done\":false},{\"id\":2,\"texto\":\"Completar planilla de evaluación de tiempos, narrativa y paradas gastronómicas\",\"done\":false},{\"id\":3,\"texto\":\"Obtener banco de fotos y clips audiovisuales de la experiencia en campo\",\"done\":false}]", ["adria","francisco"]],
        ["arroyo-08", "arroyo", 8, "Distinción, resultados y rueda de negocios en Melipal", "cie", "Centro Cultural Melipal", "2026-11-19", "10:00", "13:00", "programada", "Participación protagónica en el Encuentro de Cierre de Esquel LAB. Montaje del espacio de El Arroyo que nos ve crecer... con exhibición del libro Postales históricas de Esquel, mapas de cuenca y fotografías antiguas. Pitch de 3 minutos de Marcelo Troiano presentando el producto ante operadores turísticos, prensa y autoridades. Entrega del plan de continuidad comercial y sustentabilidad comunitaria.", "[\"¿Qué balance arroja el proceso de aceleración y cómo se siente Marcelo en su nuevo rol de anfitrión turístico?\",\"¿Cómo se proyecta la incorporación de jóvenes guías del CFP Nº 655 para la temporada alta de verano?\",\"¿Qué articulación se mantendrá con la Secretaría de Turismo para eventos culturales y fechas históricas?\"]", "[\"Presentar oficialmente el producto turístico ante el ecosistema turístico y los medios de prensa.\",\"Consolidar compromisos comerciales firmes de comercialización para el verano 2026/2027.\",\"Entregar el informe de cierre de asistencia técnica y manual operativo del recorrido.\"]", "[{\"id\":1,\"texto\":\"Montar mesa expositora con libros, fotos patrimoniales y postales históricas\",\"done\":false},{\"id\":2,\"texto\":\"Exponer el pitch de 3 minutos ante prestadores y autoridades municipales\",\"done\":false},{\"id\":3,\"texto\":\"Firmar cartas de compromiso comercial con agencias y hoteles de Esquel\",\"done\":false}]", ["leandro","adria","mariela","francisco","agustina","cesia","noelia"]],
        ["vicotita-01", "vicotita", 1, "Relevamiento en terreno: taller, procesos y muestras históricas", "ter", "Taller Chanico Navarro (Pintor Antúnez 968)", "2026-09-23", "09:30", "11:00", "programada", "Relevar las maquinarias de serigrafía, shablonadora, stock de telas impermeables, herramientas de encuadernación y muestras de productos históricos.", "[\"¿Cuáles son los productos con menor tiempo de confección y mejor margen?\",\"¿Qué capacidad de almacenamiento y aprovisionamiento de telas tienen hoy?\"]", "[\"Inventariar maquinaria y herramientas de taller.\",\"Fotografiar muestras de encuadernación y marroquinería.\",\"Analizar compras de insumos por volumen.\"]", "[{\"id\":1,\"texto\":\"Relevar máquinas de coser, shablones y mesas de corte\",\"done\":false},{\"id\":2,\"texto\":\"Inventariar telas impermeables y tipos de papel\",\"done\":false},{\"id\":3,\"texto\":\"Fotografiar muestras históricas y piezas de Puro Diseño\",\"done\":false},{\"id\":4,\"texto\":\"Definir el flujo de trabajo entre ambos domicilios\",\"done\":false}]", ["mariela","cesia"]],
        ["vicotita-02", "vicotita", 2, "Storytelling de marca, marbete narrativo y código QR", "ind", "Turismo", "2026-09-25", "15:00", "16:30", "programada", "Traducir la profundidad del relato mapuche contemporáneo en un texto breve para marbetes y tarjetas de autenticidad que acompañen cada pieza.", "[\"¿Cómo explicamos el símbolo del Quñegüe o el punto nimín en 3 oraciones sencillas?\",\"¿Qué llamado a la acción incluimos en el código QR?\"]", "[\"Redactar el texto del marbete de autor.\",\"Diseñar el boceto de la tarjeta con código QR.\",\"Cotizar impresión con imprentas locales.\"]", "[{\"id\":1,\"texto\":\"Redactar el texto del marbete en español y mapuzugun\",\"done\":false},{\"id\":2,\"texto\":\"Diseñar el mockup de tarjeta de autenticidad con QR\",\"done\":false},{\"id\":3,\"texto\":\"Configurar landing/enlace con galería del proceso artesanal\",\"done\":false},{\"id\":4,\"texto\":\"Seleccionar imprenta local para tirada de prueba\",\"done\":false}]", ["cesia"]],
        ["vicotita-03", "vicotita", 3, "Prototipado de la Bitácora de Campo y Registro de Montaña", "ind", "Turismo", "2026-10-07", "09:30", "11:00", "programada", "Definir el formato físico, encuadernación y contenido interior de la libreta de registro de senderos y montaña para prestadores.", "[\"¿Qué tamaño es el más práctico para llevar en la mochila de trekking (A5 o A6)?\",\"¿Qué secciones de coordenadas y apuntes incluimos en las hojas?\"]", "[\"Definir gramaje de hojas y tipo de encuadernación (cosida o brocheada).\",\"Redactar el contenido de las páginas interiores.\",\"Armar el primer boceto físico.\"]", "[{\"id\":1,\"texto\":\"Definir medidas estándar de corte A5/A6\",\"done\":false},{\"id\":2,\"texto\":\"Diagramar la grilla de coordenadas y mapa de senderos\",\"done\":false},{\"id\":3,\"texto\":\"Seleccionar micro-poesías de autores patagónicos\",\"done\":false},{\"id\":4,\"texto\":\"Confeccionar el primer ejemplar de prueba\",\"done\":false}]", ["mariela","cesia"]],
        ["vicotita-04", "vicotita", 4, "Costeo, volumen y consignación (Célula 1)", "ind", "Célula 1 (Melipal)", "2026-10-15", "16:30", "18:00", "programada", "Encuentro grupal de la Célula 1 (Oficio y pieza). Poner en común matrices de costeo, valor de hora de taller, esquemas de comisiones para revendedores y acuerdos de no canibalización.", "[\"¿Qué porcentaje es justo dejarle a una recepción de hotel o tienda regional?\",\"¿Conviene vender en firme con descuento o en consignación?\"]", "[\"Comparar costos fijos y variables con otros artesanos.\",\"Validar escala de descuentos mayoristas.\",\"Evaluar alianzas de empaque conjunto.\"]", "[{\"id\":1,\"texto\":\"Llevar la planilla de costeo por producto terminada\",\"done\":false},{\"id\":2,\"texto\":\"Comparar márgenes con Los Crovas, Carpintero y Patagonia Retro\",\"done\":false},{\"id\":3,\"texto\":\"Fijar tope de comisión para terceros (20% a 25%)\",\"done\":false}]", ["cesia"]],
        ["vicotita-05", "vicotita", 5, "Diseño y estructura del catálogo B2B para prestadores", "ind", "Turismo", "2026-10-21", "09:30", "11:00", "programada", "Estructurar el catálogo comercial digital para presentar a hoteles, agencias y corporativos con mockups de personalización y co-branding.", "[\"¿Qué 6 productos insignia colocamos en el catálogo?\",\"¿Cómo explicamos los tiempos de producción (7 a 15 días) para evitar reclamos?\"]", "[\"Seleccionar fotos de alta calidad de los productos.\",\"Redactar las fichas técnicas y condiciones comerciales.\",\"Montar el PDF interactivo.\"]", "[{\"id\":1,\"texto\":\"Seleccionar las fotos definitivas de la línea de temporada\",\"done\":false},{\"id\":2,\"texto\":\"Redactar escalas de precios para 20, 50 y 100 unidades\",\"done\":false},{\"id\":3,\"texto\":\"Armar el PDF interactivo listo para enviar por WhatsApp y mail\",\"done\":false},{\"id\":4,\"texto\":\"Definir cláusula de seña del 50% y plazos de entrega\",\"done\":false}]", ["mariela","cesia"]],
        ["vicotita-06", "vicotita", 6, "Validación de prototipos y proto-armado de taller abierto", "ind", "Taller de Encuadernación (Majo)", "2026-10-29", "16:30", "18:00", "programada", "Reunión conjunta con ambas hermanas para revisar los prototipos de la Bitácora de Campo terminados y evaluar la viabilidad de la experiencia inmersiva de taller.", "[\"¿Cómo responde el diseño gráfico interior de la libreta?\",\"¿Es viable abrir el taller para 4 o 6 personas en temporadas especiales?\"]", "[\"Evaluar físicamente la bitácora terminada.\",\"Validar el circuito de serigrafía y estampado en vivo.\",\"Definir pautas del taller abierto de temporada.\"]", "[{\"id\":1,\"texto\":\"Revisar 3 bitácoras terminadas con encuadernación artesanal\",\"done\":false},{\"id\":2,\"texto\":\"Probar la experiencia de estampado en vivo con matriz doble\",\"done\":false},{\"id\":3,\"texto\":\"Redactar el guion de 1h30m para grupos reducidos\",\"done\":false},{\"id\":4,\"texto\":\"Establecer cupos máximos de 6 personas para octubre\",\"done\":false}]", ["cesia"]],
        ["vicotita-07", "vicotita", 7, "Rueda de contactos comerciales y colocación en hoteles", "ter", "Turismo", "2026-11-04", "09:30", "11:00", "programada", "Presentar el catálogo B2B a 5 establecimientos turísticos seleccionados de Esquel para concertar pedidos mayoristas de merchandising de autor.", "[\"¿Qué hoteles boutique y lodges de pesca muestran interés en co-brandear bitácoras o estuches?\",\"¿Qué pedidos de muestra se entregan?\"]", "[\"Enviar catálogo personalizado a los 5 establecimientos objetivo.\",\"Entregar muestras físicas con marbete narrativo.\",\"Realizar seguimiento de pedidos.\"]", "[{\"id\":1,\"texto\":\"Mapear 5 establecimientos objetivo de Esquel\",\"done\":false},{\"id\":2,\"texto\":\"Enviar el catálogo comercial con nota formal de presentación\",\"done\":false},{\"id\":3,\"texto\":\"Dejar muestras físicas con marbete en 2 hoteles boutique\",\"done\":false},{\"id\":4,\"texto\":\"Registrar devoluciones y solicitudes de cotización\",\"done\":false}]", ["mariela","cesia"]],
        ["vicotita-08", "vicotita", 8, "Distinción, resultados y rueda de negocios en Melipal", "cie", "Centro Cultural Melipal", "2026-11-19", "10:00", "13:00", "programada", "Cierre plenario y rueda comercial con el sector turístico comarcal. Presentación del producto ante agencias, prestadores y prensa.", "[\"¿Cuántos convenios comerciales de provisión formal se firman en la rueda de negocios?\"]", "[\"Cerrar al menos dos convenios de provisión con alojamientos o agencias.\",\"Exhibir la colección completa en el stand oficial.\"]", "[{\"id\":1,\"texto\":\"Confirmar asistencia de ambas socias al plenario\",\"done\":false},{\"id\":2,\"texto\":\"Montar stand de exhibición con marbetes y packaging terminado\",\"done\":false},{\"id\":3,\"texto\":\"Cerrar al menos un acuerdo comercial formal en la rueda\",\"done\":false}]", ["leandro","adria","mariela","francisco","agustina","cesia","noelia"]],
        ["carpint-01", "carpint", 1, "Diagnóstico en Taller de Barrio Estación y Relevamiento del Torno", "ter", "Taller Carpintero Esquel (Brown 1570, B° Estación)", "2026-09-16", "11:00", "12:30", "programada", "Visitar el taller hogareño de Maxi en calle Brown 1570. Relevar el torno de madera, las gubias, herramientas de lijado, acopio de troncos y tablones nobles (lenga, radal, ciprés). Evaluar el lay-out actual para definir la zona segura para visitantes (a 1,5 m de la bancada del torno).", "[\"¿Cuánto tiempo real te insume tornear un cuenco mediano desde el trozo en bruto hasta el lijado final?\",\"¿Qué trabajos pesados te obligan sí o sí a trasladar madera al CAPEC y cuánto pagás por el canon CAM?\",\"¿Cómo resolvés el frío y la lluvia en el patio durante el invierno para no frenar la producción?\"]", "[\"Relevar medidas y lay-out del taller para delimitar la zona de visita y zona segura del torno.\",\"Identificar las piezas con mayor demanda histórica y mayor margen de ganancia artesanal.\",\"Establecer el cronograma de trabajo conjunto y disponibilidad matutina de Maxi.\"]", "[{\"id\":1,\"texto\":\"Inspeccionar torno de madera, herramientas y stock de maderas nobles en taller\",\"done\":false},{\"id\":2,\"texto\":\"Medir distancias de seguridad y demarcar visualmente la zona de visitantes a 1,5 m\",\"done\":false},{\"id\":3,\"texto\":\"Listar los 4 productos candidatos a conformar la Línea Turística Estrella\",\"done\":false}]", ["mariela","cesia"]],
        ["carpint-02", "carpint", 2, "Estandarización de las 4 Piezas Estrella y Acabados Alimentarios", "ind", "Taller Carpintero Esquel", "2026-09-24", "16:30", "18:00", "programada", "Seleccionar y cerrar las 4 piezas definitivas de la línea turística (Cuenco Mediano, Mate Torneado con Sello, Plato de Asado y Cuchara Rústica). Estandarizar dimensiones, tiempos de torno, tipo de madera y protocolo de curado alimentario seguro con cera de abejas y aceite mineral.", "[\"¿Qué tratamiento o sellador usás actualmente para que los cuencos y mates no se rajen ni transmitan sabores extraños?\",\"¿Cuál es el costo unitario de lija, sellador y marca a fuego por pieza?\",\"¿Podemos garantizar un stock mínimo de 10 unidades por pieza para abastecer consignaciones iniciales?\"]", "[\"Cerrar la ficha técnica con dimensiones y tolerancias de cada una de las 4 piezas estrella.\",\"Validar la fórmula de curado artesanal inocuo y apto para alimentos calientes y fríos.\",\"Diseñar la etiqueta colgante de madera o papel kraft que certifique autenticidad y origen cordillerano.\"]", "[{\"id\":1,\"texto\":\"Definir medidas exactas de cuenco, mate, plato y cuchara rústica\",\"done\":false},{\"id\":2,\"texto\":\"Aprobar el protocolo de curado inocuo con cera de abejas virgen\",\"done\":false},{\"id\":3,\"texto\":\"Diseñar el boceto de etiqueta colgante con historia de Barrio Estación y cuidados de la madera\",\"done\":false}]", ["cesia"]],
        ["carpint-03", "carpint", 3, "Costeo Integral, Tiempos de Maquinado y Tarifario Mayorista/Minorista", "ind", "Oficinas de Turismo / LAB Esquel", "2026-09-30", "11:00", "12:30", "programada", "Construir la planilla de costeo paramétrico de las 4 piezas. Desglosar costo de pie de madera, canon de uso del CAPEC, desgaste de herramientas/lijas, cera, marca a fuego, y cuantificar la mano de obra calificada por hora de torno. Fijar precios sugeridos al público y precio mayorista para comercios (margen del 30-40% para el revendedor).", "[\"¿Cuántas piezas podés producir por semana sin descuidar pedidos de carpintería tradicional?\",\"¿A qué precio vendías antes tus piezas y qué margen real te quedaba tras comprar insumos?\",\"¿Qué porcentaje de comisión o descuento comercial resulta viable ofrecer a regionales y hoteles?\"]", "[\"Parametrizar el costo unitario real de cada pieza en planilla Excel/Drive.\",\"Establecer el precio de venta mayorista y el precio de venta sugerido al público (PVP).\",\"Fijar la política de reposición y plazos de pago para tiendas en consignación.\"]", "[{\"id\":1,\"texto\":\"Cargar la planilla de costos unitarios con amortización de herramientas y CAPEC\",\"done\":false},{\"id\":2,\"texto\":\"Emitir la lista de precios oficial mayorista y minorista de la Línea Turística\",\"done\":false},{\"id\":3,\"texto\":\"Redactar modelo de remito y acta de entrega en consignación a 15 días\",\"done\":false}]", ["mariela","cesia"]],
        ["carpint-04", "carpint", 4, "Guion Vivencial Taller Abierto en Barrio Estación y Protocolo de Seguridad", "ind", "Taller Carpintero Esquel", "2026-10-08", "16:30", "18:00", "programada", "Estructurar la experiencia vivencial turística para grupos reducidos (2 a 4 personas). Diseñar la secuencia: bienvenida con reseña del oficio y Barrio Estación, demostración de torneado en vivo, participación guiada del turista en lijado de su propia pieza, marcado a fuego y cierre con mateada campesina. Validar el protocolo de seguridad y zona restringida.", "[\"¿Qué sensaciones y anécdotas del oficio de carpintero querés transmitirle al visitante durante la demostración?\",\"¿En qué momento exacto de la pieza participa el turista para que sea una experiencia segura y sin riesgo de corte?\",\"¿Cómo articulamos con tu familia la preparación del mate y las tortas fritas para la bienvenida?\"]", "[\"Redactar el guion vivencial paso a paso de 60 a 75 minutos de duración.\",\"Formalizar el protocolo de bioseguridad y elementos de protección (antiparras obligatorias).\",\"Definir el valor de la entrada o ticket por persona que incluya la pieza personalizada de recuerdo.\"]", "[{\"id\":1,\"texto\":\"Redactar el guion de la experiencia Taller Abierto en Barrio Estación\",\"done\":false},{\"id\":2,\"texto\":\"Comprobar stock de antiparras de seguridad y cartelería de precaución en torno\",\"done\":false},{\"id\":3,\"texto\":\"Simular la secuencia de lijado participativo y marcado a fuego con el equipo técnico\",\"done\":false}]", ["cesia"]],
        ["carpint-05", "carpint", 5, "Producción Fotográfica 4K, Catálogo Digital y Piezas de Comunicación", "ter", "Taller Carpintero Esquel", "2026-10-21", "11:15", "12:45", "programada", "Sesión fotográfica y de video profesional 4K en el taller con iluminación natural y encuadres de virutas volando en el torno. Registrar las 4 piezas terminadas y la dinámica vivencial con el artesano. Armar el catálogo digital interactivo para envío a agencias receptivas y hotelería de alta gama.", "[\"¿Qué piezas y maderas tienen mejor veta y presencia visual para el plano detalle de fotografía?\",\"¿Cómo querés presentar tu historia personal en el texto de portada del catálogo digital?\",\"¿Qué canales de contacto directo (WhatsApp comercial, Instagram) vamos a vincular al catálogo?\"]", "[\"Generar un banco de 25 fotografías profesionales en alta resolución y clips cortos de torno en vivo.\",\"Maquetar el catálogo digital PDF de la Línea Turística con ficha técnica de cada madera noble.\",\"Configurar el perfil de Instagram y WhatsApp Business con catálogo integrado de productos.\"]", "[{\"id\":1,\"texto\":\"Realizar sesión fotográfica de piezas individuales y demostración en torno\",\"done\":false},{\"id\":2,\"texto\":\"Seleccionar las 15 mejores imágenes y redactar reseñas de cada producto\",\"done\":false},{\"id\":3,\"texto\":\"Generar el catálogo digital interactivo en formato PDF y enlace web\",\"done\":false}]", ["mariela","cesia","leandro"]],
        ["carpint-06", "carpint", 6, "Articulación CAPEC, Proyecto de Infraestructura y Rueda Comercial B2B", "ind", "CAPEC Esquel / Secretaría de Producción", "2026-10-27", "16:00", "17:30", "programada", "Reunión de trabajo con la coordinación del CAPEC (Paula Botto) y Producción. Presentar la formulación de proyecto para subsidio o microcrédito destinado al cerramiento térmico y techado definitivo del taller. Planificar la ronda de visitas a los primeros comercios céntricos y hoteles boutique para colocación en consignación.", "[\"¿Cuáles son los montos máximos y requisitos de la línea de financiamiento productivo vigente en CAPEC?\",\"¿Qué comercios de regionales y chocolaterías del centro tienen el perfil de cliente adecuado para estas piezas nobles?\",\"¿Qué volumen de stock de piezas estrella tenemos listo para dejar en consignación esta semana?\"]", "[\"Presentar el presupuesto de materiales para el cerramiento del taller ante la Secretaría de Producción.\",\"Visitar 3 comercios regionales de Esquel y presentar catálogo y muestras físicas de producto.\",\"Firmar acuerdos de consignación con remito oficial a 15 días con al menos 2 comercios.\"]", "[{\"id\":1,\"texto\":\"Entregar anteproyecto técnico y presupuesto de cerramiento del taller en CAPEC\",\"done\":false},{\"id\":2,\"texto\":\"Visitar comercios céntricos seleccionados con muestras físicas y catálogo en mano\",\"done\":false},{\"id\":3,\"texto\":\"Dejar stock inicial de 5 cuencos, 5 mates y 5 tablas en al menos 2 comercios adheridos\",\"done\":false}]", ["cesia"]],
        ["carpint-07", "carpint", 7, "Ensayo General de Taller Abierto (Fam Press y Validación en Campo)", "ter", "Taller Carpintero Esquel (Brown 1570)", "2026-11-04", "11:15", "12:45", "programada", "Simulacro completo de la experiencia vivencial con un grupo de prueba (informantes de la Secretaría de Turismo y guías invitados). Evaluar el manejo de tiempos, la claridad de la demostración en torno, la seguridad del lijado participativo, el impacto del mate con tortas fritas caseras y la venta espontánea de piezas adicionales.", "[\"¿Cómo se sintió Maxi al hablar y explicar frente a personas desconocidas mientras operaba el torno?\",\"¿El espacio de estacionamiento en calle Brown y el acceso peatonal al patio resultaron cómodos para los visitantes?\",\"¿Qué dudas o sugerencias plantearon los participantes durante la mateada final?\"]", "[\"Validar la duración real de la experiencia (meta: 60 minutos cronometrados sin desvíos).\",\"Testear la comprensión de normas de seguridad y la satisfacción del visitante al estampar su pieza a fuego.\",\"Ajustar detalles del guion verbal y del rincón de exhibición de piezas a la venta.\"]", "[{\"id\":1,\"texto\":\"Ejecutar el simulacro de la experiencia vivencial con 4 invitados externos\",\"done\":false},{\"id\":2,\"texto\":\"Recoger encuestas de feedback sobre seguridad, calidez y valor percibido del souvenir\",\"done\":false},{\"id\":3,\"texto\":\"Monitorear ventas de las primeras consignaciones en comercios céntricos y cobrar remitos cumplidos\",\"done\":false}]", ["mariela","cesia"]],
        ["carpint-08", "carpint", 8, "Distinción, resultados y rueda de negocios en Melipal", "cie", "Centro Cultural Melipal", "2026-11-19", "10:00", "13:00", "programada", "Participación protagónica en el Encuentro de Cierre y Ronda de Negocios de Esquel LAB. Montaje de mesa de exhibición de torneado y piezas de maderas nobles. Pitch de 3 minutos de Maxi presentando Carpintero Esquel: Artefactos con Alma de Bosque y Taller Abierto en Barrio Estación. Firma de acuerdos comerciales con prestadores turísticos y entrega del plan operativo post-incubación.", "[\"¿Qué balance arrojan las primeras ventas en consignación y qué producto tuvo mayor rotación?\",\"¿Cómo organizará Maxi su calendario semanal entre producción de taller, CAPEC y visitas turísticas agendadas?\",\"¿Qué apoyo adicional requerirá para la ejecución de la obra del taller cuando se apruebe el financiamiento?\"]", "[\"Exhibir la Línea Turística Estrella completa ante operadores turísticos, guías y autoridades municipales.\",\"Consolidar al menos 3 acuerdos de comercialización continua con hoteles y tiendas de diseño local.\",\"Entregar el informe de cierre de asistencia técnica y hoja de ruta productiva para la temporada 2026/2027.\"]", "[{\"id\":1,\"texto\":\"Armar stand con virutas de madera, torno fotográfico y las 4 piezas estrella terminadas\",\"done\":false},{\"id\":2,\"texto\":\"Exponer el pitch de 3 minutos ante el ecosistema turístico y comercial de Esquel\",\"done\":false},{\"id\":3,\"texto\":\"Firmar actas de compromiso comercial y balance de cobro de las primeras ventas\",\"done\":false}]", ["leandro","adria","mariela","francisco","agustina","cesia","noelia"]],
        ["corcho-01", "corcho", 1, "Relevamiento en terreno: taller barrial y entorno La Trochita", "ter", "Taller Los Sauces (Calle 44 Casa 28)", "2026-09-17", "14:00", "15:30", "programada", "Relevar el espacio físico del taller, layout de herramientas, rincón de recepción y mate, acceso desde la estación La Trochita y callejón hacia el cementerio. Probar el dulce casero y evaluar opciones de packaging.", "[\"¿Dónde ubicamos a los turistas y a los niños para que estén seguros sin riesgo en el taller?\",\"¿Cómo integramos la degustación del dulce casero en el espacio de bienvenida?\",\"¿Qué estado mecánico tiene la bicicleta de competición y qué herramientas tenemos para mostrar?\"]", "[\"Medir y delimitar el sector de visita en el taller.\",\"Fotografiar el taller y el acceso barrial.\",\"Relevar estado de la bicicleta y herramientas.\",\"Degustar el dulce casero y evaluar opciones de packaging.\"]", "[{\"id\":1,\"texto\":\"Medir el espacio disponible para recepción\",\"done\":false},{\"id\":2,\"texto\":\"Fotografiar puntos críticos de acceso y vías del tren\",\"done\":false},{\"id\":3,\"texto\":\"Relevar herramientas y elementos de seguridad en taller\",\"done\":false},{\"id\":4,\"texto\":\"Definir el rincón de mateada y degustación de dulces\",\"done\":false}]", ["leandro","agustina"]],
        ["corcho-02", "corcho", 2, "Arquitectura web y benchmarking internacional", "ind", "Turismo", "2026-10-01", "14:00", "15:30", "programada", "Revisar el material de referencias internacionales recopilado por la familia (webs de EE.UU., Europa, etc.), estructurar el árbol de contenidos de la página web y redactar el borrador del relato de vida de Corcho.", "[\"¿Qué secciones tendrá la web (Inicio, Historia de Corcho, Circuitos, Taller, Reservas)?\",\"¿Qué llamados a la acción priorizamos para que el turista reserve por WhatsApp?\"]", "[\"Recibir el documento borrador con la historia deportiva de Corcho.\",\"Seleccionar referencias de diseño y animaciones.\",\"Definir estructura de hosting, dominio y layout que programará Leandro.\"]", "[{\"id\":1,\"texto\":\"Revisar referencias web internacionales enviadas\",\"done\":false},{\"id\":2,\"texto\":\"Estructurar el árbol de navegación del sitio web\",\"done\":false},{\"id\":3,\"texto\":\"Redactar la biografía deportiva desde los 11 años\",\"done\":false},{\"id\":4,\"texto\":\"Configurar llamados a la acción para reservas\",\"done\":false}]", ["agustina"]],
        ["corcho-03", "corcho", 3, "Estrategia de flota puente, seguridad y normativa", "ind", "Turismo", "2026-10-06", "14:00", "15:30", "programada", "Definir la estrategia de provisión de bicicletas para la temporada de prueba, relevar costos de cascos homologados y encuadrar el seguro de turismo activo.", "[\"¿A qué bicicleterías o prestadores podemos acudir para un acuerdo puente de alquiler?\",\"¿Cuánto cuesta el seguro de accidentes personales por excursionista por día?\"]", "[\"Mapear 3 alternativas de provisión de 6 bicicletas.\",\"Cotizar póliza de seguro de turismo alternativo.\",\"Iniciar expediente de registro de prestador en la Subsecretaría de Turismo.\"]", "[{\"id\":1,\"texto\":\"Contactar a 2 bicicleterías locales para convenio puente\",\"done\":false},{\"id\":2,\"texto\":\"Cotizar kit de 8 cascos homologados de diversos talles\",\"done\":false},{\"id\":3,\"texto\":\"Pedir presupuesto a aseguradora para turismo activo\",\"done\":false},{\"id\":4,\"texto\":\"Armar borrador de ficha médica y deslinde de responsabilidad\",\"done\":false}]", ["leandro","agustina"]],
        ["corcho-04", "corcho", 4, "Canal, volumen y comercialización cruzada (Célula 4)", "ter", "Célula 4 (Melipal)", "2026-10-13", "14:00", "15:30", "programada", "Encuentro grupal de la Célula 4 (Canal y volumen). Analizar canales de venta, alianzas cruzadas entre prestadores de excursiones y agencias receptivas, y fijación de comisiones de intermediación.", "[\"¿Cómo puede Yamamori Travel o True Patagonia incluir las guiadas de Corcho en sus paquetes de destino?\",\"¿Qué sinergias hay entre la merienda de Haiku y el cicloturismo?\"]", "[\"Presentar la propuesta de Corcho Bikes a los colegas de célula.\",\"Analizar esquema de comisiones del 15% al 20%.\",\"Identificar derivaciones cruzadas de turistas.\"]", "[{\"id\":1,\"texto\":\"Llevar la propuesta resumida de los 2 circuitos\",\"done\":false},{\"id\":2,\"texto\":\"Acordar con al menos 1 agencia receptiva de la célula una salida de prueba\",\"done\":false},{\"id\":3,\"texto\":\"Validar el esquema de comisiones de intermediación\",\"done\":false}]", ["agustina"]],
        ["corcho-05", "corcho", 5, "Rodaje audiovisual profesional con dron y 4K", "ter", "La Trochita y Taller", "2026-10-20", "14:00", "15:30", "programada", "Filmar el material publicitario oficial con cámaras 4K y dron en vuelo rasante sobre las vías del tren La Trochita y tomas de oficio y detalle en el taller.", "[\"¿Cuáles son los ángulos más impactantes del pedaleo junto a los rieles históricos?\",\"¿Cómo capturamos la emoción y la maestría mecánica de Corcho en video?\"]", "[\"Filmar secuencia de Corcho pedaleando junto a las vías con seguimiento de dron.\",\"Realizar tomas macro de ajuste de rayos, piñones y grasa en el taller.\",\"Grabar mensaje de invitación a cámara.\"]", "[{\"id\":1,\"texto\":\"Coordinar con el camarógrafo y piloto de dron de Turismo\",\"done\":false},{\"id\":2,\"texto\":\"Preparar la bicicleta de competición impecable y ropa deportiva\",\"done\":false},{\"id\":3,\"texto\":\"Grabar tomas de taller, mates y herramientas\",\"done\":false},{\"id\":4,\"texto\":\"Hacer backup del material grabado en crudo\",\"done\":false}]", ["leandro","agustina"]],
        ["corcho-06", "corcho", 6, "Salida piloto y ensayo general de circuito familiar", "ind", "Taller y Mirador de las Vías", "2026-10-27", "14:00", "15:30", "programada", "Ejecutar la experiencia familiar completa en condiciones reales para cronometrar la clínica para niños, la merienda con mate y dulce para los adultos, y validar protocolos de seguridad.", "[\"¿Los niños comprendieron y disfrutaron la mecánica básica?\",\"¿Los padres sintieron que tuvieron un verdadero momento de descanso y relax?\",\"¿Cómo resultó el tiempo total?\"]", "[\"Cronometrar cada bloque de la experiencia.\",\"Evaluar el funcionamiento de las bicis y cascos.\",\"Recabar feedback honesto de la familia invitada.\",\"Ajustar detalles del guion.\"]", "[{\"id\":1,\"texto\":\"Convocar a una familia con 2 niños para la prueba\",\"done\":false},{\"id\":2,\"texto\":\"Probar el kit de cascos y señalización\",\"done\":false},{\"id\":3,\"texto\":\"Servir la merienda con dulce casero y mate cocido\",\"done\":false},{\"id\":4,\"texto\":\"Completar encuesta de satisfacción con los invitados\",\"done\":false}]", ["agustina"]],
        ["corcho-07", "corcho", 7, "Presentación web oficial, tarifario y ficha comercial", "ind", "Turismo", "2026-11-03", "14:00", "15:30", "programada", "Presentar el sitio web terminado y publicado online, validar el prototipo del souvenir (lapicero reciclado + dulce) y cerrar el tarifario final para el sector comercial.", "[\"¿Está operativo el botón de reserva directa por WhatsApp?\",\"¿El precio cubre todos los costos fijos y variables dejando margen de ganancia neto?\"]", "[\"Revisar la web en vivo en computadoras y celulares.\",\"Validar el prototipo del souvenir reciclado.\",\"Imprimir 10 fichas comerciales para distribuir en hoteles.\",\"Configurar catálogo de WhatsApp Business.\"]", "[{\"id\":1,\"texto\":\"Testear funcionamiento del sitio web y formularios\",\"done\":false},{\"id\":2,\"texto\":\"Aprobar el packaging del souvenir reciclado con dulce\",\"done\":false},{\"id\":3,\"texto\":\"Fijar precio por persona y paquete familiar\",\"done\":false},{\"id\":4,\"texto\":\"Imprimir 10 fichas comerciales para el sector receptivo\",\"done\":false}]", ["leandro","agustina"]],
        ["corcho-08", "corcho", 8, "Distinción, resultados y rueda de negocios en Melipal", "cie", "Centro Cultural Melipal", "2026-11-19", "10:00", "13:00", "programada", "Cierre plenario y rueda comercial con el sector turístico comarcal. Presentación del producto ante agencias, prestadores y prensa.", "[\"¿Qué convenios comerciales quedan cerrados para el verano 2027?\"]", "[\"Cerrar al menos dos convenios de derivación con agencias u hoteles.\",\"Presentar el sitio web y el video de dron en pantalla gigante.\"]", "[{\"id\":1,\"texto\":\"Confirmar asistencia al plenario con la familia\",\"done\":false},{\"id\":2,\"texto\":\"Montar stand con bici histórica, piezas recicladas y dulces\",\"done\":false},{\"id\":3,\"texto\":\"Cerrar al menos un convenio formal en la rueda de negocios\",\"done\":false}]", ["leandro","adria","mariela","francisco","agustina","cesia","noelia"]],
        ["retro-01", "retro", 1, "Diagnóstico en predio de cabañas y delimitación de acceso al museo", "ter", "Cabañas y Predio", "2026-09-23", "08:00", "09:15", "programada", "Recorrer el predio de cabañas de Paula Salvo. Evaluar físicamente la delimitación entre el alojamiento turístico y el galpón de exhibición de autos antiguos para garantizar privacidad a los huéspedes.", "[\"¿Qué vehículos están hoy en condiciones de rodar o en exhibición estática?\",\"¿Cómo se maneja hoy la llegada espontánea de visitantes al predio sin invadir las cabañas?\"]", "[\"Definir el circuito peatonal independiente de acceso.\",\"Inventariar los vehículos y piezas históricas prioritarias.\"]", "[{\"id\":1,\"texto\":\"Medir y delimitar el sendero de acceso independiente\",\"done\":false},{\"id\":2,\"texto\":\"Fotografiar los 6 vehículos clásicos principales\",\"done\":false},{\"id\":3,\"texto\":\"Acordar pautas de visitas con reserva previa\",\"done\":false}]", ["mariela","cesia"]],
        ["retro-02", "retro", 2, "Inventario museográfico y documentación de piezas", "ind", "Patagonia Retro", "2026-09-28", "15:30", "17:00", "programada", "Relevar fichas técnicas de los vehículos, año de fabricación, procedencia y anécdotas mecánicas para nutrir el relato de la visita guiada.", "[\"¿Qué anécdota singular tiene cada auto (ej: viajes, propietarios anteriores)?\",\"¿Qué material fotográfico de época se conserva?\"]", "[\"Completar el inventario de 6 autos y piezas de colección.\",\"Digitalizar fotos históricas.\"]", "[{\"id\":1,\"texto\":\"Completar fichas técnicas de cada auto\",\"done\":false},{\"id\":2,\"texto\":\"Recopilar anécdotas para el guion\",\"done\":false},{\"id\":3,\"texto\":\"Seleccionar fotos históricas para las cédulas\",\"done\":false}]", ["cesia"]],
        ["retro-03", "retro", 3, "Guion de visita guiada y cédulas explicativas", "ind", "Patagonia Retro", "2026-10-07", "08:00", "09:15", "programada", "Estructurar el guion de la visita guiada (45 minutos) y redactar los textos para las cartelas/cédulas museográficas frente a cada unidad.", "[\"¿Cómo estructuramos el recorrido cronológico de los autos?\",\"¿Qué formato tendrán las cédulas (acrílico, madera, chapa vintage)?\"]", "[\"Aprobar el guion definitivo de la visita guiada.\",\"Definir el diseño y contenido de las 6 cédulas explicativas.\"]", "[{\"id\":1,\"texto\":\"Redactar guion de visita de 45 minutos\",\"done\":false},{\"id\":2,\"texto\":\"Redactar textos de las 6 cédulas\",\"done\":false},{\"id\":3,\"texto\":\"Presupuestar cartelería en taller local\",\"done\":false}]", ["mariela","cesia"]],
        ["retro-04", "retro", 4, "Protocolo de seguridad y tarifario comercial", "ind", "Turismo", "2026-10-16", "16:00", "17:30", "programada", "Fijar el protocolo de ingreso (no tocar tableros delicados, perímetro de seguridad) y armar la matriz de costos y tarifas para visitantes y agencias.", "[\"¿Qué cupo máximo de personas por turno permite el galpón?\",\"¿Qué precio por persona fijamos y qué comisión dejamos a agencias y hoteles (20%)?\"]", "[\"Fijar tarifas de visita guiada individual y familiar.\",\"Redactar protocolo de seguridad para visitantes.\"]", "[{\"id\":1,\"texto\":\"Fijar tarifa al público y comisión a agencias\",\"done\":false},{\"id\":2,\"texto\":\"Definir cupo máximo de 10 personas por turno\",\"done\":false},{\"id\":3,\"texto\":\"Redactar cartel de normas de seguridad\",\"done\":false}]", ["cesia"]],
        ["retro-05", "retro", 5, "Visita guiada piloto con grupo reducido de huéspedes", "ter", "Predio Patagonia Retro", "2026-10-21", "08:00", "09:15", "programada", "Llevar adelante una visita piloto de prueba con 8 huéspedes de las cabañas o invitados locales. Cronometrar los tiempos y evaluar el impacto del relato.", "[\"¿En qué autos los visitantes se detienen más tiempo a hacer preguntas?\",\"¿Resulta claro el sendero delimitado desde el acceso?\"]", "[\"Ejecutar la visita guiada piloto de 45 minutos.\",\"Recoger encuestas de satisfacción.\"]", "[{\"id\":1,\"texto\":\"Guiar la visita piloto con 8 personas\",\"done\":false},{\"id\":2,\"texto\":\"Tomar registro fotográfico para redes\",\"done\":false},{\"id\":3,\"texto\":\"Levantar encuestas de retroalimentación\",\"done\":false}]", ["mariela","cesia"]],
        ["retro-06", "retro", 6, "Ajustes post-piloto y material de difusión", "ind", "Turismo", "2026-10-30", "16:00", "17:30", "programada", "Ajustar detalles del guion según la experiencia piloto. Armar la ficha digital de producto para enviar a agencias receptivas de Esquel y Trevelin.", "[\"¿Qué aspectos del relato conviene sintetizar o reforzar?\",\"¿Qué días fijos de visita semanal se van a ofrecer?\"]", "[\"Cerrar el catálogo digital de Patagonia Retro.\",\"Definir el calendario de días habilitados para visitas.\"]", "[{\"id\":1,\"texto\":\"Ajustar el guion de recorrido\",\"done\":false},{\"id\":2,\"texto\":\"Finalizar el folleto digital\",\"done\":false},{\"id\":3,\"texto\":\"Publicar horarios de visita en redes y cartel\",\"done\":false}]", ["cesia"]],
        ["retro-07", "retro", 7, "Articulación comercial con receptivos y pitch", "ind", "Turismo", "2026-11-04", "08:00", "09:15", "programada", "Cerrar acuerdos de comercialización con agencias de viajes receptivas para incluir el museo de autos en los city tours comarcales. Practicar el pitch de 3 minutos.", "[\"¿Qué agencias confirmaron interés en sumar la visita a su folletería de verano?\",\"¿Cómo se presentará la propuesta en la rueda de negocios de Melipal?\"]", "[\"Cerrar al menos 2 acuerdos con agencias locales.\",\"Entrenar el pitch para la rueda de negocios.\"]", "[{\"id\":1,\"texto\":\"Firmar acuerdos comerciales con agencias\",\"done\":false},{\"id\":2,\"texto\":\"Ensayar el pitch de 3 minutos\",\"done\":false},{\"id\":3,\"texto\":\"Preparar material y fotos para la mesa de Melipal\",\"done\":false}]", ["mariela","cesia"]],
        ["retro-08", "retro", 8, "Distinción, resultados y rueda de negocios en Melipal", "cie", "Centro Cultural Melipal", "2026-11-19", "10:00", "13:00", "programada", "Acto plenario final de la 1ª cohorte de Esquel LAB. Entrega de certificados, stand interactivo y vinculación formal con prestadores comarcales.", "[\"¿Qué convenios se firman durante la jornada?\"]", "[\"Cerrar acuerdos comerciales formales.\",\"Presentación pública del circuito turístico integrado.\"]", "[{\"id\":1,\"texto\":\"Montar mesa de exhibición\",\"done\":false},{\"id\":2,\"texto\":\"Exponer pitch ante autoridades y prestadores\",\"done\":false},{\"id\":3,\"texto\":\"Firmar acuerdos de comercialización\",\"done\":false}]", ["leandro","adria","mariela","francisco","agustina","cesia","noelia"]],
        ["margher-01", "margher", 1, "Diagnóstico integral en territorio: casita centenaria, colmenares y corrales", "ter", "Establecimiento Margherita (Ladera Sur del Nahuelpan)", "2026-09-17", "10:00", "12:30", "programada", "Visita a las 500 ha en la ladera sur del Cerro Nahuelpan (a 18 km de Esquel, límite con Trevelin). Inspección ocular de la casita centenaria de adobe y tejuelas de alerce, galería cubierta, sector de apiarios y potreros de asnos y ovinos de cabaña. Mapeo de senderos pedestres internos y evaluación del estado de accesos viales.", "[\"¿Qué capacidad máxima de carga simultánea toleran las instalaciones para mantener la intimidad campestre?\",\"¿Cómo organizamos el calendario para no entorpecer los ciclos reproductivos ovinos y de cosecha apícola?\",\"¿Qué mejoras menores de cartelería rústica y delimitación de senderos se requieren en el predio?\"]", "[\"Mapear el circuito físico: recepción en galería, senderos hacia apiarios, potreros de asnos y miradores.\",\"Definir el modelo de negocio: agroturismo de día y eventos especiales, preservando la casita como refugio estacional.\",\"Acordar el cronograma semanal de consultoría y roles operativos de Dante y su compañera.\"]", "[{\"id\":1,\"texto\":\"Inspeccionar casita de adobe, galería, apiario y corrales en la ladera sur\",\"done\":false},{\"id\":2,\"texto\":\"Relevar el estado de accesos viales y conectividad para los visitantes\",\"done\":false},{\"id\":3,\"texto\":\"Fijar el cronograma de 8 encuentros de consultoría técnica\",\"done\":false}]", ["adria","noelia"]],
        ["margher-02", "margher", 2, "Estandarización del Día de Campo, guion de apicultura y protocolo con asnos", "ter", "Establecimiento Margherita", "2026-10-01", "09:30", "12:00", "programada", "Cerrar la estructura pedagógica y el guion narrativo de la experiencia \"Día de Campo Margherita\" (3h 30min). Redactar las pautas de seguridad e higiene para la demostración apícola (uso de ahumador, trajes y cata de mieles), la interacción con los burritos mansos y el taller de amasado de tortas fritas en la galería. Fijación de cupos máximos (10 personas por turno).", "[\"¿Cuáles son los pasos clave del guion para que Dante transmita su pasión apícola de forma didáctica y segura?\",\"¿Cómo articulamos el amasado participativo con la anfitriona mientras se preparan las brasas en la parrilla?\",\"¿Qué elementos de protección y bioseguridad se dispondrán para los visitantes en el colmenar?\"]", "[\"Redactar la ficha técnica y guion interpretativo paso a paso del Día de Campo.\",\"Formalizar el protocolo de seguridad apícola y deslinde de responsabilidad civil en turismo rural.\",\"Ensayar la dinámica de recepción con mate y tortas fritas calientes en la galería.\"]", "[{\"id\":1,\"texto\":\"Aprobar el guion didáctico del Día de Campo y la demostración apícola\",\"done\":false},{\"id\":2,\"texto\":\"Verificar stock y condiciones de trajes apícolas y caretas para visitantes\",\"done\":false},{\"id\":3,\"texto\":\"Fijar la capacidad de carga (máx. 10 personas) y política de reservas previas de 24 hs\",\"done\":false}]", ["noelia"]],
        ["margher-03", "margher", 3, "Estructura de costos paramétricos, punto de equilibrio y tarifario dual B2C/B2B", "ind", "Melipal / Espacio LAB", "2026-10-08", "09:30", "12:00", "programada", "Construir la planilla paramétrica de costos de las experiencias (ingredientes gastronómicos, leña de monte, mantenimiento, seguros de turismo rural y honorarios). Establecer el \"Precio Único Oficial\" del establecimiento y estructurar el margen del 20% de comisión para agencias receptivas y conserjerías de hoteles de Esquel y Trevelin.", "[\"¿Cuál es el costo unitario por visitante y cuál es el punto de equilibrio mínimo para abrir la tranquera?\",\"¿Cómo aseguramos que las agencias vendan al mismo precio oficial sin recargos abusivos?\",\"¿Qué porcentaje de seña anticipada (50%) exigirá la plataforma web para congelar la reserva?\"]", "[\"Parametrizar los costos fijos y variables de la media jornada y jornada entera.\",\"Emitir la lista oficial de precios: público general, tarifa social residente y tarifa mayorista B2B.\",\"Diseñar la política de reservas, cancelaciones y reprogramaciones climáticas.\"]", "[{\"id\":1,\"texto\":\"Cargar la planilla de costos y márgenes de rentabilidad en Drive/Excel\",\"done\":false},{\"id\":2,\"texto\":\"Emitir el tarifario oficial unificado para agencias y hoteles boutique\",\"done\":false},{\"id\":3,\"texto\":\"Definir el protocolo de contingencia climática en caso de lluvias intensas\",\"done\":false}]", ["adria","noelia"]],
        ["margher-04", "margher", 4, "Preparación operativa de la Fiesta de la Esquila y logística gastronómica", "ter", "Establecimiento Margherita", "2026-10-15", "14:00", "16:00", "programada", "Planificar minuciosamente la realización del hito anual \"Fiesta de la Esquila & Asado de Cordero Patagónico\" en coincidencia con la temporada alta de Tulipanes en Trevelin. Coordinar la demostración en vivo de comparsa de esquila, clasificación de vellones, preparación del cordero al asador a la leña y venta de frascos de miel \"Oro de Esquel\" con packaging rústico.", "[\"¿Qué logística de compra y ovinos seleccionados se dispondrán para la jornada de esquila?\",\"¿Cómo se ambientará la galería y el patio para recibir cómodamente a los 15 comensales?\",\"¿Qué stock de frascos de miel fraccionada en CAPEC se destinará para venta en origen?\"]", "[\"Cerrar el cronograma minuto a minuto de la jornada de esquila y banquete.\",\"Verificar la logística del fuego, asadores, vajilla campesina y puestos de sombra.\",\"Diseñar la presentación rústica de los frascos de miel como souvenir conector.\"]", "[{\"id\":1,\"texto\":\"Aprobar el programa operativo de la Fiesta de la Esquila\",\"done\":false},{\"id\":2,\"texto\":\"Coordinar con la comparsa de esquila y el asador el horario de demostración\",\"done\":false},{\"id\":3,\"texto\":\"Disponer el stock de miel Oro de Esquel con la nueva etiqueta institucional\",\"done\":false}]", ["noelia"]],
        ["margher-05", "margher", 5, "Producción audiovisual 4K con dron y arquitectura de la web transaccional", "ter", "Establecimiento Margherita", "2026-10-22", "09:30", "12:30", "programada", "Jornada de producción fotográfica y audiovisual profesional financiada por el LAB (cámaras 4K y dron en la ladera sur del Nahuelpan). Registro aéreo de las 500 ha, tomas de Dante en el apiario con traje y ahumador con las cumbres de fondo, casita de adobe y tejuelas, burritos mansos y cocina al fuego. En paralelo, revisión técnica con Leandro Choi de la web transaccional y pasarela de reservas.", "[\"¿Cuáles son los ángulos aéreos más espectaculares de la ladera sur y la casita centenaria?\",\"¿Cómo estructurar la carga de datos del visitante en la web para automatizar la confirmación de turnos?\",\"¿Qué pasarela de pagos (Mercado Pago / transferencia) dejamos integrada para cobrar las señas?\"]", "[\"Completar el plan de rodaje con cámaras 4K y tomas de dron para cápsulas institucionales.\",\"Validar la interfaz y textos de la plataforma web desarrollada ad-honorem por Leandro.\",\"Capacitar a Dante y su compañera en la administración sencilla del panel de reservas.\"]", "[{\"id\":1,\"texto\":\"Rodar el material audiovisual 4K y banco de 30 fotografías profesionales\",\"done\":false},{\"id\":2,\"texto\":\"Aprobar el diseño y catálogo de la plataforma web transaccional\",\"done\":false},{\"id\":3,\"texto\":\"Configurar el canal de WhatsApp Business con respuestas rápidas y catálogo\",\"done\":false}]", ["adria","noelia","leandro"]],
        ["margher-06", "margher", 6, "Rueda comercial con agencias receptivas, hoteleros y sinergias de cohorte", "ind", "Secretaría de Turismo / Melipal", "2026-10-29", "14:00", "16:00", "programada", "Presentar formalmente la propuesta a las 4 agencias de turismo receptivo habilitadas de Esquel y Trevelin y conserjerías de hoteles boutique. Articular sinergias ecosistémicas: provisión de miel para el productor de hidromiel de la comarca, circuitos de cicloturismo de estancia con Corcho Bikes y meriendas cruzadas con Haiku Casa de Té.", "[\"¿Qué interés manifiestan las agencias en comercializar el Día de Campo y la Fiesta de la Esquila con comisión del 20%?\",\"¿Cómo articulamos la logística de traslados en combis o 4x4 para turistas sin movilidad propia?\",\"¿Qué acuerdos de provisión de miel y cera pura establecemos con emprendimientos de la cohorte?\"]", "[\"Reunirse con 3 agencias de viaje receptivas y 3 hoteles boutique de Esquel y Trevelin.\",\"Firmar al menos 2 convenios comerciales de derivación turística con comisiones formalizadas.\",\"Acordar una alianza de provisión de miel con el elaborador comarcal de hidromiel.\"]", "[{\"id\":1,\"texto\":\"Presentar el catálogo oficial a agencias receptivas y prestadores hoteleros\",\"done\":false},{\"id\":2,\"texto\":\"Firmar acuerdos de comercialización turística con tarifario mayorista unificado\",\"done\":false},{\"id\":3,\"texto\":\"Concretar la alianza estratégica de miel para hidromiel y cicloturismo\",\"done\":false}]", ["noelia"]],
        ["margher-07", "margher", 7, "Fam Tour vivencial con agencias receptivas, hoteleros y test de reservas web", "ter", "Establecimiento Margherita", "2026-11-05", "09:30", "12:00", "programada", "Simulacro vivencial real en el campo con 10 invitados estratégicos (titulares de agencias receptivas, recepcionistas de hoteles boutique y prensa turística). Prueba en vivo de la experiencia: recepción con mate y tortas fritas, visita al apiario y potrero de asnos, pizzas a la parrilla en la galería, degustación de miel y testeo del circuito de reservas web.", "[\"¿Cómo evaluaron los operadores turísticos el dinamismo del guion y la calidez del anfitrión?\",\"¿La duración de 3 horas y media resultó equilibrada y atractiva para la venta en mostrador?\",\"¿Qué sugerencias técnicas plantearon los recepcionistas de hotel para recomendar el lugar?\"]", "[\"Validar los tiempos operativos reales de la experiencia completa en condiciones simuladas.\",\"Fidelizar a los recepcionistas y agentes de viaje como promotores directos del establecimiento.\",\"Recoger encuestas de satisfacción para pulir detalles del servicio antes de la apertura estival.\"]", "[{\"id\":1,\"texto\":\"Ejecutar el Fam Tour con 10 participantes del sector turístico comarcal\",\"done\":false},{\"id\":2,\"texto\":\"Completar encuestas de evaluación sobre hospitalidad, guion y gastronomía\",\"done\":false},{\"id\":3,\"texto\":\"Ajustar detalles finales del servicio de mesa y cartelería informativa interna\",\"done\":false}]", ["adria","noelia"]],
        ["margher-08", "margher", 8, "Distinción, resultados y rueda de negocios en Melipal", "cie", "Centro Cultural Melipal", "2026-11-19", "10:00", "13:00", "programada", "Participación protagónica en el Encuentro de Cierre de Esquel LAB en el Centro Cultural Melipal. Montaje de mesa temática con frascos de miel Oro de Esquel, velas de cera, vellones de lana y fotos 4K del Nahuelpan. Presentación pública de la plataforma web transaccional. Pitch de 3 minutos de Dante Oliva y compañera ante autoridades y empresarios turísticos. Entrega del informe final de consultoría técnica.", "[\"¿Cuáles son las reservas confirmadas en la plataforma web para la temporada de verano?\",\"¿Cómo se organizará el calendario de Dante entre la zafra apícola y los días de campo turísticos?\",\"¿Qué pasos inmediatos se proyectan para el desarrollo del SUM rústico modular a futuro?\"]", "[\"Presentar públicamente la oferta consolidada de Agroturismo de Establecimiento Margherita.\",\"Consolidar acuerdos comerciales firmes con el sector receptivo comarcal para el verano.\",\"Entregar el informe final de consultoría técnica y cronograma de temporada alta 2026/2027.\"]", "[{\"id\":1,\"texto\":\"Montar stand interactivo con degustación de miel, fotos 4K y terminal web\",\"done\":false},{\"id\":2,\"texto\":\"Exponer el pitch de 3 minutos ante autoridades municipales, prestadores y medios\",\"done\":false},{\"id\":3,\"texto\":\"Firmar acuerdos comerciales formales y entrega de la hoja de ruta post-incubación\",\"done\":false}]", ["leandro","adria","mariela","francisco","agustina","cesia","noelia"]],
        ["lucero-01", "lucero", 1, "Diagnóstico integral en predio, relevamiento de corrales, compost y El Pinar", "ter", "Centro Integral Ecuestre Lucero (Ruta 259 km 25 / Los Cóndores)", "2026-09-16", "10:30", "12:30", "programada", "Visitar el predio en Ruta 259 km 25. Relevar el circuito de corrales de la granja educativa (chinchillas, ratas de laboratorio, cerdita Rita Uva, Pamperito de 35 años), la pista de monta, el recambio de suelo con compost orgánico de septiembre y la matera histórica alemana. Evaluar accesibilidad y capacidad de carga.", "[\"¿Qué capacidad de carga simultánea tienen los corrales para no estresar a los animales de rescate?\",\"¿Cómo organizamos los horarios turísticos (martes, miércoles y sábados) para no interferir con la docencia escolar de Sol ni con la equinoterapia de los viernes?\",\"¿Qué mejoras de señalética y senderos en El Pinar se requieren antes del inicio de temporada?\"]", "[\"Mapear el circuito físico de la visita a la granja y el sendero ecuestre por El Pinar.\",\"Relevar el ciclo de compostaje y mantenimiento de corrales para la experiencia pedagógica.\",\"Definir el cronograma semanal de atención: martes, miércoles y sábados de 10:00 a 17:00.\"]", "[{\"id\":1,\"texto\":\"Inspeccionar corrales, pista de monta, boyero perimetral y matera histórica\",\"done\":false},{\"id\":2,\"texto\":\"Diseñar el plano de zonificación: granja perimetral, pista de prueba y bosque El Pinar\",\"done\":false},{\"id\":3,\"texto\":\"Fijar los días y horarios fijos semanales para visitas turísticas regulares\",\"done\":false}]", ["adria","noelia"]],
        ["lucero-02", "lucero", 2, "Estandarización de 2 Experiencias, Prueba en Pista y Seguros Patagonia Broker", "ter", "Centro Ecuestre Lucero", "2026-09-29", "10:00", "12:00", "programada", "Cerrar la ficha técnica y guion de las 2 experiencias turísticas: 1) Granja Educativa & Saberes Vivos (75 min, sin contacto con boyero, historias de rescate y mateada) y 2) Bautismo Ecuestre & Encuentro con el Caballo (90 min, vínculo pie a tierra, cepillado, prueba en pista para evaluar la mano del jinete y paseo en El Pinar). Protocolizar el alta previa obligatoria de seguros con Patagonia Broker / Mercantil Andina.", "[\"¿Cuáles son los pasos etológicos en pista para evaluar al jinete y cuidar la boca del caballo antes de salir al bosque?\",\"¿Cómo diferenciamos los requerimientos de seguro entre la visita a la granja (interacción perimetral) y la actividad montada (póliza nominativa previa)?\",\"¿Qué elementos de protección (cascos homologados, polainas) se verificarán en cada turno?\"]", "[\"Redactar el guion didáctico paso a paso de la visita a la granja y el bautismo ecuestre.\",\"Formalizar el protocolo de prueba en pista obligatoria para resguardar el bienestar del animal.\",\"Estructurar el formulario digital de recolección de datos personales y médicos para el seguro.\"]", "[{\"id\":1,\"texto\":\"Aprobar el guion interpretativo de las 2 experiencias turísticas\",\"done\":false},{\"id\":2,\"texto\":\"Redactar el protocolo de prueba en pista y deslinde de responsabilidad civil\",\"done\":false},{\"id\":3,\"texto\":\"Validar el circuito administrativo de pólizas con Patagonia Broker / Mercantil Andina\",\"done\":false}]", ["noelia"]],
        ["lucero-03", "lucero", 3, "Estructura de costos forrajeros, amortización invernal y tarifario dual B2C/B2B", "ind", "LAB Esquel / Secretaría de Turismo", "2026-10-07", "10:30", "12:30", "programada", "Construir la planilla de costeo paramétrico. Desglosar forraje invernal (fardos de alfalfa y avena indispensables por falta de pasto en el pinar), veterinario, seguros y mantenimiento. Analizar el benchmark de mercado (Frisón Baroque $90.000 vs tarifas de Sol de $20.000/$40.000). Establecer un esquema tarifario dual: tarifa general para turistas y tarifa social para residentes de Esquel y Trevelin, más comisión del 20-25% para agencias EVyT.", "[\"¿Cuánto forraje comercial se consume durante los meses de cierre invernal y cómo se amortiza con la temporada estival?\",\"¿Cuál es el precio justo de mercado para reposicionar a Lucero sin perder accesibilidad?\",\"¿Qué porcentaje de comisión se asigna a las agencias receptivas de Esquel y Trevelin?\"]", "[\"Parametrizar el costo unitario de manutención de la manada y punto de equilibrio.\",\"Emitir la lista oficial de precios: tarifa turista general, tarifa social residente y tarifa mayorista B2B.\",\"Definir la política de reservas (50% de seña para congelar turno) y cancelaciones por mal tiempo.\"]", "[{\"id\":1,\"texto\":\"Cargar la planilla de costos forrajeros y amortización anual en Drive/Excel\",\"done\":false},{\"id\":2,\"texto\":\"Emitir la ficha tarifaria comercial dual (turista / residente / agencias)\",\"done\":false},{\"id\":3,\"texto\":\"Fijar el porcentaje de seña anticipada y protocolo de reprogramación climática\",\"done\":false}]", ["adria","noelia"]],
        ["lucero-04", "lucero", 4, "Desarrollo del Kit Pequeño Cuidador, Cuadernos de Historias y Merchandising", "ind", "Centro Ecuestre Lucero", "2026-10-13", "10:30", "12:30", "programada", "Prototipar el kit físico infantil Pequeño Cuidador de Animales / Guardián de Lucero (libreta de campo ilustrada, lápiz ecológico de madera, guía de huellas y cuidados, pin de guardián). Diseñar los cuadernos Historias de Lucero (el abuelo Toto Arrechea, Pamperito de 35 años, Rita Uva) y los paquetes de compost orgánico y semillas de la huerta como recuerdos sustentables.", "[\"¿Qué relatos del abuelo Toto y de los animales rescatados generan mayor conexión emocional y pedagógica con los chicos?\",\"¿Qué costo unitario de imprenta permite ofrecer el kit a un precio accesible y rentable?\",\"¿Cómo se ambientará el rincón de recepción y venta artesanal junto a la matera histórica?\"]", "[\"Cerrar el diseño gráfico y pedagógico del Kit del Pequeño Cuidador.\",\"Cotizar una primera tirada de 100 cuadernillos y 100 pins con proveedores comarcales.\",\"Diseñar el packaging sustentable de los sobres de compost de septiembre y semillas.\"]", "[{\"id\":1,\"texto\":\"Aprobar el boceto de la libreta de actividades del Pequeño Cuidador\",\"done\":false},{\"id\":2,\"texto\":\"Diseñar los stickers y empaques de compost orgánico y semillas de granja\",\"done\":false},{\"id\":3,\"texto\":\"Definir el precio de venta del kit y de los recuerdos en la matera histórica\",\"done\":false}]", ["noelia"]],
        ["lucero-05", "lucero", 5, "Producción audiovisual 4K con dron y arquitectura de la plataforma web", "ter", "Centro Ecuestre Lucero", "2026-10-20", "10:00", "12:00", "programada", "Jornada de producción audiovisual profesional financiada por el LAB (cámaras 4K y dron en El Pinar) para rodar 3 cápsulas: 1) Raíces e Historia familiar (Sol Arrechea y el legado de Toto); 2) Bienestar y Conexión en El Pinar (tomas aéreas del bosque y monta consciente); y 3) Guardianes de Lucero (niños y animales de rescate). En paralelo, revisión técnica con Leandro Choi de la arquitectura de la plataforma web transaccional para reservas y seguros.", "[\"¿Cuáles son las locaciones y ángulos aéreos más impactantes de El Pinar y los corrales para el vuelo del dron?\",\"¿Cómo estructurar la carga de datos del visitante en la web para automatizar la planilla de seguros antes de su llegada?\",\"¿Qué pasarela de pagos (Mercado Pago / transferencia) dejamos integrada para cobrar las señas?\"]", "[\"Rodar el material audiovisual 4K y tomas con dron para las 3 cápsulas promocionales.\",\"Validar la interfaz de reservas online: selección de días (mar/mié/sáb), turnos, cupos y formulario médico.\",\"Generar un banco fotográfico de alta resolución para la web y redes sociales.\"]", "[{\"id\":1,\"texto\":\"Completar el plan de rodaje con cámaras 4K y tomas aéreas de dron\",\"done\":false},{\"id\":2,\"texto\":\"Aprobar el wireframe funcional de la plataforma web transaccional diseñada por Leandro\",\"done\":false},{\"id\":3,\"texto\":\"Seleccionar las tomas fotográficas para el catálogo digital y encabezados web\",\"done\":false}]", ["adria","noelia","leandro"]],
        ["lucero-06", "lucero", 6, "Rueda comercial B2B con agencias de Esquel/Trevelin y sinergia con Haiku", "ind", "Oficinas de Turismo / Centro Cultural Melipal", "2026-11-03", "10:00", "12:00", "programada", "Presentar formalmente la propuesta a las principales agencias receptivas de Esquel y Trevelin, destacando la ubicación estratégica sobre Ruta 259. Coordinar sinergias con prestadores de la cohorte: meriendas y retiros holísticos combinados en El Pinar junto a Haiku Casa de Té y True Patagonia. Planificar la fecha y articulación de la feria comunitaria El Paseo del Pinar.", "[\"¿Qué interés manifiestan las agencias de Esquel y Trevelin en sumar una parada rural/ecuestre camino al Valle de los Tulipanes y Molino Nant Fach?\",\"¿Cómo coordinamos con Haiku la provisión de blends de té y vajilla para retiros en el bosque?\",\"¿Qué cronograma establecemos para la próxima edición de El Paseo del Pinar en primavera?\"]", "[\"Presentar el catálogo oficial a 3 agencias receptivas habilitadas de la Comarca.\",\"Firmar al menos 2 convenios de comercialización y derivación turística con agencias locales.\",\"Acordar la realización de una experiencia piloto combinada Lucero + Haiku Casa de Té.\"]", "[{\"id\":1,\"texto\":\"Reunión comercial con agencias receptivas seleccionadas con catálogo en mano\",\"done\":false},{\"id\":2,\"texto\":\"Firmar acuerdos de comercialización turística con tarifario mayorista\",\"done\":false},{\"id\":3,\"texto\":\"Diseñar la propuesta del retiro holístico combinado en El Pinar con Haiku\",\"done\":false}]", ["noelia"]],
        ["lucero-07", "lucero", 7, "Fam Tour en terreno con informantes turísticos y test de la plataforma web", "ter", "Centro Ecuestre Lucero", "2026-11-04", "10:30", "12:30", "programada", "Simulacro vivencial en campo con un grupo de prueba (informantes de Turismo de Esquel y Trevelin, guías y prestadores de la cohorte). Prueba en vivo del sistema de reservas web: registro previo de participantes y alta de seguros. Recorrido guiado completo por corrales, bautismo ecuestre con prueba de pista, entrega del Kit del Pequeño Cuidador y merienda campesina en la matera histórica.", "[\"¿El proceso de reserva web y carga previa de datos para el seguro resultó ágil y claro para el usuario?\",\"¿Cómo valoraron los informantes turísticos la calidez del relato y el bienestar visible de los animales?\",\"¿Qué ajustes finales sugieren en cuanto a tiempos de recorrido y cartelería informativa?\"]", "[\"Validar el funcionamiento operativo de la plataforma web y el alta de seguros en un caso real.\",\"Cronometrar los tiempos de las experiencias para asegurar puntualidad entre turnos.\",\"Recoger devoluciones técnicas de los informantes turísticos para su recomendación en mostrador.\"]", "[{\"id\":1,\"texto\":\"Ejecutar el Fam Tour con 10 informantes y prestadores invitados\",\"done\":false},{\"id\":2,\"texto\":\"Comprobar el circuito digital de reserva, confirmación y alta de póliza\",\"done\":false},{\"id\":3,\"texto\":\"Completar encuestas de satisfacción sobre seguridad, hospitalidad y contenido didáctico\",\"done\":false}]", ["adria","noelia"]],
        ["lucero-08", "lucero", 8, "Distinción, resultados y rueda de negocios en Melipal", "cie", "Centro Cultural Melipal", "2026-11-19", "10:00", "13:00", "programada", "Participación protagónica en el Encuentro de Cierre de Esquel LAB. Montaje de mesa temática de Centro Ecuestre Lucero con exhibición de los kits de Pequeño Cuidador, frascos de compost orgánico, fotos de El Pinar y terminal interactiva con la plataforma web desarrollada por Leandro Choi. Pitch de 3 minutos de Sol Arrechea presentando Lucero: Bienestar, Arraigo Familiar y Conexión con la Manada. Firma de acuerdos comerciales y entrega de la hoja de ruta post-LAB.", "[\"¿Cuáles son los resultados de reservas generadas durante los primeros días de la plataforma web?\",\"¿Cómo queda planificado el balance operativo de Sol para la temporada alta de verano 2026/2027?\",\"¿Qué pasos inmediatos se proyectan para la postulación a líneas de financiamiento municipal y provincial?\"]", "[\"Presentar públicamente la plataforma web transaccional y las cápsulas audiovisuales 4K.\",\"Consolidar acuerdos comerciales firmes con agencias receptivas y alojamientos de la Comarca.\",\"Entregar el plan operativo de consultoría post-incubación y cronograma de temporada alta.\"]", "[{\"id\":1,\"texto\":\"Montar el stand interactivo con material de granja, kits infantiles y navegación web\",\"done\":false},{\"id\":2,\"texto\":\"Exponer el pitch de 3 minutos ante autoridades municipales, prestadores y medios\",\"done\":false},{\"id\":3,\"texto\":\"Firmar acuerdos de comercialización formal y entrega de la hoja de ruta 2026/2027\",\"done\":false}]", ["leandro","adria","mariela","francisco","agustina","cesia","noelia"]],
        ["sabor-01", "sabor", 1, "Diagnóstico integral en Casa de Piedra, sendero Huella del Cóndor y sanitarios", "ter", "Casa de Piedra (Comunidad Nahuelpan)", "2026-09-21", "10:00", "12:30", "programada", "Visita a la Comunidad Nahuelpan. Inspección ocular de Casa de Piedra (antigua escuela comunitaria recuperada), sector de cocina, corrales de gallinas y sendero La Huella del Cóndor. Relevamiento técnico del estado de los baños: verificación de la cámara séptica y pozo ciego ya ejecutados, y detalle de los materiales faltantes (cerámicos, artefactos, grifería y pintura) para su terminación.", "[\"¿Cuáles son los costos y tiempos exactos para finalizar los baños antes del inicio de la temporada alta?\",\"¿Cómo delimitamos el sector de corrales avícolas con pallets y postes para que el turista observe sin invadir la zona productiva?\",\"¿Qué disponibilidad horaria tienen Lauriano y Yanina para establecer días y turnos fijos de recepción turística?\"]", "[\"Mapear el circuito peatonal: recepción en Casa de Piedra, ascenso por La Huella del Cóndor y regreso al salón.\",\"Elaborar el cómputo de materiales y presupuesto necesario para la terminación de los sanitarios.\",\"Definir el cronograma semanal de trabajo conjunto y roles de Lauriano y Yanina.\"]", "[{\"id\":1,\"texto\":\"Inspeccionar Casa de Piedra, cocina, corrales avícolas y sendero\",\"done\":false},{\"id\":2,\"texto\":\"Relevar estado de obra civil de los sanitarios y confeccionar listado de materiales faltantes\",\"done\":false},{\"id\":3,\"texto\":\"Acordar el calendario de las 8 semanas de incubación con el equipo de Célula 3\",\"done\":false}]", ["adria","francisco"]],
        ["sabor-02", "sabor", 2, "Estandarización del taller de amasado, protocolo de bienestar animal y guion del agua", "ter", "Casa de Piedra (Comunidad Nahuelpan)", "2026-10-05", "14:30", "16:30", "programada", "Cerrar la estructura pedagógica de la experiencia \"Sendero La Huella del Cóndor & Taller de Amasado Comunitario\". Empoderar a Nora Yanina Nahuelpan en la conducción del momento de panificados. Formalizar el protocolo de bienestar animal (erradicación total de prácticas invasivas como descolada o castraciones, priorizando la observación de la Gallina Mapuche y la incubadora comunitaria de 1.000 huevos). Redactar el guion interpretativo de la vertiente y el ritual de respeto al agua.", "[\"¿Cómo estructuramos el taller de amasado de Yanina para que sea dinámico, participativo y se integre con los tiempos del leudado y horneado?\",\"¿Qué reglas de interacción y distanciamiento con las aves de corral se explicarán a los visitantes antes de entrar al sendero?\",\"¿Cómo transmitir el significado ancestral del ritual del agua de forma pedagógica y respetuosa para todo público?\"]", "[\"Redactar la ficha técnica y guion paso a paso de la experiencia del sendero y amasado.\",\"Aprobar el protocolo de bienestar animal y pautas de visita responsable a corrales.\",\"Ensayar con Yanina la bienvenida y el taller participativo de masas campesinas.\"]", "[{\"id\":1,\"texto\":\"Validar el guion didáctico del taller de panificados con Yanina\",\"done\":false},{\"id\":2,\"texto\":\"Redactar el protocolo de bienestar animal y reglas de comportamiento para visitantes\",\"done\":false},{\"id\":3,\"texto\":\"Fijar el cupo máximo por turno (hasta 15 personas) para preservar la intimidad comunitaria\",\"done\":false}]", ["francisco"]],
        ["sabor-03", "sabor", 3, "Costeo paramétrico, tarifario dual B2C/B2B y expediente de subsidio sanitario", "ind", "Oficinas LAB / Secretaría de Turismo de Esquel", "2026-10-13", "10:00", "12:00", "programada", "Construir la planilla paramétrica de costos de las experiencias y productos. Desglosar insumos de panificación, leña seca, mantenimiento de Casa de Piedra y honorarios de guías/cocineros. Establecer un esquema tarifario dual: tarifa general para turistas y tarifa social comunitaria para residentes de Esquel y Trevelin, más 20-25% de comisión para agencias EVyT. Formulación técnica del pedido de financiamiento ante Producción/CAPEC (Paula Botto) para los sanitarios.", "[\"¿Cuál es el costo unitario por visitante en la merienda campesina y cuál es el punto de equilibrio mínimo por grupo?\",\"¿Qué precios fijamos para las agencias de turismo receptivo para que resulte un producto atractivo en sus paquetes?\",\"¿Qué línea de crédito o subsidio municipal/provincial se adapta mejor a la culminación de los baños?\"]", "[\"Parametrizar los costos operativos y punto de equilibrio de la merienda y el sendero.\",\"Emitir la lista oficial de precios: público general, residentes comarcales y agencias de viaje.\",\"Cerrar el documento de solicitud de fondos para la terminación de la obra sanitaria.\"]", "[{\"id\":1,\"texto\":\"Cargar la planilla de costos y márgenes de rentabilidad en Drive/Excel\",\"done\":false},{\"id\":2,\"texto\":\"Emitir el tarifario oficial minorista y mayorista (B2C y B2B)\",\"done\":false},{\"id\":3,\"texto\":\"Presentar el expediente de apoyo financiero ante la Secretaría de Producción\",\"done\":false}]", ["adria","francisco"]],
        ["sabor-04", "sabor", 4, "Logística de ramas de Maqui (Parques Nacionales), Curanto mensual y tazas identitarias", "ind", "Oficinas LAB / Melipal", "2026-10-19", "14:30", "16:30", "programada", "Hacer seguimiento de la nota oficial enviada a Parques Nacionales por indicación del Intendente Matías Taccetta autorizando al poblador Paulo Rosales la extracción sustentable de 5 m³ de ramas de maqui en Los Alerces. Protocolizar el manual operativo y de seguridad del \"Curanto de Nahuelpan\" (fuego, piedras calientes, técnica de tapado y tiempos de cocción). Cotizar y encargar la primera partida de tazas enlosadas con el logo institucional de Sabor Mapuche para las meriendas.", "[\"¿Cuál es el estado de la autorización de Parques Nacionales y la coordinación logística con Paulo Rosales?\",\"¿Qué calendario fijo mensual de curantos se establecerá para generar previsibilidad en agencias y público?\",\"¿Qué costo y plazos de entrega maneja el proveedor de las tazas enlosadas serigrafiadas?\"]", "[\"Monitorear la resolución administrativa de Parques Nacionales sobre el maqui.\",\"Estandarizar la receta, gramaje y procedimiento del Curanto al Hoyo de Nahuelpan.\",\"Aprobar el diseño y mandar a producción la primera tirada de tazas de losa institucionales.\"]", "[{\"id\":1,\"texto\":\"Verificar avance del permiso de recolección de maqui con la Intendencia de Parques\",\"done\":false},{\"id\":2,\"texto\":\"Redactar el manual técnico y de bioseguridad del Curanto tradicional\",\"done\":false},{\"id\":3,\"texto\":\"Aprobar la muestra gráfica de las tazas enlosadas serigrafiadas\",\"done\":false}]", ["francisco"]],
        ["sabor-05", "sabor", 5, "Producción audiovisual de microvideos (15s), fotografía 4K y arquitectura web", "ter", "Casa de Piedra y Sendero Huella del Cóndor", "2026-10-26", "10:00", "12:30", "programada", "Jornada de producción de contenidos en Casa de Piedra y sendero. Rodaje de una serie de 5 microvideos dinámicos de 15 segundos para reels e Instagram (técnica de calentamiento de piedras, encendido del fuego, atado de cordero, amasado participativo con Yanina y ritual en la vertiente). Sesión de 30 fotos 4K de alta calidad de productos gourmet, huevos celestes y paisaje. Revisión técnica con Leandro Choi de la arquitectura de la plataforma web sabormapuche.com.ar.", "[\"¿Qué tomas y detalles transmiten con mayor autenticidad la mística de la cocina a leña y la calidez del hogar?\",\"¿Cómo organizamos la tienda web para despachar sales, merkén y alfajores a nivel nacional?\",\"¿Qué pasarela de pagos y sistema de confirmación de turnos dejamos integrado en la plataforma web?\"]", "[\"Completar el plan de rodaje de los 5 microvideos y banco de 30 imágenes profesionales.\",\"Validar la interfaz y navegación de la plataforma web desarrollada por Leandro Choi.\",\"Entrenar a Lauriano y Yanina en la administración del panel de control de reservas y tienda online.\"]", "[{\"id\":1,\"texto\":\"Rodar los 5 microvideos de 15 segundos y seleccionar las 15 mejores fotografías 4K\",\"done\":false},{\"id\":2,\"texto\":\"Aprobar la estructura funcional y catálogo de la plataforma web sabormapuche.com.ar\",\"done\":false},{\"id\":3,\"texto\":\"Configurar el botón de pago y canal directo de WhatsApp Business\",\"done\":false}]", ["adria","francisco","leandro"]],
        ["sabor-06", "sabor", 6, "Rueda comercial B2B con agencias receptivas, La Trochita y sinergias de cohorte", "ind", "Secretaría de Turismo / Melipal", "2026-11-02", "14:30", "16:30", "programada", "Presentar formalmente el catálogo de experiencias y tarifario a tres agencias receptivas habilitadas de Esquel y Trevelin. Coordinar la articulación operativa con los servicios regulares del Viejo Expreso Patagónico La Trochita para recibir contingentes en Casa de Piedra tras el arribo a la estación Nahuelpan. Planificar sinergias de cohorte: articulación de circuitos culturales con \"El Arroyo Que Nos Ve Crecer...\" (Marcelo Troiano) y meriendas campesinas combinadas.", "[\"¿Qué interés y receptividad muestran las agencias en ofrecer el curanto mensual y el sendero como excursión fija?\",\"¿Cómo coordinamos los traslados desde la estación del tren hacia Casa de Piedra en los días de viaje?\",\"¿Qué acuerdos de reciprocidad podemos establecer con otros prestadores de la comarca?\"]", "[\"Reunirse con 3 agencias de viaje receptivas y entregarles material comercial y muestras de productos.\",\"Firmar al menos 2 acuerdos marco de comercialización y derivación turística.\",\"Establecer el protocolo de recepción de pasajeros del tren con las autoridades de La Trochita.\"]", "[{\"id\":1,\"texto\":\"Presentar el catálogo comercial en agencias receptivas de Esquel y Trevelin\",\"done\":false},{\"id\":2,\"texto\":\"Firmar acuerdos de comercialización turística con agencias locales\",\"done\":false},{\"id\":3,\"texto\":\"Acordar la coordinación operativa con los horarios de La Trochita\",\"done\":false}]", ["francisco"]],
        ["sabor-07", "sabor", 7, "Fam Tour vivencial en Casa de Piedra con informantes turísticos y test de la web", "ter", "Casa de Piedra (Comunidad Nahuelpan)", "2026-11-09", "10:00", "12:30", "programada", "Simulacro vivencial completo con 12 invitados especiales (informantes de las Secretarías de Turismo de Esquel y Trevelin, guías del Parque y prestadores de la cohorte). Prueba en vivo del sistema de reservas web. Recepción y bienvenida protocolar a cargo de Nora Yanina Nahuelpan, taller de amasado participativo, caminata por La Huella del Cóndor hasta la vertiente, visita guiada al corral de Gallinas Mapuches y merienda comunitaria en Casa de Piedra con las tazas institucionales.", "[\"¿El proceso de reserva digital y confirmación previa resultó fluido e intuitivo para los usuarios?\",\"¿Cómo respondieron los informantes turísticos a la conducción de Yanina en el taller de panificados?\",\"¿Qué devoluciones técnicas surgieron respecto a la señalización del sendero y los tiempos del recorrido?\"]", "[\"Validar los tiempos operativos reales de la experiencia completa en condiciones simuladas.\",\"Consolidar la seguridad y liderazgo de Yanina al frente de la conducción de contingentes.\",\"Recoger encuestas de satisfacción y sugerencias de mejora de informantes y guías turísticos.\"]", "[{\"id\":1,\"texto\":\"Ejecutar el Fam Tour con 12 participantes del sector turístico comarcal\",\"done\":false},{\"id\":2,\"texto\":\"Completar encuestas de evaluación técnica sobre hospitalidad, guion y tiempos\",\"done\":false},{\"id\":3,\"texto\":\"Ajustar detalles finales de señalética y servicio de merienda antes del lanzamiento\",\"done\":false}]", ["adria","francisco"]],
        ["sabor-08", "sabor", 8, "Distinción, resultados y rueda de negocios en Melipal", "cie", "Centro Cultural Melipal", "2026-11-19", "10:00", "13:00", "programada", "Participación protagónica en el Encuentro de Cierre de Esquel LAB. Montaje de mesa temática con productos gourmet, tazas enlosadas, huevos celestes y frascos de sales de la abuela. Presentación en vivo de la plataforma web sabormapuche.com.ar. Pitch institucional de 3 minutos co-conducido por Nora Yanina Nahuelpan y Lauriano Ríos ante autoridades municipales, prestadores y prensa. Anuncio oficial de la 6ª edición del Festival Sabor Mapuche y firma de convenios comerciales.", "[\"¿Qué impacto y visibilidad generó la presentación conjunta de Yanina y Lauriano en la comunidad turística?\",\"¿Cuáles son las reservas confirmadas en la plataforma web para el verano 2026/2027?\",\"¿Qué pasos inmediatos seguirán para la organización y sponsoreo de la 6ª edición del festival en noviembre?\"]", "[\"Exhibir la oferta consolidada de turismo rural comunitario ante autoridades y medios de comunicación.\",\"Consolidar convenios comerciales formales con agencias receptivas y comercios regionales.\",\"Entregar el informe final de consultoría técnica y plan de acción para la temporada estival.\"]", "[{\"id\":1,\"texto\":\"Montar stand interactivo con degustación de productos, tazas y terminal web\",\"done\":false},{\"id\":2,\"texto\":\"Exponer el pitch de 3 minutos co-liderado por Yanina y Lauriano\",\"done\":false},{\"id\":3,\"texto\":\"Firmar acuerdos de comercialización formal y entrega de la hoja de ruta 2026/2027\",\"done\":false}]", ["leandro","adria","mariela","francisco","agustina","cesia","noelia"]],
        ["laberin-01", "laberin", 1, "Relevamiento en terreno: replanteo, suelo y punto cero del laberinto", "ter", "Chacra Austin (Ruta 259 km 4)", "2026-09-28", "09:30", "12:00", "programada", "Relevar el terreno destinado al laberinto, verificar la perforación de agua, estado del camino de servidumbre y platea del salón de eventos. Fijar el punto cero de replanteo.", "[\"¿Dónde fijamos el punto central de replanteo del laberinto?\",\"¿Cómo resolvemos la curva de la máquina vial que invadió la parcela?\",\"¿Qué presión y caudal entrega la bomba de agua de la perforación?\"]", "[\"Medir con cinta y GPS el perímetro de las 2 hectáreas.\",\"Fotografiar el suelo, platea y puntos de acceso.\",\"Probar caudal de la perforación.\",\"Tomar 4 muestras de suelo para envío a análisis.\"]", "[{\"id\":1,\"texto\":\"Medir perímetro del predio asignado\",\"done\":false},{\"id\":2,\"texto\":\"Verificar caudal de la perforación de agua\",\"done\":false},{\"id\":3,\"texto\":\"Fotografiar la platea del salón de eventos\",\"done\":false},{\"id\":4,\"texto\":\"Extraer 4 muestras de suelo para análisis agronómico\",\"done\":false}]", ["adria","noelia"]],
        ["laberin-02", "laberin", 2, "Modelo agronómico: suelo, enmiendas y vivero de esquejes", "ind", "Turismo", "2026-09-23", "14:30", "16:30", "programada", "Analizar los resultados del suelo, estructurar el plan de enmienda con abono de oveja y diseñar el módulo de multiplicación por esquejes de ligustro.", "[\"¿Cuántas camionadas de tierra negra y abono se necesitan para la franja de plantación?\",\"¿Cómo organizamos la recolección y estacado de 4.000 esquejes de ligustro?\"]", "[\"Revisar informe preliminar de suelo.\",\"Diseñar el bancal del vivero de esquejes.\",\"Cotizar mangueras de goteo y goteros autocompensantes.\",\"Planificar la parcela testigo.\"]", "[{\"id\":1,\"texto\":\"Calcular volumen de abono de oveja necesario\",\"done\":false},{\"id\":2,\"texto\":\"Diseñar módulo de vivero para 4.000 esquejes\",\"done\":false},{\"id\":3,\"texto\":\"Cotizar sistema de riego por goteo\",\"done\":false},{\"id\":4,\"texto\":\"Definir protocolo de enraizante natural de sauce\",\"done\":false}]", ["noelia"]],
        ["laberin-03", "laberin", 3, "Geometría del laberinto y consulta técnica paisajística", "ind", "Turismo", "2026-10-05", "09:30", "12:00", "programada", "Definir la traza geométrica final del laberinto (ancho de senderos, radio exterior, plazoleta central) y calcular metros lineales de cerco vivo.", "[\"¿Qué distancia exacta entre plantas garantiza cierre tupido sin asfixia de raíces?\",\"¿Qué elementos lúdicos o miradores incluimos en el centro?\"]", "[\"Dibujar el plano del laberinto a escala.\",\"Calcular cantidad exacta de plantas necesarias.\",\"Dimensionar el circuito hidráulico de riego.\",\"Fijar puntos de mojones en plano.\"]", "[{\"id\":1,\"texto\":\"Definir ancho de senderos (1,80 a 2 m)\",\"done\":false},{\"id\":2,\"texto\":\"Calcular metros lineales totales de cerco vivo\",\"done\":false},{\"id\":3,\"texto\":\"Fijar plazoleta central con mirador panorámico\",\"done\":false},{\"id\":4,\"texto\":\"Establecer puntos de bifurcación y caminos ciegos\",\"done\":false}]", ["adria","noelia"]],
        ["laberin-04", "laberin", 4, "Predios rurales y alianzas de corredor (Célula 2)", "ind", "Célula 2 (Melipal)", "2026-10-14", "14:00", "16:00", "programada", "Encuentro grupal de la Célula 2 (Campo y gran superficie). Poner en común costos de infraestructura rural, manejo de visitantes en chacras, alianzas de derivación mutua en la Ruta 259 y seguros colectivos.", "[\"¿Cómo conectamos el laberinto con las cabalgatas de Lucero o el tambo de Sofía?\",\"¿Qué paquetes combinados de día de campo podemos prefigurar en la Ruta 259?\"]", "[\"Presentar el proyecto a los colegas de célula.\",\"Mapear circuito de la Ruta 259.\",\"Analizar normativas de turismo rural y de recreación al aire libre.\"]", "[{\"id\":1,\"texto\":\"Presentar el Master Plan del laberinto ante la célula\",\"done\":false},{\"id\":2,\"texto\":\"Mapear sinergias con Tambo, Margherita y Lucero\",\"done\":false},{\"id\":3,\"texto\":\"Analizar requisitos de habilitación de turismo rural\",\"done\":false}]", ["noelia"]],
        ["laberin-05", "laberin", 5, "Supervisión de vivero de esquejes y parcela testigo", "ter", "Chacra Austin (Ruta 259 km 4)", "2026-10-19", "09:30", "12:30", "programada", "Verificar la implantación de la parcela testigo con enmienda orgánica y supervisar el enraizamiento de los primeros lotes de esquejes bajo riego por goteo.", "[\"¿Qué brotación muestran los esquejes con enraizante de sauce?\",\"¿Cómo responde la humedad del suelo tras la aplicación de abono de oveja?\"]", "[\"Medir desarrollo de brotes en la parcela testigo.\",\"Inspeccionar sistema de riego y presión de goteros.\",\"Controlar estado del cerco anti-liebres.\",\"Tomar registros fotográficos.\"]", "[{\"id\":1,\"texto\":\"Medir longitud de brotes en parcela testigo\",\"done\":false},{\"id\":2,\"texto\":\"Controlar funcionamiento de goteros y presión de agua\",\"done\":false},{\"id\":3,\"texto\":\"Inspeccionar cerco con malla anti-liebres\",\"done\":false},{\"id\":4,\"texto\":\"Verificar avance del salón de té/eventos\",\"done\":false}]", ["adria","noelia"]],
        ["laberin-06", "laberin", 6, "Estructuración de servicios puente: casa de té y cabalgatas", "ind", "Turismo", "2026-10-28", "14:00", "16:00", "programada", "Estructurar la propuesta comercial de los servicios puente: apertura de la casa de té de campo, visitas al predio y paseos a caballo para la temporada 2027.", "[\"¿Qué menú de repostería y té artesanal ofrecerá Marta?\",\"¿Qué tarifa y protocolo tendrán las cabalgatas de faldeo guiadas por Joaquín?\"]", "[\"Armar la carta gastronómica de la casa de té.\",\"Definir circuito y seguridad de cabalgatas.\",\"Redactar ficha comercial de actividades de campo.\"]", "[{\"id\":1,\"texto\":\"Definir propuesta de repostería casera y té de campo\",\"done\":false},{\"id\":2,\"texto\":\"Trazar el circuito de cabalgatas de faldeo con los 6 caballos\",\"done\":false},{\"id\":3,\"texto\":\"Fijar tarifas de la casa de té y paseos ecuestres\",\"done\":false},{\"id\":4,\"texto\":\"Redactar deslinde de responsabilidad para cabalgatas\",\"done\":false}]", ["noelia"]],
        ["laberin-07", "laberin", 7, "Prefactibilidad económica y presupuesto por etapas", "ind", "Turismo", "2026-11-02", "09:30", "12:00", "programada", "Consolidar la matriz económica del proyecto a 3 años, cerrar el presupuesto por etapas y preparar el dossier para inversores o financiamiento productivo.", "[\"¿Cuál es la inversión neta de la Fase 1 (vivero y salón de té)?\",\"¿En qué mes proyectamos el punto de equilibrio operativo?\"]", "[\"Cerrar la planilla de costos y flujo de fondos.\",\"Redactar el resumen ejecutivo de prefactibilidad.\",\"Preparar presentación visual para la ronda de negocios.\"]", "[{\"id\":1,\"texto\":\"Consolidar la planilla de costos a 3 años\",\"done\":false},{\"id\":2,\"texto\":\"Redactar el resumen ejecutivo de prefactibilidad\",\"done\":false},{\"id\":3,\"texto\":\"Armar lámina visual del Master Plan para inversores\",\"done\":false},{\"id\":4,\"texto\":\"Preparar discurso de presentación de 3 minutos\",\"done\":false}]", ["adria","noelia"]],
        ["laberin-08", "laberin", 8, "Distinción, resultados y rueda de negocios en Melipal", "cie", "Centro Cultural Melipal", "2026-11-19", "10:00", "13:00", "programada", "Cierre plenario y rueda comercial con el sector turístico comarcal. Presentación del Master Plan ante agencias, prestadores, autoridades y prensa.", "[\"¿Qué alianzas o apoyos institucionales se concretan para la ejecución de la Fase 1?\"]", "[\"Presentar el Master Plan del laberinto en el stand.\",\"Ofrecer degustación de repostería de la futura casa de té.\",\"Cerrar al menos una carta de intención con el sector receptivo.\"]", "[{\"id\":1,\"texto\":\"Montar maqueta/lámina del Master Plan en el stand\",\"done\":false},{\"id\":2,\"texto\":\"Llevar plantines de ligustro y muestras de repostería casera\",\"done\":false},{\"id\":3,\"texto\":\"Cerrar al menos una alianza comercial en la rueda\",\"done\":false}]", ["leandro","adria","mariela","francisco","agustina","cesia","noelia"]],
        ["nire-01", "nire", 1, "Relevamiento en terreno y diagnóstico de predio", "ter", "Predio Altos de Nant y Fall", "2026-09-25", "09:30", "12:30", "programada", "Relevar in situ las 2 hectáreas, el sendero de circunvalación, la casita de descanso y el estado del camino de ripio de 1.500 m. Evaluar áreas de microflora y puntos de mayor silencio.", "[\"¿Dónde se siente el mayor silencio dentro del bosque?\",\"¿Cómo reacciona el suelo del callejón con lluvia?\",\"¿Qué microflora observamos en el sendero corto?\"]", "[\"Relevar medidas y recorrido del sendero.\",\"Evaluar puntos críticos del callejón de acceso.\",\"Validar disponibilidad de la casita y servicios.\"]", "[{\"id\":1,\"texto\":\"Fotografiar puntos críticos del acceso\",\"done\":false},{\"id\":2,\"texto\":\"Medir los tramos del sendero interno\",\"done\":false},{\"id\":3,\"texto\":\"Probar conectividad y equipamiento de la casita\",\"done\":false},{\"id\":4,\"texto\":\"Tomar muestras de líquenes y hojas de ñire\",\"done\":false}]", ["adria","noelia"]],
        ["nire-02", "nire", 2, "Estrategia de macrodestino y nodo Laguna La Zeta", "ind", "Turismo", "2026-10-02", "09:30", "12:00", "programada", "Definir el circuito periurbano en Laguna La Zeta para tener presencia activa y legitimada dentro del ejido municipal de Esquel, capturando turistas de tarde.", "[\"¿Qué rincón de La Zeta ofrece la menor contaminación sonora y mejor resguardo de viento?\",\"¿Cómo adaptamos los tiempos para turistas en tránsito en Esquel?\"]", "[\"Trazar el mapa del circuito La Zeta (máximo 1,5 km).\",\"Redactar la fundamentación de macrodestino para autoridades.\",\"Definir frecuencia de salidas semanales.\"]", "[{\"id\":1,\"texto\":\"Trazar el recorrido de La Zeta\",\"done\":false},{\"id\":2,\"texto\":\"Redactar la fundamentación institucional del doble nodo\",\"done\":false},{\"id\":3,\"texto\":\"Definir días y horarios de salidas en Esquel\",\"done\":false}]", ["noelia"]],
        ["nire-03", "nire", 3, "Estructuración del guion sensorial e inmersión", "ind", "Turismo", "2026-10-16", "09:30", "12:30", "programada", "Redactar el guion de la experiencia con las consignas sensoriales, ejercicios de respiración, micro-observación y tiempos de pausa.", "[\"¿Cómo rompemos el ritmo acelerado del turista en los primeros 10 minutos?\",\"¿Qué metáforas usamos para explicar los líquenes y el ñirantal?\"]", "[\"Escribir el guion de 5 estaciones.\",\"Estandarizar la bienvenida y cierre ceremonial.\",\"Incorporar el protocolo de recolección de infusión.\"]", "[{\"id\":1,\"texto\":\"Escribir las 5 estaciones del recorrido\",\"done\":false},{\"id\":2,\"texto\":\"Pautar los momentos de silencio absoluto\",\"done\":false},{\"id\":3,\"texto\":\"Diseñar la ceremonia de cierre con infusión caliente\",\"done\":false}]", ["adria","noelia"]],
        ["nire-04", "nire", 4, "Gestión de predios rurales y costeo (Célula 2)", "ter", "Célula 2 (Turismo)", "2026-10-23", "09:30", "12:00", "programada", "Encuentro grupal de la Célula 2 (Campo y gran superficie). Poner en común costos de mantenimiento rural, traslados, seguros de excursionistas y alianzas cruzadas en el corredor.", "[\"¿Cómo nos complementamos en el circuito de Nant y Fall y la Ruta 259?\",\"¿Podemos compartir transportes o derivar visitantes entre chacras?\"]", "[\"Completar matriz de costos fijos y variables.\",\"Identificar cruces con Viñas del Nant y Fall y Cascada.\",\"Validar seguro colectivo de turismo activo.\"]", "[{\"id\":1,\"texto\":\"Llevar la matriz de costos completa\",\"done\":false},{\"id\":2,\"texto\":\"Identificar al menos 2 cruces de derivación con la célula\",\"done\":false},{\"id\":3,\"texto\":\"Revisar pólizas de seguro de turismo activo\",\"done\":false}]", ["noelia"]],
        ["nire-05", "nire", 5, "Salida piloto y prueba de campo en La Zeta", "ter", "Laguna La Zeta", "2026-11-06", "09:30", "12:30", "programada", "Ejecutar el guion sensorial completo con público testigo para medir tiempos reales, silencios y recepción emocional.", "[\"¿Los participantes lograron desconectarse del celular?\",\"¿Qué estación resultó más emotiva?\",\"¿Cómo funcionó la infusión servida al final?\"]", "[\"Validar tiempos reales del guion.\",\"Recoger devoluciones sinceras de los participantes.\",\"Tomar fotografías de calidad para el banco de imágenes.\"]", "[{\"id\":1,\"texto\":\"Cronometrar cada parada del sendero\",\"done\":false},{\"id\":2,\"texto\":\"Registrar planilla de feedback de los asistentes\",\"done\":false},{\"id\":3,\"texto\":\"Probar logística de calentamiento de agua para infusión al aire libre\",\"done\":false}]", ["adria","noelia"]],
        ["nire-06", "nire", 6, "Turismo accesible familiar y souvenir botánico", "ind", "Turismo", "2026-11-10", "14:00", "16:00", "programada", "Formalizar la cápsula para familias con personas con discapacidad y terminar el prototipo del packaging de la infusión de hojas de ñire.", "[\"¿Qué adaptaciones requiere el sendero para paso asistido o personas con movilidad reducida?\",\"¿Cómo comunicamos la propuesta accesible con calidez y sin estigmatizar?\"]", "[\"Redactar la ficha de Turismo Accesible Familiar.\",\"Diseñar la etiqueta de la bolsita de té de ñire.\",\"Articular con la Dirección de Discapacidad / Inclusión.\"]", "[{\"id\":1,\"texto\":\"Redactar el protocolo para familias con miembros con discapacidad\",\"done\":false},{\"id\":2,\"texto\":\"Diseñar la etiqueta del souvenir botánico\",\"done\":false},{\"id\":3,\"texto\":\"Definir el método de secado y conservación de las hojas\",\"done\":false}]", ["noelia"]],
        ["nire-07", "nire", 7, "Ficha comercial y venta a receptivos y hoteles", "ind", "Turismo", "2026-11-16", "10:00", "12:30", "programada", "Cerrar tarifas, comisiones para agencias (15-20%) y armar el material gráfico/digital para recepciones de hoteles boutique de Esquel.", "[\"¿Cuánto le dejamos al recepcionista o agencia por derivación confirmada?\",\"¿Cuál es el canal y mensaje de reserva inmediata?\"]", "[\"Cerrar tarifario definitivo y comisiones.\",\"Imprimir fichas comerciales en alta calidad.\",\"Configurar WhatsApp Business con catálogo.\"]", "[{\"id\":1,\"texto\":\"Cerrar el tarifario final con comisiones\",\"done\":false},{\"id\":2,\"texto\":\"Redactar la ficha de una carilla para agencias\",\"done\":false},{\"id\":3,\"texto\":\"Listar los 5 hoteles boutique donde presentar la propuesta\",\"done\":false}]", ["adria","noelia"]],
        ["nire-08", "nire", 8, "Distinción, resultados y rueda de negocios en Melipal", "cie", "Centro Cultural Melipal", "2026-11-19", "10:00", "13:00", "programada", "Acto plenario y cierre del programa con el sector turístico comarcal. Presentación del producto ante agencias, prestadores y prensa.", "[\"¿Qué convenios comerciales quedan cerrados para el verano 2027?\"]", "[\"Cerrar al menos dos convenios de derivación con agencias u hoteles.\",\"Presentar el souvenir botánico en el stand.\"]", "[{\"id\":1,\"texto\":\"Confirmar asistencia al plenario\",\"done\":false},{\"id\":2,\"texto\":\"Llevar muestras de la infusión de ñire para degustación\",\"done\":false},{\"id\":3,\"texto\":\"Cerrar al menos una alianza comercial en la rueda\",\"done\":false}]", ["leandro","adria","mariela","francisco","agustina","cesia","noelia"]],
        ["truepat-01", "truepat", 1, "Diagnóstico en terreno, deconstrucción de marca y reposicionamiento de autor", "ind", "Oficina Turismo", "2026-09-21", "09:30", "11:30", "programada", "Deconstruir el nombre provisorio \"True Patagonia\" y acordar la nueva denominación de autor. Inventariar la red de contactos existente (maestras de telar en Melipal, hilanderas, chacras conocidas en Percy y Nahuelpan). Fijar el perfil de la persona pública de Cecilia.", "[\"¿Por qué el nombre en inglés aleja al público que busca identidad ancestral?\",\"¿Cómo resumimos la historia de Cecilia en 30 segundos de manera magnética?\",\"¿Cuáles son los 3 saberes que sí o sí deben estar en el retiro?\"]", "[\"Completar ficha de relevamiento de contactos de campo.\",\"Proponer 3 opciones de denominación de marca con anclaje patagónico.\",\"Definir público objetivo (mujeres 35-65 años, apasionadas del quehacer textil, turismo regenerativo y cultural).\"]", "[{\"id\":1,\"texto\":\"Mapear artesanas, hilanderas y predios rurales aliados\",\"done\":false},{\"id\":2,\"texto\":\"Definir nueva denominación de marca de autor\",\"done\":false},{\"id\":3,\"texto\":\"Diseñar perfil de la persona pública de Cecilia\",\"done\":false}]", ["mariela","noelia"]],
        ["truepat-02", "truepat", 2, "Curaduría del itinerario vivencial y diseño del guion emocional", "ind", "Taller Cecilia (Los Álamos)", "2026-09-30", "09:30", "11:30", "programada", "Diagramar el cronograma paso a paso del retiro de 4 días / 3 noches. Diseñar la curva dramática de la experiencia: alternancia de actividades manuales, tiempos de descanso, comidas tradicionales y momentos de asombro.", "[\"¿Cómo evitamos que la jornada de hilado resulte agotadora para quien nunca agarró un huso?\",\"¿En qué momento del día se produce la revelación del color en la olla de tintes?\",\"¿Qué historia de fogón compartimos a la noche?\"]", "[\"Redactar el guion cronológico del Día 1 al Día 4.\",\"Cronometrar tiempos de taller (máximo 3 horas de trabajo manual por jornada).\",\"Programar la Cápsula Full Day de Crochet y Naturaleza como producto complementario.\"]", "[{\"id\":1,\"texto\":\"Redactar guion paso a paso de las 4 jornadas\",\"done\":false},{\"id\":2,\"texto\":\"Establecer descansos y pausas sensoriales\",\"done\":false},{\"id\":3,\"texto\":\"Definir la cápsula de campo Patrones de Montaña y Crochet\",\"done\":false}]", ["noelia"]],
        ["truepat-03", "truepat", 3, "Prospección en territorio y acuerdos con anfitriones rurales", "ter", "Las Margaritas (Nahuelpan) y Percy", "2026-10-09", "10:00", "12:00", "programada", "Relevar in situ las instalaciones de Establecimiento Las Margaritas y evaluar la articulación entre emprendimientos de la misma cohorte. Visitar chacras ovinas aliadas para definir el espacio de esquila, demostración y almuerzo criollo.", "[\"¿Las Margaritas cuenta con capacidad para alojar o funciona mejor como locación de talleres y contacto con animales?\",\"¿Qué infraestructura básica de baños y resguardo de viento se requiere en Percy?\"]", "[\"Completar acta de acuerdo preliminar con Las Margaritas.\",\"Evaluar estado de accesos vehiculares para transfers de turistas.\",\"Determinar el canon diario por uso de instalaciones y atención campesina.\"]", "[{\"id\":1,\"texto\":\"Relevar predio Las Margaritas con Lorena Cogos\",\"done\":false},{\"id\":2,\"texto\":\"Inspeccionar chacras ovinas en Alto Río Percy\",\"done\":false},{\"id\":3,\"texto\":\"Fijar canon por uso de predio y atención campesina\",\"done\":false}]", ["mariela","noelia"]],
        ["truepat-04", "truepat", 4, "Costeo, punto de equilibrio y tarifario (Célula 4)", "ind", "Célula 4 (Melipal)", "2026-10-21", "14:30", "16:30", "programada", "Poner en común la estructura de costos de los paquetes receptivos y retiros. Calcular costos fijos y variables (alojamiento, transfers, insumos de telar/tintes, honorarios de artesanas campesinas, coordinación de Cecilia y comisión de agencia).", "[\"¿Cuál es el costo directo por persona y cuánto representa el honorario de facilitación de Cecilia?\",\"¿Qué precio final en dólares y pesos resiste el segmento ABC1 nacional e internacional?\",\"¿A partir de cuántos pasajeros se cubre el punto de equilibrio?\"]", "[\"Planilla de costeo integral terminada.\",\"Fijar punto de equilibrio en 4 pasajeros.\",\"Definir esquema de comisión para agencias de viajes (20% margen receptivo sobre tarifa neta).\"]", "[{\"id\":1,\"texto\":\"Completar matriz de costeo integral\",\"done\":false},{\"id\":2,\"texto\":\"Determinar punto de equilibrio (4 pasajeros)\",\"done\":false},{\"id\":3,\"texto\":\"Fijar tarifario B2C y tarifa neta B2B con 20% margen\",\"done\":false}]", ["noelia"]],
