    // 5. Sincronización inteligente en SQLite
    $dbSeedVersion = (int) $pdo->query("PRAGMA user_version")->fetchColumn();
    $TARGET_SEED_VERSION = 20260917;

    if ($dbSeedVersion < $TARGET_SEED_VERSION) {
        $pdo->beginTransaction();
        $checkReu = $pdo->prepare("SELECT estado, minuta_notas FROM lab_reuniones WHERE id = ?");
        $updReu = $pdo->prepare("UPDATE lab_reuniones SET numero_reunion = ?, titulo = ?, tipo = ?, lugar = ?, fecha = ?, hora_inicio = ?, hora_fin = ?, guia_consultor = ?, preguntas_clave = ?, objetivos = ?, checklist = ? WHERE id = ? AND estado = 'programada'");
        $insReuNew = $pdo->prepare("INSERT INTO lab_reuniones (id, proyecto_id, numero_reunion, titulo, tipo, lugar, fecha, hora_inicio, hora_fin, estado, guia_consultor, preguntas_clave, objetivos, checklist) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)");
        $delAsist = $pdo->prepare("DELETE FROM lab_reunion_asistentes WHERE reunion_id = ?");
        $insAsistNew = $pdo->prepare("INSERT OR IGNORE INTO lab_reunion_asistentes (reunion_id, consultor_id, rol) VALUES (?, ?, ?)");
        $validReuIds = [];
        foreach ($reunionesOficiales as $rRow) {
            $asistList = array_pop($rRow);
            $reuId = $rRow[0];
            $validReuIds[] = $reuId;
            $checkReu->execute([$reuId]);
            $existing = $checkReu->fetch(PDO::FETCH_ASSOC);
            if ($existing) {
                if ($existing['estado'] === 'programada') {
                    $updReu->execute([$rRow[2], $rRow[3], $rRow[4], $rRow[5], $rRow[6], $rRow[7], $rRow[8], $rRow[10], $rRow[11], $rRow[12], $rRow[13], $reuId]);
                    $delAsist->execute([$reuId]);
                    foreach ($asistList as $consId) { $insAsistNew->execute([$reuId, $consId, 'asistente']); }
                }
            } else {
                $insReuNew->execute($rRow);
                foreach ($asistList as $consId) { $insAsistNew->execute([$reuId, $consId, 'asistente']); }
            }
        }
        if (!empty($validReuIds)) {
            $inClause = implode(',', array_fill(0, count($validReuIds), '?'));
            $stmtObs = $pdo->prepare("SELECT id FROM lab_reuniones WHERE estado = 'programada' AND id NOT IN ($inClause)");
            $stmtObs->execute($validReuIds);
            $obsoletas = $stmtObs->fetchAll(PDO::FETCH_COLUMN);
            foreach ($obsoletas as $obsId) {
                $delAsist->execute([$obsId]);
                $pdo->prepare("DELETE FROM lab_reuniones WHERE id = ?")->execute([$obsId]);
            }
        }
        $pdo->exec("PRAGMA user_version = $TARGET_SEED_VERSION");
        $pdo->commit();
    }
